local config = {
  ui_story_5029_50290001_1_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5029_50290001_2_dialog_content = "いつもはにぎやかな港が、\n赤子の呪文と共に深い眠りにつく時…",
