  ui_story_5029_50290001_6_dialog_content = "柔らかな刺激がゆっくりと髪から全身へ流れ、\nつま先まで行き届くのを感じていることでしょう。",
  ui_story_5029_50290001_7_dialog_content = "これまでに経験したことのない、ゆったりとした気分に包まれ…\nあなたの心はこの上なく穏やかになるでしょう。",
  ui_story_5029_50290001_8_dialog_content = "それでは…<color=#793f76>深呼吸をしてください</color>。",
  ui_story_5029_50290001_9_option_content = "吸って、吐く…",
  ui_story_5029_50290001_10_option_content = "吐いて、吸う…",
  ui_story_5029_50290001_11_dialog_content = "素晴らしい。呼吸がお上手ですね。\n以前、ここで動物のような鳴き声を上げた方がいまして。",
  ui_story_5029_50290001_12_dialog_content = "ああ、そんなことは重要ではありませんね。\n今、あなたは…",
  ui_story_5029_50290001_13_dialog_content = "意識が遠くなり始めているでしょう。\nですが、心配することはありません。\nあなたはハッキリと目覚めています。",
  ui_story_5029_50290001_14_dialog_content = "そう、ハッキリと心に浮かぶはずです…",
  ui_story_5029_50290001_15_dialog_content = "あなたが選ぶ道の先、運命を手繰り、\n結末をうかがいたいと思った、その相手を…",
  ui_story_5029_50290001_16_dialog_content = "素晴らしい…今、あなたの頭の中には\nその人物の姿が浮かんでいることでしょう。",
  ui_story_5029_50290001_17_dialog_content = "まっすぐで勇敢な、人々の前に立って進む、\n<color=#793f76>まばゆい陽の光</color>でしょうか？",
  ui_story_5029_50290001_18_dialog_content = "優しく親切で、いつも側に居てくれる、\n<color=#793f76>やわらかな月の光</color>でしょうか？",
  ui_story_5029_50290001_19_dialog_content = "それとも、利発で活力にあふれ、イタズラ心のある、\n<color=#793f76>きらめく星の光</color>でしょうか？",
  ui_story_5029_50290001_20_dialog_content = "僕はあなたが絡まった糸の数本を手繰り寄せる、\nお手伝いをするだけ。\n答えをお出しすることはできません。",
  ui_story_5029_50290001_21_dialog_content = "むろん、感情や発想というものは、\n凡人にとらえられるものではありません。\nこれはただの、たとえ話…",
  ui_story_5029_50290001_22_dialog_content = "頭の中で、魅惑的に感じるものを求め続ければ…",
  ui_story_5029_50290001_23_dialog_content = "それが進むべき方向を\n指し示してくれることでしょう。",
  ui_story_5029_50290001_24_dialog_content = "さあ、あなたは今からこの占いの魂となります。",
  ui_story_5029_50290001_25_dialog_content = "物語の作者、夢を織りなす者、\n運命の主宰者となるのです。",
  ui_story_5029_50290001_26_dialog_content = "ただ…これだけは覚えておいてください。\n落ち着いて、取り乱さないように。",
  ui_story_5029_50290001_27_dialog_content = "<color=#793f76>冷静さ</color>と<color=#793f76>集中力</color>を保つことが、\n占いにおいては肝要…",
  ui_story_5029_50290001_28_dialog_content = "冷静さを失えば、そこまで成し遂げたこともすべて、\n時の洪水が一切の迷いなく押し流すでしょう。",
  ui_story_5029_50290001_29_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5029_50290001_30_dialog_content = "時間です。",
  ui_story_5029_50290001_31_dialog_content = "それでは、1つ目の選択を。\n目の前にある3枚のカードの中から<color=#793f76>1枚</color>お選びください。",
  ui_story_5029_50290001_32_dialog_content = "それが未来への旅路を開くカギとなります。",
  ui_story_5029_50290001_33_option_content = "始原のカード――太陽",
  ui_story_5029_50290001_34_dialog_content = "まばゆい陽の光…\n誰もがそれを直視できるわけではありません。",
  ui_story_5029_50290001_35_dialog_content = "フフフ…これがあなたの選択ですか？",
