  ui_story_5029_50290001_38_dialog_content = "奇跡は、すぐ側にあるのです。",
  ui_story_5029_50290001_39_option_content = "始原のカード――月",
  ui_story_5029_50290001_40_dialog_content = "優しい月の光ですか。\n誰もが月をなでられるわけではありません…",
  ui_story_5029_50290001_41_dialog_content = "フフフ…これがあなたの選択ですか？",
  ui_story_5029_50290001_42_dialog_content = "素晴らしい始まりとなるといいですね。\nあなたの望む答えが見つかることを願っています。",
