  ui_story_5029_50290001_44_dialog_content = "奇跡は、すぐ側にあるのです。",
  ui_story_5029_50290001_45_dialog_content = "始原のカード――星",
  ui_story_5029_50290001_46_dialog_content = "きらめく星の光ですか。\n誰もが星のもつ影を知ることができるわけではありません…",
  ui_story_5029_50290001_47_dialog_content = "フフフ…これがあなたの選択ですか？",
  ui_story_5029_50290001_48_dialog_content = "素晴らしい始まりとなるといいですね。\nあなたの望む答えが見つかることを願っています。",
  ui_story_5029_50290001_49_dialog_content = "どうあろうと、忘れてはいけませんよ…",
  ui_story_5029_50290001_50_dialog_content = "奇跡は、すぐ側にあるのです。",
  ui_story_5029_50290001_51_dialog_content = "何も選ばない",
  ui_story_5029_50290001_52_dialog_content = "どうされましたか、お客様。",
