  ui_story_5029_50290001_55_dialog_content = "未来に隠された答えを探り出し、\n己の運命を手の内に収めたいとは思わないのですか？",
  ui_story_5029_50290001_56_dialog_content = "運命は、いつでも僕自身が握ってるんだ。",
  ui_story_5029_50290001_57_dialog_content = "じつに情熱的なお言葉です。\n闇深き夜にも、熱を帯びた光がともりそうなほどに。",
  ui_story_5029_50290001_58_dialog_content = "そこまで真剣にとらえられることはありませんよ。\nこれはただの幻…ちょっとしたマジックショーに過ぎません。",
  ui_story_5029_50290001_59_dialog_content = "望んだままの美しい夢を見られるとでも、お考えください。",
  ui_story_5029_50290001_60_dialog_content = "僕には分かる気がするんだ…\nカードを選んだ後、どういうことになるのか。",
  ui_story_5029_50290001_61_dialog_content = "正解を選んでいけば、\n必ず美しい結末にたどり着くことは、分かってる。",
  ui_story_5029_50290001_62_dialog_content = "海辺の灯台の明かり、荒野の夕暮れ、\n人混みの中の静けさ…",
  ui_story_5029_50290001_63_dialog_content = "でも、それは全部、\nつかの間の、はかない幻なんだ。",
  ui_story_5029_50290001_64_dialog_content = "夢におぼれるよりも、僕は現実の暮らしの中にある\n選択の機会一つ一つを大切にしたいよ。",
  ui_story_5029_50290001_65_dialog_content = "後悔することも、\n途方に暮れることもあるだろうけど…",
  ui_story_5029_50290001_66_dialog_content = "そういう経験をすることで、自分が本当にするべきことが何か、\nだんだん分かってくるんだと思う。",
  ui_story_5029_50290001_67_dialog_content = "それこそ、僕が本当に望む未来だよ。",
  ui_story_5029_50290001_68_dialog_content = "そろそろ…現実に戻らないと。",
  ui_story_5029_50290001_69_dialog_content = "それがお客様の望みとあらば…\n僕も無理にとは申しません。",
  ui_story_5029_50290001_70_dialog_content = "完璧なパフォーマンスの実現は、\nお客様の協力があってこそ。",
  ui_story_5029_50290001_71_dialog_content = "どうやら、また次の機会とするしかなさそうですね。",
  ui_story_5029_50290001_72_dialog_content = "ですが、そうですね…\n<color=#793f76>彼女たち</color>なら、あなたの助けになってくれるやも…",
  ui_story_5029_50290001_73_dialog_content = "待って！",
  ui_story_5029_50290001_74_dialog_content = "「彼女たち」って…？",
