  ui_story_5029_50290002_1_dialog_content = "PlayerName。",
  ui_story_5029_50290002_2_dialog_content = "…",
  ui_story_5029_50290002_3_dialog_content = "私の声が聞こえる？",
  ui_story_5029_50290002_4_dialog_content = "ずいぶん派手に転んだから…\n頭でもぶつけたかしら？",
  ui_story_5029_50290002_5_dialog_content = "PlayerName、しっかりして…",
  ui_story_5029_50290002_6_dialog_content = "近くに診療所があるかどうか、\n聞いてくるわ。",
  ui_story_5029_50290002_7_dialog_content = "いや…",
  ui_story_5029_50290002_8_dialog_content = "え？",
  ui_story_5029_50290002_9_option_content = "置いていかないで",
  ui_story_5029_50290002_10_dialog_content = "気がついたの？",
  ui_story_5029_50290002_11_dialog_content = "安心して。置き去りになどしないわ。",
  ui_story_5029_50290002_12_dialog_content = "だから…手を放してもらえる？",
  ui_story_5029_50290002_13_dialog_content = "あ…",
  ui_story_5029_50290002_14_option_content = "医者はいやだ",
  ui_story_5029_50290002_15_dialog_content = "気がついた？\nその様子なら、大きな問題はなさそうね。",
  ui_story_5029_50290002_16_dialog_content = "でも、お医者様を怖がるとは思わなかったわ。",
  ui_story_5029_50290002_17_dialog_content = "でも、時間があるのなら、\n検査してもらった方がいいわね。",
  ui_story_5029_50290002_18_dialog_content = "あ、そうじゃなくて…",
  ui_story_5029_50290002_19_option_content = "僕にかまわないで",
  ui_story_5029_50290002_20_dialog_content = "…私も好き好んでかまっているわけではないわ。",
  ui_story_5029_50290002_21_dialog_content = "ここは白夜城に統治されている地。\n道端のガラクタを片付けるのは、私の当然の職権。",
  ui_story_5029_50290002_22_dialog_content = "気がついたなら、後は勝手にしなさい。",
