  ui_story_5029_50290002_24_option_content = "ぶたないで",
  ui_story_5029_50290002_25_dialog_content = "オホン…今、何と言ったかしら？",
  ui_story_5029_50290002_26_dialog_content = "どうして理由もなく、私があなたを叩くの？",
  ui_story_5029_50290002_27_dialog_content = "あ…",
  ui_story_5029_50290002_28_dialog_content = "ごめん！",
  ui_story_5029_50290002_29_dialog_content = "まだ夢の中だと思ってて…\n何か変なことを言っちゃってたら、気にしないで。",
  ui_story_5029_50290002_30_dialog_content = "夢…？",
  ui_story_5029_50290002_31_dialog_content = "まあ、いいわ、何でもないのなら。\n自分で立ち上がれる？",
  ui_story_5029_50290002_32_dialog_content = "…",
  ui_story_5029_50290002_33_dialog_content = "カレン、ここにいたのね！\nあら、PlayerNameも？",
  ui_story_5029_50290002_34_dialog_content = "地面に寝転がって何してるの？\nお腹は冷やさないようにね！",
  ui_story_5029_50290002_35_dialog_content = "さ、手を貸してあげるから立って。",
  ui_story_5029_50290002_36_option_content = "あ、ありがとう！",
  ui_story_5029_50290002_37_dialog_content = "ちょっと手を貸しただけでしょ。\nお礼なんていいのよ。",
  ui_story_5029_50290002_38_option_content = "自分で立てるよ",
  ui_story_5029_50290002_39_dialog_content = "そう？分かったわ。",
  ui_story_5029_50290002_39X1_dialog_content = "うっ…！腕をつっちゃった…",
  ui_story_5029_50290002_40_dialog_content = "強がるからよ…",
  ui_story_5029_50290002_41_dialog_content = "ところで…",
  ui_story_5029_50290002_42_dialog_content = "2人とも、ここで何してたの？",
  ui_story_5029_50290002_43_dialog_content = "実を言うと、よく覚えてないんだ。",
  ui_story_5029_50290002_44_dialog_content = "何も覚えていないの？本当に？",
  ui_story_5029_50290002_45_dialog_content = "うん…",
  ui_story_5029_50290002_46_dialog_content = "あの壁に貼ってある<color=#793f76>懸賞金の張り紙</color>を\nはがそうとして、うっかり転んだのよ。",
  ui_story_5029_50290002_47_dialog_content = "懸賞金の張り紙？",
  ui_story_5029_50290002_48_dialog_content = "そう。あなたが今、\n手に握りしめている、それよ。",
  ui_story_5029_50290002_49_dialog_content = "僕が手に…？\nあ、本当だ、何か紙を握ってる！？",
  ui_story_5029_50290002_50_dialog_content = "盗まれた家宝を取り戻すため、探偵求む。\n高額の懸賞金の用意あり。",
  ui_story_5029_50290002_51_dialog_content = "興味のある方は、張り紙をはがせば\n担当の者より直接連絡する。",
  ui_story_5029_50290002_52_dialog_content = "本当だわ、賞金つきの依頼ね。\n金額も高そう！？",
  ui_story_5029_50290002_53_dialog_content = "…これ、本当に僕がはがしたの？\nまったく記憶にないんだけど…",
  ui_story_5029_50290002_54_dialog_content = "一切迷わずはがしていたわ。",
  ui_story_5029_50290002_55_dialog_content = "でも僕、質の悪い探偵小説を\n読んだことがあるぐらいで、\n本物の探偵の仕事なんてやったことないよ。",
  ui_story_5029_50290002_56_dialog_content = "一体何を思って、はがしたんだろう…？",
  ui_story_5029_50290002_57_dialog_content = "きっと「高額の懸賞金」って文字に\n目がくらんだんでしょ。",
  ui_story_5029_50290002_58_dialog_content = "その気持ち、よく分かるわ！",
  ui_story_5029_50290002_59_dialog_content = "ハーバーシティは治安が良い、\n豊かな街だとずいぶん前から評判よ。\nこの街でそんな盗難事件が起こったというの？",
  ui_story_5029_50290002_60_dialog_content = "それに…なぜ領主に解決を依頼しないのかしら。",
  ui_story_5029_50290002_61_dialog_content = "領主には解決できない問題だから…？",
  ui_story_5029_50290002_62_dialog_content = "でも、絶好のチャンスじゃない！\n何をモタモタしてるの！？",
  ui_story_5029_50290002_63_dialog_content = "時間なら十分あるでしょ。\n探偵になれて、ついでに賞金を稼げるなら、いいんじゃない？",
  ui_story_5029_50290002_64_dialog_content = "調査することには賛成よ。\nただし、白夜城の名のもとに調査させてもらうわ。",
  ui_story_5029_50290002_65_dialog_content = "白夜城の属領で起こった事件である以上、\n犯人は白夜城の法律で裁かれる必要があるから。",
  ui_story_5029_50290002_66_dialog_content = "でも、それだと…懸賞金はもらえないんじゃ？",
  ui_story_5029_50290002_67_dialog_content = "…",
  ui_story_5029_50290002_68_dialog_content = "キャロ、プランB！今すぐ！",
  ui_story_5029_50290002_69_dialog_content = "ルルル！",
  ui_story_5029_50290002_70_dialog_content = "あ、張り紙が…とられちゃった！",
  ui_story_5029_50290002_71_dialog_content = "やったね、キャロ！",
  ui_story_5029_50290002_72_dialog_content = "フィア！？どこから出てきたの！？\n…いつものことだけど…",
  ui_story_5029_50290002_73_option_content = "てっきり強盗かと…",
  ui_story_5029_50290002_74_dialog_content = "失礼でしょ、PlayerName！",
  ui_story_5029_50290002_74X1_dialog_content = "あたしのどこが強盗に見えるの！？",
  ui_story_5029_50290002_75_dialog_content = "あたしはあたしの珍獣PlayerNameが何を見てるのか、\n興味があっただけ！",
  ui_story_5029_50290002_76_option_content = "さすが珍獣マスター",
  ui_story_5029_50290002_77_dialog_content = "気配を消すのが上手だね。",
  ui_story_5029_50290002_78_dialog_content = "へへ、トーゼンでしょ！",
  ui_story_5029_50290002_79_dialog_content = "だから、あんたも捕まったんだしね～。",
  ui_story_5029_50290002_80_dialog_content = "さ、一体何を見てたのか、\n見せてもらおっと。",
  ui_story_5029_50290002_81_dialog_content = "分かったよ…でも、今度は驚かさないでね。",
  ui_story_5029_50290002_82_dialog_content = "あっ、懸賞金付きのお仕事！",
  ui_story_5029_50290002_83_dialog_content = "キャロ！あたしたち、すっごくラッキーだよ！\nこれからの旅費が何とかできそう！",
  ui_story_5029_50290002_84_dialog_content = "ルルル～！",
  ui_story_5029_50290002_85_dialog_content = "あのドケチ師匠、こんな遠くまで来るのに、\nお金なんかほとんどくれないんだから！",
  ui_story_5029_50290002_86_dialog_content = "おいしいものも食べられないし、面白いものがあっても遊べない…\nダメ師匠、今に見てなさい…！",
  ui_story_5029_50290002_87_dialog_content = "フィアは言いつけをやり遂げるだけじゃ終わらない！\nついでに大金を稼いじゃうから！",
  ui_story_5029_50290002_88_dialog_content = "ルルル～！",
  ui_story_5029_50290002_89_dialog_content = "フィア、まさか、この仕事を受けるつもり？",
  ui_story_5029_50290002_90_dialog_content = "よく読みなさい。遊びじゃないのよ。",
  ui_story_5029_50290002_91_dialog_content = "引き受ければ、正真正銘の犯罪者を\n相手にすることになるわ。",
  ui_story_5029_50290002_92_dialog_content = "え？あ、あたし…",
  ui_story_5029_50290002_93_dialog_content = "フ、フン…！バカにしないで！",
  ui_story_5029_50290002_94_dialog_content = "凶暴で気性の荒い動物だって手なずけられるんだよ。\n犯罪者ぐらい怖くないもん！！",
  ui_story_5029_50290002_95_dialog_content = "フィア、犯罪者と珍獣は別物だよ…",
  ui_story_5029_50290002_96_dialog_content = "PlayerNameまで、あたしをバカにする気？",
  ui_story_5029_50290002_97_dialog_content = "ふふ～ん…分かった！\nこの仕事、引き受ける気なんでしょ？",
  ui_story_5029_50290002_98_dialog_content = "だったら、<color=#793f76>公平に勝負</color>しよ！",
  ui_story_5029_50290002_99_dialog_content = "賞金は、犯人を見つけた人のものってことね？\nいいと思うわ！",
  ui_story_5029_50290002_100_dialog_content = "それなら、覚悟することね。",
  ui_story_5029_50290002_101_dialog_content = "私には、白夜城でそれなりの経験があるわ。",
  ui_story_5029_50290002_102_dialog_content = "え…じゃあ、僕は…？",
  ui_story_5029_50290002_103_dialog_content = "お待たせして申し訳ございません。",
  ui_story_5029_50290002_104_dialog_content = "私が張り紙に書かれている、連絡担当の者です。\nゼインと申します。",
  ui_story_5029_50290002_105_dialog_content = "皆様、お仕事をお引き受けいただけるのでしたら、\nどうぞ私について来てください。",
  ui_story_5029_50290003_1_dialog_content = "PlayerName。",
  ui_story_5029_50290003_2_dialog_content = "…",
  ui_story_5029_50290003_3_dialog_content = "PlayerName、脅かさないで。",
  ui_story_5029_50290003_4_dialog_content = "今までだって危機や災難だらけだったけど、\n全部乗り越えてきたでしょ！",
  ui_story_5029_50290003_5_dialog_content = "転んだぐらい、どうってことないわよね？",
  ui_story_5029_50290003_6_dialog_content = "あ、そうだわ。\n巨像に生命維持装置があったわね…",
  ui_story_5029_50290003_7_dialog_content = "PlayerName、待ってて。\n私が装置まで背負っていくから！",
  ui_story_5029_50290003_8_dialog_content = "きっと助かるわ！",
  ui_story_5029_50290003_9_dialog_content = "僕は…",
  ui_story_5029_50290003_10_dialog_content = "よかった、ようやく気がついたのね！",
  ui_story_5029_50290003_11_option_content = "恐い",
  ui_story_5029_50290003_12_dialog_content = "大丈夫よ、PlayerName。\n私がずっと側にいるわ。",
  ui_story_5029_50290003_13_dialog_content = "この街は安全よ。\nあなたは不注意で転んだだけ。",
  ui_story_5029_50290003_14_dialog_content = "怖がらなくていいのよ。\nもし何かあっても、私が守ってあげるから！",
  ui_story_5029_50290003_15_dialog_content = "あれ、僕は一体何を言ってるんだろ…？",
  ui_story_5029_50290003_16_option_content = "君が側にいてくれてよかった",
  ui_story_5029_50290003_17_dialog_content = "えっ？",
  ui_story_5029_50290003_18_dialog_content = "きゅ、急に何言ってるの？",
  ui_story_5029_50290003_19_dialog_content = "恥ずかしいじゃない…",
  ui_story_5029_50290003_20_dialog_content = "ええと、ぼ、僕…",
  ui_story_5029_50290003_21_option_content = "大丈夫だよ",
  ui_story_5029_50290003_22_dialog_content = "本当に？",
  ui_story_5029_50290003_23_dialog_content = "頭は痛まない？\n身体はどこか、具合が悪くない？",
  ui_story_5029_50290003_24_dialog_content = "何も異常はないよ、大丈夫だ。\nただ…",
  ui_story_5029_50290003_25_option_content = "君には関係ない",
  ui_story_5029_50290003_26_dialog_content = "えっ…？",
  ui_story_5029_50290003_27_dialog_content = "転んだせいで、\n性格が悪くなったのかしら。",
  ui_story_5029_50290003_28_dialog_content = "もう1度転んだら、もとに戻る？",
  ui_story_5029_50290003_29_dialog_content = "えっ…バイス？何をするの？",
  ui_story_5029_50290003_30_dialog_content = "ちょっと、話を聞いて…",
  ui_story_5029_50290003_31_dialog_content = "僕、夢を見てたみたいなんだ。",
  ui_story_5029_50290003_32_dialog_content = "もし変なことを言ってたとしても、\n絶対に気にしないで…",
  ui_story_5029_50290003_33_dialog_content = "分かったわ。\nあなたが無事ならそれでいいの。",
  ui_story_5029_50290003_34_dialog_content = "とにかく、地面に転がってたら冷えるわよ。",
  ui_story_5029_50290003_35_dialog_content = "ほら、起こしてあげる。\n気を付けて。",
  ui_story_5029_50290003_36_dialog_content = "ありがとう…",
  ui_story_5029_50290003_37_dialog_content = "バイス、どうしてここにいるの？\n美術館へ行って審美眼を養うと言っていなかった？",
  ui_story_5029_50290003_38_dialog_content = "アハハ…途中で思わぬものを見たから…",
  ui_story_5029_50290003_39_dialog_content = "あら？PlayerNameも一緒…？",
  ui_story_5029_50290003_40_dialog_content = "顔色が悪いようだけれど、何かあった？",
  ui_story_5029_50290003_41_option_content = "大したことじゃないよ",
  ui_story_5029_50290003_42_dialog_content = "カレンもいるなら、もう安心だね。",
  ui_story_5029_50290003_43_dialog_content = "安心して。ハーバーシティはもともと安全よ。",
  ui_story_5029_50290003_44_option_content = "この街のせいだ",
  ui_story_5029_50290003_45_dialog_content = "ハーバーシティの道って、ちゃんと舗装してるのかな…\nおかげで転んじゃったよ。",
  ui_story_5029_50290003_45X1_dialog_content = "平らできれいに整っているわ。\n道のせいだと思っているの？",
  ui_story_5029_50290003_45X2_dialog_content = "（カレン、不機嫌になった…？\nそうか、ここは白夜城の属領だった…早く、話題を変えよう）",
  ui_story_5029_50290003_46_dialog_content = "突然、思い出したんだけど…\nさっきまで、夢を見てたみたいなんだ。",
  ui_story_5029_50290003_47_dialog_content = "ここで自分が何をしてたか、\n忘れちゃったみたいで…",
  ui_story_5029_50290003_48_dialog_content = "えっ？忘れたの？",
  ui_story_5029_50290003_49_dialog_content = "さっき、壁に貼ってある<color=#793f76>懸賞金の張り紙</color>を見て、\n帰りの旅費を稼ぐって言い出して…",
  ui_story_5029_50290003_50_dialog_content = "張り紙をはがそうとしたら、\nふらついて転んだのよ。",
  ui_story_5029_50290003_51_dialog_content = "懸賞金の張り紙?",
  ui_story_5029_50290003_52_dialog_content = "ええ、PlayerNameが手に握ってるでしょ。",
  ui_story_5029_50290003_53_dialog_content = "僕が手に…？\nあ、本当だ、何か紙を握ってる！？",
  ui_story_5029_50290003_54_dialog_content = "盗まれた家宝を取り戻すため、探偵求む。\n高額の懸賞金の用意あり。",
  ui_story_5029_50290003_55_dialog_content = "興味のある方は、張り紙をはがせば\n担当の者より直接連絡する。",
  ui_story_5029_50290003_56_dialog_content = "…これ、本当に僕がはがしたの？\nまったく記憶にないんだけど…",
  ui_story_5029_50290003_57_dialog_content = "私がここを通りかかった時には、\nすごく嬉しそうだったわよ。",
  ui_story_5029_50290003_58_dialog_content = "私まで引き留められて、\n「高額」ってどのぐらいだろうって、しばらく騒いでたわ。",
  ui_story_5029_50290003_59_dialog_content = "でも僕、質の悪い探偵小説を\n読んだことがあるぐらいで、\n本物の探偵の仕事なんてやったことないよ。",
  ui_story_5029_50290003_60_dialog_content = "どうせ私たちには時間があるんだから、\n探偵になって、ついでに賞金を稼いでもいいんじゃない？",
  ui_story_5029_50290003_61_dialog_content = "ハーバーシティは治安が良い、\n豊かな街だとずいぶん前から評判よ。\nこの街でそんな盗難事件が起こったというの？",
  ui_story_5029_50290003_62_dialog_content = "それに…なぜ領主に解決を依頼しないのかしら。",
  ui_story_5029_50290003_63_dialog_content = "領主には解決できない問題だから…？",
  ui_story_5029_50290003_64_dialog_content = "白夜城の属領で起こった事件であるからには、\n私も見て見ぬふりはできないわ。",
  ui_story_5029_50290003_65_dialog_content = "白夜城の名のもとに、\n犯人は白夜城の法律で裁かれなければ。",
  ui_story_5029_50290003_66_dialog_content = "でも、それだと…懸賞金はもらえないんじゃ？",
  ui_story_5029_50290003_67_dialog_content = "…",
  ui_story_5029_50290003_68_dialog_content = "キャロ、プランC！今すぐ！",
  ui_story_5029_50290003_69_dialog_content = "ルルル！",
  ui_story_5029_50290003_70_dialog_content = "あ、張り紙が…とられちゃった！",
  ui_story_5029_50290003_71_dialog_content = "やったね、キャロ！",
  ui_story_5029_50290003_72_dialog_content = "フィア！？どこから出てきたの！？\n…いつものことだけど…",
  ui_story_5029_50290003_73_option_content = "てっきり強盗かと…",
  ui_story_5029_50290003_74_dialog_content = "失礼でしょ、PlayerName！",
  ui_story_5029_50290003_74X1_dialog_content = "あたしのどこが強盗に見えるの！？",
  ui_story_5029_50290003_75_dialog_content = "あたしはあたしの珍獣PlayerNameが何を見てるのか、\n興味があっただけ！",
  ui_story_5029_50290003_76_option_content = "さすが珍獣マスター",
  ui_story_5029_50290003_77_dialog_content = "気配を消すのが上手だね。",
  ui_story_5029_50290003_78_dialog_content = "へへ、トーゼンでしょ！",
  ui_story_5029_50290003_79_dialog_content = "だから、あんたも捕まったんだしね～。",
  ui_story_5029_50290003_80_dialog_content = "さ、一体何を見てたのか、\nあたしも見せてもらおうかな。",
  ui_story_5029_50290003_81_dialog_content = "分かったよ…でも、今度は驚かさないでね。",
  ui_story_5029_50290003_82_dialog_content = "あっ、懸賞金付きのお仕事！",
  ui_story_5029_50290003_83_dialog_content = "キャロ！あたしたち、すっごくラッキーだよ！\nこれからの旅費が何とかできそう！",
  ui_story_5029_50290003_84_dialog_content = "ルルル～！",
  ui_story_5029_50290003_85_dialog_content = "あのドケチ師匠、こんな遠くまで来るのに、\nお金なんかほとんどくれないんだから！",
  ui_story_5029_50290003_86_dialog_content = "おいしいものも食べられないし、面白いものがあっても遊べない…\nダメ師匠、今に見てなさい…！",
  ui_story_5029_50290003_87_dialog_content = "フィアは言いつけをやり遂げるだけじゃ終わらない！\nついでに大金を稼いじゃうから！",
  ui_story_5029_50290003_88_dialog_content = "ルルル～！",
  ui_story_5029_50290003_89_dialog_content = "フィア、まさか、この仕事を受けるつもり？",
  ui_story_5029_50290003_90_dialog_content = "よく読みなさい。遊びじゃないのよ。",
  ui_story_5029_50290003_91_dialog_content = "引き受ければ、正真正銘の犯罪者を\n相手にすることになるわ。",
  ui_story_5029_50290003_92_dialog_content = "あ、あたしは…",
  ui_story_5029_50290003_93_dialog_content = "フ、フン…！バカにしないで！",
  ui_story_5029_50290003_94_dialog_content = "凶暴で気性の荒い動物だって手なずけられるんだよ。\n犯罪者ぐらい怖くないもん！！",
  ui_story_5029_50290003_95_dialog_content = "フィア、犯罪者と珍獣は別物だよ…",
  ui_story_5029_50290003_96_dialog_content = "PlayerNameまで、あたしをバカにする気？",
  ui_story_5029_50290003_97_dialog_content = "ふふ～ん…分かった！\nこの仕事、引き受ける気なんでしょ？",
  ui_story_5029_50290003_98_dialog_content = "だったら、<color=#793f76>公平に勝負</color>しよ！",
  ui_story_5029_50290003_99_dialog_content = "賞金は、犯人を見つけた人のものってことね？\nいいと思うわ！",
  ui_story_5029_50290003_100_dialog_content = "それなら、覚悟することね。",
  ui_story_5029_50290003_101_dialog_content = "私には、白夜城でそれなりの経験があるわ。",
  ui_story_5029_50290003_102_dialog_content = "え…じゃあ、僕は…？",
  ui_story_5029_50290003_103_dialog_content = "お待たせして申し訳ございません。",
  ui_story_5029_50290003_104_dialog_content = "私が張り紙に書かれている、連絡担当の者です。\nゼインと申します。",
  ui_story_5029_50290003_105_dialog_content = "皆様、お仕事をお引き受けいただけるのでしたら、\nどうぞ私について来てください。",
  ui_story_5029_50290004_1_dialog_content = "PlayerName！",
  ui_story_5029_50290004_2_dialog_content = "…",
  ui_story_5029_50290004_3_dialog_content = "ううっ、PlayerName…\n話もできなくなっちゃったの？",
  ui_story_5029_50290004_4_dialog_content = "キャロ、どうしよう…？",
  ui_story_5029_50290004_5_dialog_content = "ルル！",
  ui_story_5029_50290004_6_dialog_content = "そうだよ、あたしは珍獣マスター！",
  ui_story_5029_50290004_7_dialog_content = "こういう時こそ、専門家としての腕を見せなきゃ！",
  ui_story_5029_50290004_8_dialog_content = "確か師匠のノートに、\n陸の珍獣用の気付け薬の作り方が書いてあったっけ…？",
  ui_story_5029_50290004_8X1_dialog_content = "空の末裔にも効くよね？",
  ui_story_5029_50290004_9_dialog_content = "あ、あった！\nええと…気付けには、キャロの人工呼吸が必要？",
  ui_story_5029_50290004_10_dialog_content = "ル…？",
  ui_story_5029_50290004_11_dialog_content = "ゴホッゴホッ…",
  ui_story_5029_50290004_12_dialog_content = "もう！やっと気がついた！？",
  ui_story_5029_50290004_13_option_content = "フィアのおかげだ",
  ui_story_5029_50290004_14_dialog_content = "ふふふ、お礼はいらないよ！",
  ui_story_5029_50290004_15_dialog_content = "あんたはあたしが苦労して捕まえた珍獣だもん。\nお世話するのは、当然の義務だから！",
  ui_story_5029_50290004_16_dialog_content = "あ、そうだ、キャロも手伝ってくれたんだよ！",
  ui_story_5029_50290004_17_dialog_content = "ル～！",
  ui_story_5029_50290004_18_option_content = "だいぶ良くなった",
  ui_story_5029_50290004_19_dialog_content = "トーゼンでしょ！",
  ui_story_5029_50290004_20_dialog_content = "あたしとキャロがいるんだから、\n大丈夫に決まってる！",
  ui_story_5029_50290004_21_dialog_content = "ルルル！",
  ui_story_5029_50290004_22_option_content = "とどめを刺す気？",
  ui_story_5029_50290004_23_dialog_content = "PlayerName…",
  ui_story_5029_50290004_24_dialog_content = "あたしもキャロも好意で助けてあげてるの！\n恩知らずにもほどがあるよ！",
  ui_story_5029_50290004_25_dialog_content = "フン！空の末裔なんて、大して飼育する価値なさそう！\nこんなんだったら、暗鬼を飼ってた方がマシだよ！",
  ui_story_5029_50290004_26_dialog_content = "ルルル！",
  ui_story_5029_50290004_27_option_content = "キャロ、来ないで！",
  ui_story_5029_50290004_28_dialog_content = "イヤならイヤでいいけど、\nいきなり大声出さないでよ。",
  ui_story_5029_50290004_29_dialog_content = "でも、その様子なら元気そうだね。\n確かにキャロの手助けはいらないかな。",
  ui_story_5029_50290004_30_dialog_content = "ルルル～。",
  ui_story_5029_50290004_31_dialog_content = "さっきのは…全部、夢？",
  ui_story_5029_50290004_32_dialog_content = "夢なんて見てたの？\n転んでからそんなに時間経ってないよ？",
  ui_story_5029_50290004_33_dialog_content = "空の末裔って、白昼夢を見やすいとか？\nううん…それなら大変！ちゃんと記録しておかなきゃ。",
  ui_story_5029_50290004_34_dialog_content = "ちょっと、そんなこと記録しなくていいよ…",
  ui_story_5029_50290004_35_dialog_content = "あら、PlayerName？",
  ui_story_5029_50290004_36_dialog_content = "地面に寝転がって何してるの？\nお腹は冷やさないようにね！",
  ui_story_5029_50290004_37_dialog_content = "さ、手を貸してあげるから立って。",
  ui_story_5029_50290004_38_option_content = "あ、ありがとう！",
  ui_story_5029_50290004_39_dialog_content = "ちょっと手を貸しただけでしょ。\nお礼なんていいのよ。",
  ui_story_5029_50290004_40_option_content = "自分で立てるよ",
  ui_story_5029_50290004_41_dialog_content = "そう？分かったわ。",
  ui_story_5029_50290004_41X1_dialog_content = "うっ…！腕をつっちゃった…",
  ui_story_5029_50290004_42_dialog_content = "強がるからよ…",
  ui_story_5029_50290004_43_dialog_content = "「空の末裔は、女性に会うと緊張する…」",
  ui_story_5029_50290004_44_dialog_content = "あら？フィアちゃん、\nPlayerNameの記録を作ってるの？",
  ui_story_5029_50290004_45_dialog_content = "そうだよ！珍獣の生態とか、表現方法とかが分かってないと\nきちんとコミュニケーションがとれないもん。",
  ui_story_5029_50290004_46_dialog_content = "僕は緊張なんてしてないよ！",
  ui_story_5029_50290004_47_dialog_content = "そう？それはいいけど…\n手に握りしめてるのは何？",
  ui_story_5029_50290004_48_dialog_content = "え？言われるまで僕も気付かなかったよ…\n何かの紙かな？",
  ui_story_5029_50290004_49_dialog_content = "PlayerNameはさっき、\nそれを壁からはがそうとしてたんだよ。",
  ui_story_5029_50290004_49X1_dialog_content = "で、力を入れ過ぎて転んだみたい。",
  ui_story_5029_50290004_50_dialog_content = "そんなに気になることでも\n書いてあったのかな？",
  ui_story_5029_50290004_51_dialog_content = "あたしにも早く見せて！",
  ui_story_5029_50290004_52_dialog_content = "気を付けて、破れちゃうよ…",
  ui_story_5029_50290004_53_dialog_content = "<color=#828282>ヒュゥ――</color>",
  ui_story_5029_50290004_54_dialog_content = "あっ…風が！",
  ui_story_5029_50290004_55_dialog_content = "キャロ、プランA！今すぐ！",
  ui_story_5029_50290004_56_dialog_content = "ルルル！",
  ui_story_5029_50290004_57_dialog_content = "ちょっと待って。その必要はなさそうよ。\n誰かが拾ってくれたわ。",
  ui_story_5029_50290004_58_dialog_content = "あなたたちだったの？",
  ui_story_5029_50290004_59_dialog_content = "今、飛んできた紙を拾ったのだけれど、\nあなたたちのもの？",
  ui_story_5029_50290004_60_dialog_content = "そうだよ！\nPlayerNameの秘密があるの！",
  ui_story_5029_50290004_61_dialog_content = "カレン、その紙…",
  ui_story_5029_50290004_62_option_content = "拾ってくれてありがとう",
  ui_story_5029_50290004_63_dialog_content = "どういたしまして。",
  ui_story_5029_50290004_64_dialog_content = "実は僕も、何が書かれてるのか知らないんだ…",
  ui_story_5029_50290004_65_option_content = "早く返して！",
  ui_story_5029_50290004_65X1_dialog_content = "R・Wにでも入ることにしたの？",
  ui_story_5029_50290004_65X2_dialog_content = "ずいぶんぶしつけね。\nあの人たちとそっくり。",
  ui_story_5029_50290004_66_dialog_content = "だ、だって、僕も何が書かれてるか、\n知らないから…",
  ui_story_5029_50290004_67_dialog_content = "根も葉もないことが書いてあるかも…",
  ui_story_5029_50290004_68_dialog_content = "それなら、見れば分かるわ。",
  ui_story_5029_50290004_69_dialog_content = "盗まれた家宝を取り戻すため、探偵求む。\n高額の懸賞金の用意あり。",
  ui_story_5029_50290004_70_dialog_content = "興味のある方は、張り紙をはがせば\n担当の者より直接連絡する。",
  ui_story_5029_50290004_71_dialog_content = "わぁ、<color=#793f76>懸賞金</color>の張り紙だ！",
  ui_story_5029_50290004_72_dialog_content = "ハーバーシティは治安が良い、\n豊かな街だとずいぶん前から評判よ。\nこの街でそんな盗難事件が起こったというの？",
  ui_story_5029_50290004_73_dialog_content = "…これ、本当に僕がはがしたの？\nまったく記憶にないんだけど…",
  ui_story_5029_50290004_74_dialog_content = "PlayerName、気持ちはよく分かるわ。",
  ui_story_5029_50290004_74X1_dialog_content = "きっと「高額の懸賞金」って文字に\n目がくらんだのね！",
  ui_story_5029_50290004_75_dialog_content = "でも僕、質の悪い探偵小説を\n読んだことがあるぐらいで、\n本物の探偵の仕事なんてやったことないよ。",
  ui_story_5029_50290004_76_dialog_content = "一体何を思って、はがしたんだろう…？",
  ui_story_5029_50290004_77_dialog_content = "PlayerName、まさか、怖がってるの～？",
  ui_story_5029_50290004_78_dialog_content = "だったら、その話はフィアに任せて！\nあたしとキャロ、ちょうどお金に困ってたんだ。",
  ui_story_5029_50290004_79_dialog_content = "ルルル～！",
  ui_story_5029_50290004_80_dialog_content = "旅費はもらってないの？師匠から。",
  ui_story_5029_50290004_81_dialog_content = "あのドケチ師匠、こんな遠くまで来るのに、\nお金なんかほとんどくれないんだから！",
  ui_story_5029_50290004_82_dialog_content = "おいしいものも食べられないし、面白いものがあっても遊べない…\nダメ師匠、今に見てなさい…！",
  ui_story_5029_50290004_83_dialog_content = "フィアは言いつけをやり遂げるだけじゃ終わらない！\nついでに大金を稼いじゃうから！",
  ui_story_5029_50290004_84_dialog_content = "でも、おかしな話ね…",
  ui_story_5029_50290004_85_dialog_content = "なぜ領主に解決を依頼しないのかしら。",
  ui_story_5029_50290004_86_dialog_content = "領主には解決できない問題だから…？",
  ui_story_5029_50290004_87_dialog_content = "フフン！だったら、フィアがどれだけすごいか、\nその領主って人に見せつけてあげる！",
  ui_story_5029_50290004_88_dialog_content = "よく考えなさい。\n遊びじゃないのよ。",
  ui_story_5029_50290004_89_dialog_content = "引き受ければ、正真正銘の犯罪者を\n相手にすることになるわ。",
  ui_story_5029_50290004_90_dialog_content = "え？あ、あたしは…",
  ui_story_5029_50290004_91_dialog_content = "フ、フン…！バカにしないで！",
  ui_story_5029_50290004_92_dialog_content = "凶暴で気性の荒い動物だって手なずけられるんだよ。\n犯罪者ぐらい怖くないもん！！",
  ui_story_5029_50290004_93_dialog_content = "フィア、犯罪者と珍獣は別物だよ…",
  ui_story_5029_50290004_94_dialog_content = "PlayerNameまで、あたしをバカにする気？",
  ui_story_5029_50290004_95_dialog_content = "どうあろうと、白夜城の属領で起こった事件であるからには、\n私も見て見ぬふりはできないわ。",
  ui_story_5029_50290004_96_dialog_content = "白夜城の名のもとに、\n犯人は白夜城の法律で裁かれなければ。",
  ui_story_5029_50290004_97_dialog_content = "でも、それだと…懸賞金はもらえないんじゃ？",
  ui_story_5029_50290004_98_dialog_content = "あ～、分かった！\nこの仕事に手を出して欲しくないんだ！",
  ui_story_5029_50290004_99_dialog_content = "本当は、あんたたちが自分で\n受けたいんでしょ？",
  ui_story_5029_50290004_100_dialog_content = "だったら、<color=#793f76>公平に勝負</color>しよ！",
  ui_story_5029_50290004_101_dialog_content = "賞金は、犯人を見つけた人のものってことね？\nいいと思うわ！",
  ui_story_5029_50290004_102_dialog_content = "それなら、覚悟することね。",
  ui_story_5029_50290004_103_dialog_content = "私には、白夜城でそれなりの経験があるわ。",
  ui_story_5029_50290004_104_dialog_content = "え…じゃあ、僕は…？",
  ui_story_5029_50290004_105_dialog_content = "お待たせして申し訳ございません。",
  ui_story_5029_50290004_106_dialog_content = "私が張り紙に書かれている、連絡担当の者です。\nゼインと申します。",
  ui_story_5029_50290004_107_dialog_content = "皆様、お仕事をお引き受けいただけるのでしたら、\nどうぞ私について来てください。",
  ui_story_5029_50290005_1_dialog_content = "ちょっと待って。ここって…",
  ui_story_5029_50290005_2_dialog_content = "…見間違いじゃないよね？",
  ui_story_5029_50290005_3_dialog_content = "ということは、<color=#793f76>あの人</color>が依頼主…？",
  ui_story_5029_50290005_4_dialog_content = "なぞなぞでもやってるの？\nあたしにも分かるように話してよ。",
  ui_story_5029_50290005_5_dialog_content = "皆様、入口でお立ちになる必要はございません。\nどうぞお入りください。",
  ui_story_5029_50290005_6_dialog_content = "主が中で探偵様をお待ちです。",
  ui_story_5029_50290005_7_dialog_content = "ねえ、聞いた？「探偵様」だって。\nあのおじさん、あたしたちのこと探偵様って呼んだ！",
  ui_story_5029_50290005_8_dialog_content = "シーッ…こういう時、\n探偵役は控えめにしてるものだよ。",
  ui_story_5029_50290005_9_dialog_content = "べ～だ！PlayerName、\nどんどんダメ師匠に似てきてるよ！",
  ui_story_5029_50290005_10_dialog_content = "探偵の皆様、\nようこそ、いらっしゃいました…",
  ui_story_5029_50290005_11_dialog_content = "<color=#793f76>エルビス</color>、また会ったわね。",
  ui_story_5029_50290005_12_dialog_content = "カレン殿下！？",
  ui_story_5029_50290005_13_dialog_content = "まさか、殿下がいらっしゃるとは…\nご友人の皆さんもご一緒なのですね？",
  ui_story_5029_50290005_14_dialog_content = "ゼイン、どういうことだ？\n私は探偵を探すように言ったはずだ。",
  ui_story_5029_50290005_15_dialog_content = "それについては…",
  ui_story_5029_50290005_16_dialog_content = "僕たち、貼り出された依頼の張り紙を見て、\nここに来たんです。",
  ui_story_5029_50290005_17_dialog_content = "皆さんはこのハーバーシティのお客様です。\nお客様に仕事をお願いする道理はございません。",
  ui_story_5029_50290005_18_dialog_content = "お客様は仕事を受けちゃいけないの？",
  ui_story_5029_50290005_19_dialog_content = "ヘヘヘ…それなら、\nお客じゃないのは、あたしだけ…",
  ui_story_5029_50290005_20_dialog_content = "依頼はフィア1人に任せてくれていいよ！",
  ui_story_5029_50290005_21_dialog_content = "申し訳ございませんが…\nそういう意味ではないのです。",
  ui_story_5029_50290005_22_dialog_content = "ハーバーシティにいらした方は、\n誰もが私どものお客様です。",
  ui_story_5029_50290005_23_dialog_content = "皆さんもハーバーシティを\nもう少し見て回られたいのではありませんか？",
  ui_story_5029_50290005_24_dialog_content = "依頼を解決しながら、\n普通の旅と一味違った体験もできると思います。",
  ui_story_5029_50290005_25_dialog_content = "ただの観光よりも、ずっと深く\nこの街について知ることができるかもしれません。",
  ui_story_5029_50290005_26_dialog_content = "ハハハ…皆さんの腕が立ち、\n非凡な度量をお持ちであることは、分かっておりました…",
  ui_story_5029_50290005_27_dialog_content = "皆さんのお力添えを頂けるなら、\n失くした家宝もきっと順調に取り戻せることでしょう。",
  ui_story_5029_50290005_28_dialog_content = "分かったら、早く教えて。\n一体どんな宝物を失くしたの？",
  ui_story_5029_50290005_29_dialog_content = "<color=#793f76>銀の箱</color>です。",
  ui_story_5029_50290005_30_dialog_content = "白夜城で最も著名な芸術家、\nかのレオナルドが自らデザインを手がけ制作した、\n希少な芸術作品なのです。",
  ui_story_5029_50290005_31_dialog_content = "レオナルド…どこかで聞いた覚えが…？",
  ui_story_5029_50290005_32_dialog_content = "白夜城の芸術史に何度も名前が出てくる、\n才能あふれる芸術家ね。",
  ui_story_5029_50290005_33_dialog_content = "彼の残した作品は、\n今でも多くのコレクターの憧れの的よ。",
  ui_story_5029_50290005_34_dialog_content = "その1つをあなたが持っているとは、\n思わなかったわ。",
  ui_story_5029_50290005_35_dialog_content = "さすがはカレン殿下。\nもっと早く知っていれば、芸術談義ができたのですが。",
  ui_story_5029_50290005_36_dialog_content = "残念ながら、箱はもう…",
  ui_story_5029_50290005_37_dialog_content = "難しい話はいいから、\nその銀の箱っていうのがどんなものか教えてよ。",
  ui_story_5029_50290005_38_dialog_content = "そうね…より詳しい情報を頂ければうれしいです。\n例えば、重さや寸法といった…",
  ui_story_5029_50290005_39_dialog_content = "もちろん、簡単な図でもあれば、\nいちばん早いですけど。",
  ui_story_5029_50290005_40_dialog_content = "皆さん、これをどうぞ。",
  ui_story_5029_50290005_41_dialog_content = "急いで描いたものですが、\nお役に立てば幸いです。",
  ui_story_5029_50290005_42_dialog_content = "とてもお上手ですね！\n設計図のような正確さと、美術品としての美しさを感じます。",
  ui_story_5029_50290005_43_dialog_content = "アストラ大陸で絵が描けないのって、\n僕だけなのかな…",
  ui_story_5029_50290005_44_dialog_content = "キャロ、しっかり見てね。\nこれを見つければ、ご飯が食べられるよ。",
  ui_story_5029_50290005_45_dialog_content = "ルルル！",
  ui_story_5029_50290005_46_dialog_content = "この銀の箱は、普段どこに？\nそれから、失くなったことに気付いたのはいつ頃？",
  ui_story_5029_50290005_47_dialog_content = "銀の箱はいつも、\n書斎の<color=#793f76>棚</color>の中に入れてありました。",
  ui_story_5029_50290005_48_dialog_content = "昨日の昼食前に、1度取り出して鑑賞したのですが、\n夕食後にはなくなっていました。",
  ui_story_5029_50290005_49_dialog_content = "ということは、箱が消えたのは、\n<color=#793f76>昨日の正午から夕方</color>の間…",
  ui_story_5029_50290005_50_dialog_content = "その時間帯、屋敷に出入りした者は？",
  ui_story_5029_50290005_51_dialog_content = "3名おります。",
  ui_story_5029_50290005_52_dialog_content = "1人目は、正午に清掃に来た<color=#793f76>メイド</color>です。",
  ui_story_5029_50290005_53_dialog_content = "2人目は、午後にハーバーシティを訪ねてきた、\n<color=#793f76>白夜城の公爵</color>閣下。",
  ui_story_5029_50290005_54_dialog_content = "3人目は、夕方に投資話で訪れた<color=#793f76>商人</color>です。",
  ui_story_5029_50290005_55_dialog_content = "たった3名…そのことは確かなの？",
  ui_story_5029_50290005_56_dialog_content = "それは私が保証します。",
  ui_story_5029_50290005_56X1_dialog_content = "正午から夕方までの間、私がずっと出入り口におりました。\n出入りしたのは、確かにそのお三方のみでございます。",
  ui_story_5029_50290005_57_dialog_content = "昨日、主は仕事で忙しくされており、\nどのお客様もそれぞれお屋敷の中で少しお待ちいただきました。",
  ui_story_5029_50290005_58_dialog_content = "その通り。最後の客人との話が終わった後、\n書斎に鍵を掛け、夕食を食べに向かいました。",
  ui_story_5029_50290005_59_dialog_content = "では、書斎に戻った時、\nドアに鍵が壊されたような痕跡は？",
  ui_story_5029_50290005_60_dialog_content = "いいえ、ありません。\nしかも、窓はすべて<color=#793f76>内側から鍵が掛けられています</color>。",
  ui_story_5029_50290005_61_dialog_content = "ですから、それより前に屋敷に出入りした、\nこの3名を疑っているのです。",
  ui_story_5029_50290005_62_dialog_content = "怪しいのは3人だけ？\nだったら、調べるのは難しくなさそうだけど…",
  ui_story_5029_50290005_63_dialog_content = "その3人を捕まえて聞けばいいんじゃない？",
  ui_story_5029_50290005_64_dialog_content = "そうはいかない理由があるのでしょう。",
  ui_story_5029_50290005_65_dialog_content = "ゴホゴホッ…\nカレン殿下、またご名答です。",
  ui_story_5029_50290005_66_dialog_content = "疑わしき者は、白夜城の貴族の身分である方と、\n影ノ街の商会の口利きで入ったメイド…",
  ui_story_5029_50290005_67_dialog_content = "もうお一方も、投資の意向があるようですし…\nむやみに関係を壊したくはないのです。",
  ui_story_5029_50290005_68_dialog_content = "それから、皆さんもご存じかと思いますが、\nここ数日、街では祝典がもよおされています。",
  ui_story_5029_50290005_69_dialog_content = "領主たる者、私事で皆の楽しい気分に\n水を差すわけにもまいりません。",
  ui_story_5029_50290005_70_dialog_content = "この件については、皆さんにお話したほか、\nゼインにしか知らせていません。",
  ui_story_5029_50290005_71_dialog_content = "つまり、僕たちに<color=#793f76>秘密で調査</color>してほしい、\nということですね？",
  ui_story_5029_50290005_72_dialog_content = "秘密調査…急に難しくなったわね。",
  ui_story_5029_50290005_73_dialog_content = "無理を申し上げていることは承知しています。\nですから、皆さんには、<color=#793f76>銀の箱さえ取り戻していただければよいのです</color>。",
  ui_story_5029_50290005_74_dialog_content = "もし、犯人が本当に3名のお客様の中にいたのなら…",
  ui_story_5029_50290005_75_dialog_content = "自ら立ち去っていただけるよう、\nこちらで方法を考えます。",
  ui_story_5029_50290006_1_dialog_content = "主は祝典関連の職務に向かわれました。",
  ui_story_5029_50290006_2_dialog_content = "皆様はこの後、自由に屋敷の中を調べていただいて結構です。",
  ui_story_5029_50290006_3_dialog_content = "私はホールにおりますので、\n何かありましたら、いつでもお声がけください。",
  ui_story_5029_50290006_4_dialog_content = "主に質問がある場合は、\n私からお伝え致します。",
  ui_story_5029_50290006_5_option_content = "ゼインの所へ行く",
  ui_story_5029_50290006_6_dialog_content = "何をお聞きになりたいのですか？",
  ui_story_5029_50290006_7_option_content = "この屋敷について",
  ui_story_5029_50290006_8_dialog_content = "ここは主の<color=#793f76>蔵書館</color>です。\n普段はいつもここでお仕事をなさっています。",
  ui_story_5029_50290006_9_dialog_content = "多くの時間、このお屋敷に一人で過ごされています。",
  ui_story_5029_50290006_10_dialog_content = "時には、親しいご友人とお会いになることもございます。",
  ui_story_5029_50290006_11_dialog_content = "鍵も主がご自身で管理されています。",
  ui_story_5029_50290006_12_dialog_content = "ほかに何かご質問はございますか？",
  ui_story_5029_50290006_13_option_content = "屋敷の間取り",
  ui_story_5029_50290006_14_dialog_content = "この屋敷は2階建てでございます。",
  ui_story_5029_50290006_15_dialog_content = "1階はホール、小さなカフェも備えております。",
  ui_story_5029_50290006_16_dialog_content = "2階が主の書斎です。",
  ui_story_5029_50290006_17_dialog_content = "ほかに何かご質問はございますか？",
  ui_story_5029_50290006_18_option_content = "あなたは？",
  ui_story_5029_50290006_19_dialog_content = "ゼインと申します。\n主の護衛でございます。",
  ui_story_5029_50290006_20_dialog_content = "もとは、港で運搬の仕事をしておりましたが…",
  ui_story_5029_50290006_21_dialog_content = "主にお目をかけて頂き、今日の私がございます。",
  ui_story_5029_50290006_22_dialog_content = "ほかに何かご質問はございますか？",
  ui_story_5029_50290006_23_option_content = "ない",
  ui_story_5029_50290006_24_dialog_content = "もしまたご質問がございましたら、\nいつでもお声かけください。",
  ui_story_5029_50290006_25_dialog_content = "分かったよ、ありがとう。",
  ui_story_5029_50290006_26_option_content = "適当にブラブラする",
  ui_story_5029_50290006_27_dialog_content = "皆、調査を始めたのかな？",
  ui_story_5029_50290006_28_dialog_content = "ふん…",
  ui_story_5029_50290006_29_dialog_content = "…",
  ui_story_5029_50290006_30_dialog_content = "…",
  ui_story_5029_50290006_31_dialog_content = "（何だか、気まずい雰囲気だ…）",
  ui_story_5029_50290006_32_dialog_content = "（3人とも、本当に勝負する気なの？）",
  ui_story_5029_50290006_33_dialog_content = "（そんなことないよね…\n僕も勝負しないといけないのかな…）",
  ui_story_5029_50290006_34_dialog_content = "どうしよう…",
  ui_story_5029_50290006_35_option_content = "カレンを探す",
  ui_story_5029_50290006_36_dialog_content = "カレン…",
  ui_story_5029_50290006_37_dialog_content = "どうしたの？",
  ui_story_5029_50290006_38_option_content = "一緒に調べよう",
  ui_story_5029_50290006_39_dialog_content = "私と一緒に…？構わないわ。",
  ui_story_5029_50290006_40_dialog_content = "でも、実力を確かめさせてもらわないとね。",
  ui_story_5029_50290006_41_option_content = "がんばって！",
  ui_story_5029_50290006_42_dialog_content = "ありがとう。",
  ui_story_5029_50290006_43_dialog_content = "白夜城の名にかけて、\n絶対に遅れは取らないわ。",
  ui_story_5029_50290006_44_dialog_content = "（え？もう行っちゃった…？）",
  ui_story_5029_50290006_45_dialog_content = "（何か、変なこと言っちゃったかな…）",
  ui_story_5029_50290006_46_option_content = "何でもない",
  ui_story_5029_50290006_47_dialog_content = "そう。なら、私は調査を続けるわ。",
  ui_story_5029_50290006_48_dialog_content = "（カレンの目は真剣だ…\n凍りつくかと思った）",
  ui_story_5029_50290006_49_dialog_content = "（やっぱり僕は僕でがんばろう…）",
  ui_story_5029_50290006_50_dialog_content = "（どこを調べよう？）",
  ui_story_5029_50290006_51_option_content = "バイスを探す",
  ui_story_5029_50290006_52_dialog_content = "バイス…",
  ui_story_5029_50290006_53_dialog_content = "PlayerName、どうしたの？",
  ui_story_5029_50290006_54_option_content = "一緒に調べよう",
  ui_story_5029_50290006_55_dialog_content = "私も一緒に調べようと思って待ってたの。",
  ui_story_5029_50290006_56_dialog_content = "でも、1つ問題があって…",
  ui_story_5029_50290006_57_option_content = "がんばって！",
  ui_story_5029_50290006_58_dialog_content = "安心して。もちろん、がんばるわ！",
  ui_story_5029_50290006_59_dialog_content = "賞金のために！",
  ui_story_5029_50290006_60_dialog_content = "（えっ？急いでどこかに行っちゃった…）",
  ui_story_5029_50290006_61_option_content = "何でもない",
  ui_story_5029_50290006_62_dialog_content = "そう？",
  ui_story_5029_50290006_63_dialog_content = "（バイス、今日はなんだか変だな…）",
  ui_story_5029_50290006_64_dialog_content = "（やっぱり僕は僕でがんばろう…）",
  ui_story_5029_50290006_65_dialog_content = "（どこを調べよう？）",
  ui_story_5029_50290006_66_option_content = "フィアを探す",
  ui_story_5029_50290006_67_dialog_content = "フィア…",
  ui_story_5029_50290006_68_dialog_content = "なに？",
  ui_story_5029_50290006_69_option_content = "一緒に調べよう",
  ui_story_5029_50290006_70_dialog_content = "ほんとに！？",
  ui_story_5029_50290006_71_dialog_content = "…オホン！あたしにはキャロがいるけど、\n人手は多くて悪いことはないね。",
  ui_story_5029_50290006_72_option_content = "がんばって！",
  ui_story_5029_50290006_73_dialog_content = "ふん、言われなくてもがんばってるもんね。",
  ui_story_5029_50290006_74_dialog_content = "フィアとキャロなら、トーゼン！",
  ui_story_5029_50290006_75_dialog_content = "（フィア、僕まで競争相手だと思ってるのかな？）",
  ui_story_5029_50290006_76_option_content = "何でもない",
  ui_story_5029_50290006_77_dialog_content = "ふーん。じゃあ、名推理のジャマしないで！",
  ui_story_5029_50290006_78_dialog_content = "（フィア、今日はなんだか近づきづらい…）",
  ui_story_5029_50290006_79_dialog_content = "（やっぱり僕は僕でがんばろう…）",
  ui_story_5029_50290006_80_dialog_content = "（どこを調べようかな？）",
  ui_story_5029_50290006_81_option_content = "一人で調査する",
  ui_story_5029_50290006_82_dialog_content = "（皆、忙しそうだ）",
  ui_story_5029_50290006_83_dialog_content = "（やっぱり、自分だけで調べよう…）",
  ui_story_5029_50290007_1_dialog_content = "大きな屋敷ね。一体どこから調査すべきかしら？",
  ui_story_5029_50290007_2_dialog_content = "そうだなあ…",
  ui_story_5029_50290007_3_option_content = "書斎を調べる",
  ui_story_5029_50290007_4_dialog_content = "本棚がこんなにたくさん…\nまるで図書館みたいだね？",
  ui_story_5029_50290007_5_dialog_content = "エルビスは黎明学院在学中から本の虫で、\n成績も常に上位だったと聞いているわ。",
  ui_story_5029_50290007_6_dialog_content = "君より成績のいい人がいるとも思えないけどね…",
  ui_story_5029_50290007_7_dialog_content = "…",
  ui_story_5029_50290007_8_dialog_content = "言葉の上では、彼は私の先輩にあたるわね。",
  ui_story_5029_50290007_9_dialog_content = "ただ、今はそんなことを考えているヒマはないわ。\n調査を進めましょう。",
  ui_story_5029_50290007_10_dialog_content = "どこか気になる所はある？",
  ui_story_5029_50290007_11_dialog_content = "うーん…",
  ui_story_5029_50290007_12_option_content = "1列目の本棚",
  ui_story_5029_50290007_13_dialog_content = "この本棚に置かれてる本、見覚えがあるな。\nどこか別の所で見たことある気がする。",
  ui_story_5029_50290007_14_dialog_content = "『赤浪サメ之助伝・第1巻』…？",
  ui_story_5029_50290007_15_dialog_content = "この本は…いつも一番いい所で終わっちゃうから、\nついつい読み続けちゃうんだよ。",
  ui_story_5029_50290007_16_dialog_content = "通俗小説なんて、\n領主らしくないわね…",
  ui_story_5029_50290007_17_dialog_content = "僕は本に貴賤（きせん）はないと思うよ？\n面白ければ、皆読みたくなるよ。",
  ui_story_5029_50290007_18_dialog_content = "…本については、あなたの方が視野が広いようね。",
  ui_story_5029_50290007_19_dialog_content = "でも、どうして第1巻しかないんだろう？\n続きが読みたいって思わなかったのかな？",
  ui_story_5029_50290007_20_dialog_content = "それは確かに疑うべきところがあるわね。\n後でゼインにどういうことか、事情を聞きましょう。",
  ui_story_5029_50290007_21_dialog_content = "ほかに気になる所はある？",
  ui_story_5029_50290007_22_option_content = "机の上",
  ui_story_5029_50290007_23_dialog_content = "机の上に置かれている、あの本…\n他とは少し雰囲気が違うわね。",
  ui_story_5029_50290007_24_dialog_content = "そう？見てみようか…",
  ui_story_5029_50290007_25_dialog_content = "<color=#828282>ビリッ！</color>",
  ui_story_5029_50290007_26_dialog_content = "あっ…",
  ui_story_5029_50290007_27_dialog_content = "どうなさいました…\nなんと！主が一番大切にしている古書を破いてしまわれるとは！？",
  ui_story_5029_50290007_28_dialog_content = "すぐに報告させていただきますよ！",
  ui_story_5029_50290007_29_dialog_content = "わ、わざとじゃないんです！",
  ui_story_5029_50290007_30_dialog_content = "エルビスは道理をわきまえた人物よ。\n私も説明してあげるから、心配しないで。",
  ui_story_5029_50290007_31_dialog_content = "それより、他に気になる所はない？",
  ui_story_5029_50290007_32_option_content = "棚",
  ui_story_5029_50290007_33_dialog_content = "銀の箱はずっと、\nこの棚の中に入れてたって言ってたね。",
  ui_story_5029_50290007_34_dialog_content = "ええ…周りに特におかしな痕跡はないわね。\n言っていた通り、窓もこじ開けられた様子はない。",
  ui_story_5029_50290007_35_dialog_content = "それにしても、ずいぶん不注意じゃないかな？\n貴重な物をしまってるのに、棚に鍵がないなんて？",
  ui_story_5029_50290007_36_dialog_content = "図によれば、銀の箱そのものに鍵がついているわ。",
  ui_story_5029_50290007_37_dialog_content = "それは変だね…",
  ui_story_5029_50290007_38_dialog_content = "銀の箱の中に、何かもっと大切な物が\n入っていたのかもしれないわね。",
  ui_story_5029_50290007_39_dialog_content = "何だか興味をそそられるね。",
  ui_story_5029_50290007_40_dialog_content = "それより、他に気になる所はない？",
  ui_story_5029_50290007_41_option_content = "もうないよ",
  ui_story_5029_50290007_42_dialog_content = "特に変わった所はないみたいだ。",
  ui_story_5029_50290007_43_dialog_content = "別の部屋を見に行ってみる？",
  ui_story_5029_50290007_44_option_content = "ホールへ行く",
  ui_story_5029_50290007_45_dialog_content = "ホールは他の部屋に通じているから、\n役にたつ手がかりが見つかるかもしれないわ。",
  ui_story_5029_50290007_46_dialog_content = "どこか気になる所はある？",
  ui_story_5029_50290007_47_dialog_content = "うーん…",
  ui_story_5029_50290007_48_option_content = "植木鉢",
  ui_story_5029_50290007_49_dialog_content = "何をしているの？",
  ui_story_5029_50290007_50_dialog_content = "植木鉢の中に\n何か手がかりがないかなって…",
  ui_story_5029_50290007_51_dialog_content = "ずいぶん細かく調べるのね…",
  ui_story_5029_50290007_52_dialog_content = "これは…砂漠の植物を育てているようね。",
  ui_story_5029_50290007_53_dialog_content = "トゲがあるから、気を付けて。",
  ui_story_5029_50290007_54_dialog_content = "植木鉢にぶつけられたような痕跡があるわ？",
  ui_story_5029_50290007_55_dialog_content = "トゲもたくさん落ちちゃってる。\nぶつかった人、痛かっただろうな…",
  ui_story_5029_50290007_56_dialog_content = "ほかに気になる所はある？",
  ui_story_5029_50290007_57_option_content = "ティートレイ",
  ui_story_5029_50290007_58_dialog_content = "このお盆に置かれてる本、見覚えがあるな。\nどこか別の所で見たことある気がする。",
  ui_story_5029_50290007_59_dialog_content = "『赤浪サメ之助伝・第1巻』…？",
  ui_story_5029_50290007_60_dialog_content = "この本は…いつも一番いい所で終わっちゃうから、\nついつい読み続けちゃうんだよ。",
  ui_story_5029_50290007_61_dialog_content = "通俗小説なんて、\n領主らしくないわね…",
  ui_story_5029_50290007_62_dialog_content = "僕は本に貴賤（きせん）はないと思うよ？\n面白ければ、皆読みたくなるよ。",
  ui_story_5029_50290007_63_dialog_content = "…本については、あなたの方が視野が広いようね。",
  ui_story_5029_50290007_64_dialog_content = "でも、どうして第1巻しかないんだろう？\n続きが読みたいって思わなかったのかな？",
  ui_story_5029_50290007_65_dialog_content = "それは確かに疑うべきところがあるわね。\n後でゼインにどういうことか、事情を聞きましょう。",
  ui_story_5029_50290007_66_dialog_content = "ほかに気になる所はある？",
  ui_story_5029_50290007_67_option_content = "飾り",
  ui_story_5029_50290007_68_dialog_content = "きれいな巻貝ね。",
  ui_story_5029_50290007_69_dialog_content = "僕、聞いたことあるよ。\n巻貝に願い事をすると…",
  ui_story_5029_50290007_70_dialog_content = "願いが叶う？",
  ui_story_5029_50290007_71_dialog_content = "カレンも言い伝え、知ってたんだね！",
  ui_story_5029_50290007_72_dialog_content = "せっかくだから、願い事してみる？",
  ui_story_5029_50290007_73_dialog_content = "意外と子供っぽいのね。\nおとぎ話のような言い伝えを信じるなんて。",
  ui_story_5029_50290007_74_dialog_content = "そういうわけじゃないけど…\n何となく、言葉にすると、\n願い事がかないやすくなる気がするんだ。",
  ui_story_5029_50290007_75_dialog_content = "一種の自己暗示みたいなものかな。",
  ui_story_5029_50290007_76_dialog_content = "自己暗示…",
  ui_story_5029_50290007_77_dialog_content = "まぁ、巻貝に願い事をするのが子供っぽいって思うなら、\n僕に話してくれてもいいよ。",
  ui_story_5029_50290007_78_dialog_content = "そうすれば、手助けできるかもしれないし。",
  ui_story_5029_50290007_79_dialog_content = "そう？それなら、私の願いは\n早く手がかりを見つけることね。",
  ui_story_5029_50290007_80_dialog_content = "じゃあ、今すぐ次の場所を調べに行こう！",
  ui_story_5029_50290007_81_option_content = "もうないよ",
  ui_story_5029_50290007_82_dialog_content = "特に変わった所はないみたいだ。",
  ui_story_5029_50290007_83_dialog_content = "別の部屋を見に行ってみる？",
  ui_story_5029_50290007_84_option_content = "カフェに行く",
  ui_story_5029_50290007_85_dialog_content = "カフェへ行かれるのですか？\nこちらへどうぞ。",
  ui_story_5029_50290007_86_dialog_content = "主は仕事中に人に会うことを嫌うので、\nここにカフェがあるのです。",
  ui_story_5029_50290007_87_dialog_content = "主みずからお客様にコーヒーを\nいれることもございますね。",
  ui_story_5029_50290007_88_dialog_content = "PlayerName、どう？\nどこか気になる所はある？",
  ui_story_5029_50290007_89_dialog_content = "うーん…",
  ui_story_5029_50290007_90_option_content = "イス",
  ui_story_5029_50290007_91_dialog_content = "座って少し休まない？",
  ui_story_5029_50290007_92_dialog_content = "大丈夫よ、私は疲れていないわ。",
  ui_story_5029_50290007_93_dialog_content = "そう…？じゃあ、僕も調査を続けよう！",
  ui_story_5029_50290007_94_dialog_content = "あれ、このイス、新聞が置いてある？",
  ui_story_5029_50290007_95_dialog_content = "影ノ街の、昨日の新聞…",
  ui_story_5029_50290007_96_dialog_content = "もうこんな所にあるなんて、エルビスはさすがね。",
  ui_story_5029_50290007_97_dialog_content = "「空の末裔はしばらく影ノ街に姿を見せておらず、\nファンたちはプライベートを追うため、\n高額でスケジュールを求めている…」",
  ui_story_5029_50290007_98_dialog_content = "…こんなものも新聞記事と言うのかしら。",
  ui_story_5029_50290007_99_dialog_content = "オホン、オホン！事件と無関係なのは確実だね。",
  ui_story_5029_50290007_100_dialog_content = "まあ、いいわ。\nほかに気になる所はある？",
  ui_story_5029_50290007_101_option_content = "カウンター",
  ui_story_5029_50290007_102_dialog_content = "カウンターに置かれてる本、見覚えがあるな。\nどこか別の所で見たことある気がする。",
  ui_story_5029_50290007_103_dialog_content = "『赤浪サメ之助伝・第1巻』…？",
  ui_story_5029_50290007_104_dialog_content = "この本は…いつも一番いい所で終わっちゃうから、\nついつい読み続けちゃうんだよ。",
  ui_story_5029_50290007_105_dialog_content = "通俗小説なんて、\n領主らしくないわね…",
  ui_story_5029_50290007_106_dialog_content = "僕は本に貴賤（きせん）はないと思うよ？\n面白ければ、皆読みたくなるよ。",
  ui_story_5029_50290007_107_dialog_content = "…本については、あなたの方が視野が広いようね。",
  ui_story_5029_50290007_108_dialog_content = "でも、どうして第1巻しかないんだろう？\n続きが読みたいって思わなかったのかな？",
  ui_story_5029_50290007_109_dialog_content = "それは確かに疑うべきところがあるわね。\n後でゼインにどういうことか、事情を聞きましょう。",
  ui_story_5029_50290007_110_dialog_content = "ほかに気になる所はある？",
  ui_story_5029_50290007_111_option_content = "壁",
  ui_story_5029_50290007_112_dialog_content = "壁にたくさん、きれいな油絵が掛かってる。",
  ui_story_5029_50290007_113_dialog_content = "大胆な筆づかいで描かれているわね。\nそれがかえって圧倒的な迫力を生み出しているわ。",
  ui_story_5029_50290007_114_dialog_content = "エルビスの心の中もきっと、\n見た目ほど弱々しくはないのでしょうね。",
  ui_story_5029_50290007_115_dialog_content = "あれ？この絵、どこか見覚えがある…",
  ui_story_5029_50290007_116_dialog_content = "これは…！？",
  ui_story_5029_50290007_117_dialog_content = "あ…思い出した。",
  ui_story_5029_50290007_118_dialog_content = "これ、カレンのお父さんの若い頃の肖像画？",
  ui_story_5029_50290007_119_dialog_content = "父上の肖像画の模写など、\nどうしてエルビスが持っているのかしら。",
  ui_story_5029_50290007_120_dialog_content = "白夜城への忠誠を示すため、とか？",
  ui_story_5029_50290007_121_dialog_content = "カレンの肖像画も\nこっそり持ってるかもしれないよ、アハハ…",
  ui_story_5029_50290007_122_dialog_content = "そうでないことを願うわ…",
  ui_story_5029_50290007_123_dialog_content = "それはいいとして、\nほかに気になる所はある？",
  ui_story_5029_50290007_124_option_content = "もうないよ",
  ui_story_5029_50290007_125_dialog_content = "特に変わった所はないみたいだ。",
  ui_story_5029_50290007_126_dialog_content = "別の部屋を見に行ってみる？",
  ui_story_5029_50290007_127_option_content = "もう調べるべき所はない",
  ui_story_5029_50290007_128_dialog_content = "調べられる所は全部、調べたと思う。",
  ui_story_5029_50290007_129_dialog_content = "そう？",
  ui_story_5029_50290007_130_dialog_content = "私は気になることがあるの…\nもう1度確認してみるわ。",
  ui_story_5029_50290007_131_dialog_content = "じゃあ、僕はソファに座って一休みするよ。",
  ui_story_5029_50290008_1_dialog_content = "どこを調べる？",
  ui_story_5029_50290008_2_dialog_content = "そうだなあ…",
  ui_story_5029_50290008_3_option_content = "書斎を調べる",
  ui_story_5029_50290008_4_dialog_content = "本棚がこんなにたくさん…\nまるで図書館みたいだね？",
  ui_story_5029_50290008_5_dialog_content = "こういう部屋が欲しいなら、\nあなたも巨像に図書室を作ればいいじゃない。",
  ui_story_5029_50290008_6_dialog_content = "そうだね！この依頼でお金がもらえたら、\nそれで本を買うのもいいかな。",
  ui_story_5029_50290008_7_dialog_content = "もっとやる気が出て来たわ！\nさあ、急いで手がかり探しを続けましょ！",
  ui_story_5029_50290008_8_dialog_content = "どこを調べようか…",
  ui_story_5029_50290008_9_option_content = "1列目の本棚",
  ui_story_5029_50290008_10_dialog_content = "領主さん、いろんな本を読むんだね？",
  ui_story_5029_50290008_11_dialog_content = "題名さえなんて読むのか、\n分からない本ばっかりだ…",
  ui_story_5029_50290008_12_dialog_content = "啓光にも大きな図書館があるわ。\nもし勉強したいなら、私と一緒に啓光で…",
  ui_story_5029_50290008_13_dialog_content = "えっ？ちょっと待って！\n『亜人社会の分業探究――「失われた秘境」の例に基づく』って…",
  ui_story_5029_50290008_14_dialog_content = "この本、亜人に関する最新研究じゃない！？",
  ui_story_5029_50290008_15_dialog_content = "私、まだ読んだことないわ！",
  ui_story_5029_50290008_16_dialog_content = "僕は隣の小説でも読むことにするよ…",
  ui_story_5029_50290008_17_dialog_content = "…じゃない！！\n僕は引き続き手がかりを探すよ！",
  ui_story_5029_50290008_18_option_content = "2列目の本棚",
  ui_story_5029_50290008_19_dialog_content = "バイス、見て！\nこの本、装丁に宝石がはめ込まれてる！",
  ui_story_5029_50290008_20_dialog_content = "領主一族の家系譜みたいね。",
  ui_story_5029_50290008_21_dialog_content = "だとしても、装丁が豪華すぎるわ…\nこれ1冊の値段で、どれだけの食糧が買えることか…",
  ui_story_5029_50290008_22_dialog_content = "もし一族全員の名前を知ることが出来るなら、\n僕もきっと、こんな本を作るために手を尽くすと思うよ。",
  ui_story_5029_50290008_23_dialog_content = "PlayerName…",
  ui_story_5029_50290008_24_dialog_content = "じゃあ、今すぐにでも、\n貯金を始めないとね！",
  ui_story_5029_50290008_25_dialog_content = "…ア、アハハ…",
  ui_story_5029_50290008_26_dialog_content = "ぼ、僕は手がかり探しに戻るよ！",
  ui_story_5029_50290008_27_option_content = "棚",
  ui_story_5029_50290008_28_dialog_content = "銀の箱はずっと、\nこの棚の中に入れてたって言ってたね。",
  ui_story_5029_50290008_29_dialog_content = "この棚には、錠前がないのね。",
  ui_story_5029_50290008_30_dialog_content = "中は空っぽよ、何も入ってないわ。",
  ui_story_5029_50290008_31_dialog_content = "僕だったら、きっと何重にも鍵をかけるけどなぁ。",
  ui_story_5029_50290008_32_dialog_content = "寝てる時も、鍵を枕の下に隠したり…",
  ui_story_5029_50290008_33_dialog_content = "へ～、そう？いいこと聞いちゃった！",
  ui_story_5029_50290008_34_dialog_content = "今度、あなたの枕の下に\n宝の隠し場所の鍵がないか、探してみよっと。",
  ui_story_5029_50290008_35_dialog_content = "それは…",
  ui_story_5029_50290008_36_dialog_content = "て、手がかり探しに戻らないと！",
  ui_story_5029_50290008_37_option_content = "一通り調べ終わった",
  ui_story_5029_50290008_38_dialog_content = "別の部屋を調べようか？",
  ui_story_5029_50290008_39_dialog_content = "そうね、どこを調べる？",
  ui_story_5029_50290008_40_option_content = "ホールへ行く",
  ui_story_5029_50290008_41_dialog_content = "こんなに大きなお屋敷を、\n領主さんは普段、仕事のためだけに使ってるの？",
  ui_story_5029_50290008_42_dialog_content = "ここに住んでも良さそうなのに…",
  ui_story_5029_50290008_43_dialog_content = "あなただって巨像があるじゃない。\nお屋敷がうらやましいの？",
  ui_story_5029_50290008_44_dialog_content = "アハハ…不思議に思っただけだよ。",
  ui_story_5029_50290008_45_dialog_content = "私だって冗談よ。\n急いで手がかりを探しましょ。",
  ui_story_5029_50290008_46_dialog_content = "どこを調べようか…",
  ui_story_5029_50290008_47_option_content = "植木鉢",
  ui_story_5029_50290008_48_dialog_content = "植木鉢の中に、何かしかけがあったりしないかな？",
  ui_story_5029_50290008_49_dialog_content = "想像力が豊かね…",
  ui_story_5029_50290008_50_dialog_content = "ううん…残念だけど、何もないや。",
  ui_story_5029_50290008_51_dialog_content = "それにしてもこの花、すごくきれいだ。\nすがすがしい香りもする。クンクン…",
  ui_story_5029_50290008_52_dialog_content = "…ちょっとクラクラしてきた。",
  ui_story_5029_50290008_53_dialog_content = "まさか、この花に何か…？",
  ui_story_5029_50290008_54_dialog_content = "ゼインさん、急いで見てください…\nこの花、誰かが毒でもしかけたのでは？",
  ui_story_5029_50290008_55_dialog_content = "いえ、その花はキョウチクセンといい、\nもともと毒を持っているのです。",
  ui_story_5029_50290008_56_dialog_content = "口に入れなければ大ごとにはならないでしょう。",
  ui_story_5029_50290008_57_dialog_content = "毒性のある花を屋内に飾るなんて…？\n貴族の趣味って、よく分からないわ…",
  ui_story_5029_50290008_58_dialog_content = "PlayerName、疲れてない？ソファーで少し休みましょ。",
  ui_story_5029_50290008_59_dialog_content = "大丈夫、まだ続けられるよ！",
  ui_story_5029_50290008_60_option_content = "ソファー",
  ui_story_5029_50290008_61_dialog_content = "座り心地の良さそうなソファーだなぁ…",
  ui_story_5029_50290008_62_dialog_content = "巨像にもこんなソファーがあったらいいな。",
  ui_story_5029_50290008_63_dialog_content = "コホン…それならこのソファーがいくらするか、\n聞きたくないでしょうね。",
  ui_story_5029_50290008_64_dialog_content = "…",
  ui_story_5029_50290008_65_dialog_content = "やっぱり立ってよう。",
  ui_story_5029_50290008_66_dialog_content = "どうしたの？",
  ui_story_5029_50290008_67_dialog_content = "正直、僕は…干し草の上に座るのも、\n気持ちよくて好きだよ！",
  ui_story_5029_50290008_68_dialog_content = "ふぅ…今日もまた１つ、ムダづかいを減らせたわ…",
  ui_story_5029_50290008_69_dialog_content = "コホン…じゃあ、調査を続けよう。",
  ui_story_5029_50290008_70_option_content = "飾り",
  ui_story_5029_50290008_71_dialog_content = "PlayerName、見て見て。\n巻貝があるわ！",
  ui_story_5029_50290008_72_dialog_content = "きれいだね。\nこんな大きな巻貝、珍しい。",
  ui_story_5029_50290008_73_dialog_content = "僕、聞いたことがあるよ。人里離れた小島だと、\n二枚貝や巻貝がお金として使われてるんだって。",
  ui_story_5029_50290008_74_dialog_content = "この巻貝も、そうとうなお金として\n使えるってことかしら？",
  ui_story_5029_50290008_75_dialog_content = "残念だけど、\nここじゃ白夜コインしか使えないよ。",
  ui_story_5029_50290008_76_dialog_content = "でも、気に入ったなら、\nこんど海に探しに行ってもいいね。",
  ui_story_5029_50290008_77_dialog_content = "これより大きくて、\nきれいな貝が見つかるかもしれないよ。",
  ui_story_5029_50290008_78_dialog_content = "そうね。絶対に約束よ！",
  ui_story_5029_50290008_79_dialog_content = "もちろん！\nじゃあ、調査を続けよう。",
  ui_story_5029_50290008_80_option_content = "一通り調べ終わった",
  ui_story_5029_50290008_81_dialog_content = "別の部屋を調べようか？",
  ui_story_5029_50290008_82_dialog_content = "そうね、どこを調べる？",
  ui_story_5029_50290008_83_option_content = "カフェに行く",
  ui_story_5029_50290008_84_dialog_content = "カフェへ行かれるのですか？\nこちらへどうぞ。",
  ui_story_5029_50290008_85_dialog_content = "主は仕事中に人に会うことを嫌うので、\nここにカフェがあるのです。",
  ui_story_5029_50290008_86_dialog_content = "主みずからお客様にコーヒーを\nいれることもございますね。",
  ui_story_5029_50290008_87_dialog_content = "ずいぶんと凝ってるわね。",
  ui_story_5029_50290008_88_dialog_content = "物がたくさんあって、\n何から調べればいいか、分からないや…",
  ui_story_5029_50290008_89_option_content = "コーヒーカップ",
  ui_story_5029_50290008_90_dialog_content = "1つ1つ、デザインも模様も違ってる！",
  ui_story_5029_50290008_91_dialog_content = "このコーヒーカップだけで、\n展覧会が開けそうね。",
  ui_story_5029_50290008_92_dialog_content = "あれ、おかしいわ。\nこのカップ、どうしてまだコーヒーが入ってるの？",
  ui_story_5029_50290008_93_dialog_content = "昨日のお客さんの誰かが、\n飲み残したんじゃないかな？",
  ui_story_5029_50290008_94_dialog_content = "<color=#828282>カチン…</color>",
  ui_story_5029_50290008_95_dialog_content = "中に何か入ってるみたいよ？",
  ui_story_5029_50290008_96_dialog_content = "出してみよう…",
  ui_story_5029_50290008_97_dialog_content = "あっ、バッジだね…\nどこかで見たことがあるような？",
  ui_story_5029_50290008_98_dialog_content = "白夜城騎士団のバッジだわ！",
  ui_story_5029_50290008_99_dialog_content = "どうしてカップの中に入ってたのかしら？\nまさか、昨日ここに来たっていう公爵が…？",
  ui_story_5029_50290008_100_dialog_content = "後でゼインさんに話を聞きましょう。",
  ui_story_5029_50290008_101_dialog_content = "そうだね！\nじゃあ、調査を続けよう。",
  ui_story_5029_50290008_102_option_content = "イス",
  ui_story_5029_50290008_103_dialog_content = "PlayerName、そのイスを引いてもらえる？",
  ui_story_5029_50290008_104_dialog_content = "いいよ、疲れちゃったの？",
  ui_story_5029_50290008_105_dialog_content = "違うわ、そのイスの上に何かあるの。",
  ui_story_5029_50290008_106_dialog_content = "本当だ…新聞だね。",
  ui_story_5029_50290008_107_dialog_content = "「アンデルセン家は、\nニナ女史の大規模な事業展開を支持…」",
  ui_story_5029_50290008_108_dialog_content = "「関係筋によると、女史は以前、\n空の末裔のもとへ家出をしたという…」",
  ui_story_5029_50290008_109_dialog_content = "…こ、こんな書き方されたら、\n誤解されるんじゃ…",
  ui_story_5029_50290008_110_dialog_content = "まぁ、間違いではないけどね？",
  ui_story_5029_50290008_111_dialog_content = "オホン、オホン！",
  ui_story_5029_50290008_112_dialog_content = "手がかりを探そう。",
  ui_story_5029_50290008_113_option_content = "壁",
  ui_story_5029_50290008_114_dialog_content = "この壁にかかってる絵、\nどれも価値が高そうね。",
  ui_story_5029_50290008_115_dialog_content = "じゃあ、犯人はどうして、\nここの絵とかを狙わなかったんだろう？",
  ui_story_5029_50290008_116_dialog_content = "有名な人の絵じゃないからかもね。",
  ui_story_5029_50290008_117_dialog_content = "ん？隅にかかってる妙な絵は…",
  ui_story_5029_50290008_118_dialog_content = "こ、これ、あなたが私にくれた絵じゃない！？\nどうしてここにあるの？",
  ui_story_5029_50290008_119_dialog_content = "…近くに販売業者の名前でも\n書かれてないかな？",
  ui_story_5029_50290008_120_dialog_content = "ハチ、ギン…！？",
  ui_story_5029_50290008_121_dialog_content = "あの二人、僕の絵の模写を\nハーバーシティまで売りにきてたの？",
  ui_story_5029_50290008_122_dialog_content = "ある意味、感心するよ…",
  ui_story_5029_50290008_123_dialog_content = "でも今は、手がかりを探そう。",
  ui_story_5029_50290008_124_option_content = "一通り調べ終わった",
  ui_story_5029_50290008_125_dialog_content = "別の部屋を調べようか？",
  ui_story_5029_50290008_126_dialog_content = "そうね、どこを調べる？",
  ui_story_5029_50290008_127_option_content = "もう調べるべき所はない",
  ui_story_5029_50290008_128_dialog_content = "調べられる所は全部、調べたと思う。",
  ui_story_5029_50290008_129_dialog_content = "私は1つ気になる所があるの…",
  ui_story_5029_50290008_130_dialog_content = "もう一度確かめてくるわ！",
  ui_story_5029_50290008_131_dialog_content = "僕はソファーの所で待ってるよ。",
  ui_story_5029_50290009_1_dialog_content = "で…あたしたち、何すればいいの？",
  ui_story_5029_50290009_2_dialog_content = "そうだなぁ…",
  ui_story_5029_50290009_3_option_content = "書斎を調べる",
  ui_story_5029_50290009_4_dialog_content = "キャロ、隊形を崩さず、警戒態勢を保って！",
  ui_story_5029_50290009_5_dialog_content = "ルルル！",
  ui_story_5029_50290009_6_dialog_content = "決まった隊形なんてあった？",
  ui_story_5029_50290009_7_dialog_content = "PlayerNameが先頭、キャロが後ろで、\nフィアは真ん中！",
  ui_story_5029_50290009_7X1_dialog_content = "それがあたしたちのドラゴンフォーメーション！",
  ui_story_5029_50290009_8_dialog_content = "そうなんだ…？\nそれにしても、この部屋、本当に広いなぁ。",
  ui_story_5029_50290009_9_dialog_content = "どこを調べるの？",
  ui_story_5029_50290009_10_option_content = "1列目の本棚",
  ui_story_5029_50290009_11_dialog_content = "この本棚、1冊ずいぶん場所を取ってる本があるね。",
  ui_story_5029_50290009_12_dialog_content = "すごそうな表紙だね…",
  ui_story_5029_50290009_13_dialog_content = "まさか、伝説の珍獣の密猟を\n記録した本とか！？",
  ui_story_5029_50290009_14_dialog_content = "…あれ、この本…\n中身は師匠の『ふしぎな小動物』だよ！？",
  ui_story_5029_50290009_15_dialog_content = "表紙が装丁しなおしてあるみたいだね。",
  ui_story_5029_50290009_16_dialog_content = "あの領主のおじさん、師匠の本を読んだってこと？",
  ui_story_5029_50290009_17_dialog_content = "ってことは、きっとフィアの本も好きになるよね？",
  ui_story_5029_50290009_18_dialog_content = "君の本なんて出版されてたの？",
  ui_story_5029_50290009_19_dialog_content = "まだだけど…",
  ui_story_5029_50290009_20_dialog_content = "あと何年かしたら、\nフィアの出した本が師匠の本の人気を追い越すんだから！",
  ui_story_5029_50290009_21_dialog_content = "分かったよ…でも今は、\n調査を続けよう。",
  ui_story_5029_50290009_22_option_content = "壁",
  ui_story_5029_50290009_23_dialog_content = "ル…",
  ui_story_5029_50290009_24_dialog_content = "キャロ、怖がることはないよ。",
  ui_story_5029_50290009_25_dialog_content = "ただのシカの頭だよ。",
  ui_story_5029_50290009_26_dialog_content = "ルルルゥ…",
  ui_story_5029_50290009_27_dialog_content = "説明した後の方が、怖がってるみたいだけど？",
  ui_story_5029_50290009_28_dialog_content = "キャロったら…きっとまた、\nシカに体当たりされてふっとんだ時のことを思い出したんだよ。",
  ui_story_5029_50290009_29_dialog_content = "ルルル！！",
  ui_story_5029_50290009_30_dialog_content = "キャロ、離れないようにね。\n調査を続けるよ！",
  ui_story_5029_50290009_31_option_content = "棚",
  ui_story_5029_50290009_32_dialog_content = "銀の箱はずっと、\nこの棚の中に入れてたって言ってたね。",
  ui_story_5029_50290009_33_dialog_content = "中はもう、空っぽ…",
  ui_story_5029_50290009_34_dialog_content = "おかしいな。\nこの棚、錠前が付いてないよ。",
  ui_story_5029_50290009_35_dialog_content = "領主のおじさん、部屋に鍵が付いてるから、\n棚にはなくても大丈夫って思ってたんじゃない？",
  ui_story_5029_50290009_36_dialog_content = "でも、図面によれば、\n銀の箱には鍵が付いてたはず。",
  ui_story_5029_50290009_37_dialog_content = "へえ～。じゃ、銀の箱の中には、\n箱より大切な物が入ってるのかも？",
  ui_story_5029_50290009_38_dialog_content = "確かに、鋭いね…",
  ui_story_5029_50290009_39_dialog_content = "「珍獣マスター兼名探偵」って呼んで！",
  ui_story_5029_50290009_40_dialog_content = "分かったよ、「珍獣マスター兼名探偵」さん、\n調査を続けようか。",
  ui_story_5029_50290009_41_option_content = "一通り調べ終わった",
  ui_story_5029_50290009_42_dialog_content = "じゃあ、どうする…？",
  ui_story_5029_50290009_43_dialog_content = "別の部屋を探そう！",
  ui_story_5029_50290009_44_dialog_content = "次はどこにする？",
  ui_story_5029_50290009_45_option_content = "ホールへ行く",
  ui_story_5029_50290009_46_dialog_content = "ホールは他の部屋につながってるから、\nしっかり調べないと。",
  ui_story_5029_50290009_47_dialog_content = "そんなのトーゼンだよ。\nわざわざ言わなくても分かってるって。",
  ui_story_5029_50290009_48_dialog_content = "問題は…",
  ui_story_5029_50290009_49_dialog_content = "どこを調べるの？",
  ui_story_5029_50290009_50_option_content = "植木鉢",
  ui_story_5029_50290009_51_dialog_content = "植木鉢の中に、何かしかけがあったりしないかな？",
  ui_story_5029_50290009_52_dialog_content = "ちょっと待って！！！",
  ui_story_5029_50290009_53_dialog_content = "ど、どうしたの、急に大声出して？",
  ui_story_5029_50290009_54_dialog_content = "この花、師匠のノートに書かれてたヤツだよ。\n確か、猛毒をもってる！",
  ui_story_5029_50290009_55_dialog_content = "フィア、ありがとう…\nおかげで触らずに済んだよ。",
  ui_story_5029_50290009_56_dialog_content = "ちょっと、キャロ！\n匂いもかいじゃダメ！",
  ui_story_5029_50290009_57_dialog_content = "キャロ、早く戻っておいで。\n調査を続けるよ。",
  ui_story_5029_50290009_58_option_content = "ソファー",
  ui_story_5029_50290009_59_dialog_content = "どうしたの、何か見つけた？",
  ui_story_5029_50290009_60_dialog_content = "物語とかだと、ソファーの下に\nすごい秘密が隠されてたりするでしょ。",
  ui_story_5029_50290009_61_dialog_content = "でも、こんなに狭いすき間じゃ、キャロの頭も入らないよ。\n銀の箱だって入らないんじゃない？",
  ui_story_5029_50290009_62_dialog_content = "銀の箱が隠れてなくても、\nほかのものなら、隠せるかも。",
  ui_story_5029_50290009_63_dialog_content = "例えば…",
  ui_story_5029_50290009_64_dialog_content = "あれ、ソファーの下、本当に何かあったの？",
  ui_story_5029_50290009_65_dialog_content = "でも、何だか分からないよ。",
  ui_story_5029_50290009_66_dialog_content = "何かが割れた、破片みたいだね。",
  ui_story_5029_50290009_67_dialog_content = "え！？\nこれって、大事な手がかりじゃない！？",
  ui_story_5029_50290009_68_dialog_content = "領主のおじさんが言ってたよね？\n昼にメイドが掃除しに来たって。",
  ui_story_5029_50290009_69_dialog_content = "掃除が行き届いてなかったのかも…？",
  ui_story_5029_50290009_70_dialog_content = "違う！そんな単純なことじゃないよ！\n「珍獣マスター兼名探偵」の直感でわかるの！",
  ui_story_5029_50290009_71_dialog_content = "後でゼインおじさんに、そのメイドのことをいろいろ聞かなくちゃ。",
  ui_story_5029_50290009_72_dialog_content = "そうだね、じゃあ、調査を続けよう。",
  ui_story_5029_50290009_73_option_content = "飾り",
  ui_story_5029_50290009_74_dialog_content = "わぁ！\n珍獣がいるよ、PlayerName、早く早く！",
  ui_story_5029_50290009_75_dialog_content = "えっ、巻貝を見たことないの？",
  ui_story_5029_50290009_76_dialog_content = "あたしは珍獣マスターだよ！\n見たことない動物なんていないもん！",
  ui_story_5029_50290009_77_dialog_content = "た、ただ、こんな色の巻貝を実際に見るのは、\nはじめてだっただけ…",
  ui_story_5029_50290009_78_dialog_content = "巻貝に願い事をすると、\n願いが叶うって聞いたことがあるよ。",
  ui_story_5029_50290009_79_dialog_content = "え？そんなの子供だましでしょ？",
  ui_story_5029_50290009_80_dialog_content = "あたしはもう子どもじゃないの！\nそんな手には乗らないよ～だ。",
  ui_story_5029_50290009_81_dialog_content = "巻貝さん、巻貝さん…\nどうか、領主さんの失くしものが見つかりますように…",
  ui_story_5029_50290009_82_dialog_content = "自分だけ願い事する気？\nだったら…",
  ui_story_5029_50290009_83_dialog_content = "巻貝さん、巻貝さん。\n領主様の失くしものを見つけるのが、\nフィアでありますように！",
  ui_story_5029_50290009_84_dialog_content = "コホン…さあ、急いで調査を続けよう。",
  ui_story_5029_50290009_85_option_content = "一通り調べ終わった",
  ui_story_5029_50290009_86_dialog_content = "じゃあ、どうする…？",
  ui_story_5029_50290009_87_dialog_content = "別の部屋を探そう！",
  ui_story_5029_50290009_88_dialog_content = "次はどこにする？",
  ui_story_5029_50290009_89_option_content = "カフェに行く",
  ui_story_5029_50290009_90_dialog_content = "カフェへ行かれるのですか？\nこちらへどうぞ。",
  ui_story_5029_50290009_91_dialog_content = "主は仕事中に人に会うことを嫌うので、\nここにカフェがあるのです。",
  ui_story_5029_50290009_92_dialog_content = "主みずからお客様にコーヒーを\nいれることもございますね。",
  ui_story_5029_50290009_93_dialog_content = "わあ、いい匂い！",
  ui_story_5029_50290009_94_dialog_content = "ルルル！",
  ui_story_5029_50290009_95_dialog_content = "どこを調べる？",
  ui_story_5029_50290009_96_option_content = "調理場",
  ui_story_5029_50290009_97_dialog_content = "まさか、これって…",
  ui_story_5029_50290009_98_dialog_content = "ハチミツケーキ？",
  ui_story_5029_50290009_99_dialog_content = "ハーバーシティに、\n北境名物があるとは思わなかったよ。",
  ui_story_5029_50290009_100_dialog_content = "影ノ街じゃ、食べたことないな～。",
  ui_story_5029_50290009_101_dialog_content = "おいしいの？",
  ui_story_5029_50290009_102_dialog_content = "おいしいけど、\nこれは食べずにそのままにしておこう。",
  ui_story_5029_50290009_103_dialog_content = "ふん！そんなこと、\nフィアだって分かってるよ。",
  ui_story_5029_50290009_104_dialog_content = "ハーバーシティは、他にもおいしいものが\nたくさんあるって聞いてるし…",
  ui_story_5029_50290009_105_dialog_content = "銀の箱を見つけて、お金をもらえれば…\nなんでも食べ放題だね！",
  ui_story_5029_50290009_106_dialog_content = "ルルル！",
  ui_story_5029_50290009_107_dialog_content = "コホン…さあ、急いで調査を続けよう。",
  ui_story_5029_50290009_108_option_content = "床板",
  ui_story_5029_50290009_109_dialog_content = "キャロ、どうしてあたしの後ろで震えてるの？",
  ui_story_5029_50290009_110_dialog_content = "あっちに何かある？",
  ui_story_5029_50290009_111_dialog_content = "あっ、PlayerName！！\n血の付いた果物ナイフがある！",
  ui_story_5029_50290009_112_dialog_content = "殺人事件の調査じゃなかったはずだけど…？",
  ui_story_5029_50290009_113_dialog_content = "う～ん…",
  ui_story_5029_50290009_114_dialog_content = "オホン…僕が見てみるよ。",
  ui_story_5029_50290009_115_dialog_content = "…アハハ、大丈夫。\nただのイチゴジャムだよ。",
  ui_story_5029_50290009_116_dialog_content = "さ、最初から怖がってなんかないよ！",
  ui_story_5029_50290009_117_dialog_content = "あっ！",
  ui_story_5029_50290009_118_dialog_content = "PlayerName、手にイチゴジャムがついてるよ。",
  ui_story_5029_50290009_119_dialog_content = "…うっかり指を切っちゃった…\n今度こそ本当の血だよ…",
  ui_story_5029_50290009_120_dialog_content = "ええええええ、どうしよう！？",
  ui_story_5029_50290009_121_dialog_content = "そうだ！キャロのだ液に、消毒作用があるんだった！\nキャロ、早くPlayerNameを助けてあげて！",
  ui_story_5029_50290009_122_dialog_content = "ルルル！",
  ui_story_5029_50290009_123_dialog_content = "だ、大丈夫だよ、大したケガじゃないから…\nそれより、調査を続けよう。",
  ui_story_5029_50290009_124_option_content = "カウンター",
  ui_story_5029_50290009_125_dialog_content = "カウンターの上に置いてある本は、\n調べてみた？",
  ui_story_5029_50290009_126_dialog_content = "どれどれ…『赤浪サメ之助伝・第1巻』？",
  ui_story_5029_50290009_127_dialog_content = "ただの作り話じゃない。",
  ui_story_5029_50290009_128_dialog_content = "あたしは、師匠の『ふしぎな小動物』の方が好き！",
  ui_story_5029_50290009_129_dialog_content = "ふ～ん？",
  ui_story_5029_50290009_130_dialog_content = "な、なに…？",
  ui_story_5029_50290009_131_dialog_content = "口では師匠のことを悪く言ってるけど、\n本当はやっぱり、尊敬してるんだね！",
  ui_story_5029_50290009_132_dialog_content = "まぁ、そうでもなきゃ、\n何かにつけて「師匠」のことを話すはずないよね。",
  ui_story_5029_50290009_133_dialog_content = "偶然、ただの偶然だよ！",
  ui_story_5029_50290009_134_dialog_content = "分かったよ。\nじゃあ、調査を続けよう。",
  ui_story_5029_50290009_135_option_content = "一通り調べ終わった",
  ui_story_5029_50290009_136_dialog_content = "じゃあ、どうする…？",
  ui_story_5029_50290009_137_dialog_content = "別の部屋を探そう！",
  ui_story_5029_50290009_138_dialog_content = "次はどこにする？",
  ui_story_5029_50290009_139_option_content = "もう調べるべき所はない",
  ui_story_5029_50290009_140_dialog_content = "調べられる所は全部、調べたと思う。",
  ui_story_5029_50290009_141_dialog_content = "はぁ、やっと一休みできる…",
  ui_story_5029_50290009_142_dialog_content = "あれ、ちょっと待って。\nキャロがまたどっか行っちゃった。",
  ui_story_5029_50290009_143_dialog_content = "PlayerName、あたし、キャロを探してくる！",
  ui_story_5029_50290009_144_dialog_content = "分かった、気を付けて。",
  ui_story_5029_50290010_1_dialog_content = "（このお屋敷、本当に大きいな…）",
  ui_story_5029_50290010_2_dialog_content = "（どの部屋を調べよう？）",
  ui_story_5029_50290010_3_option_content = "書斎を調べる",
  ui_story_5029_50290010_4_dialog_content = "適当に見て回ろう…",
  ui_story_5029_50290010_5_option_content = "1列目の本棚",
  ui_story_5029_50290010_6_dialog_content = "この本、見覚えがある。",
  ui_story_5029_50290010_7_dialog_content = "『赤浪サメ之助伝・第1巻』…？",
  ui_story_5029_50290010_8_dialog_content = "どうして1巻しかないんだろう？",
  ui_story_5029_50290010_9_option_content = "デスク",
  ui_story_5029_50290010_10_dialog_content = "デスクの上にも本があるけど…\nボロボロだなぁ。",
  ui_story_5029_50290010_11_dialog_content = "<color=#828282>ビリッ！</color>",
  ui_story_5029_50290010_12_dialog_content = "あっ…破いちゃった！？",
  ui_story_5029_50290010_13_dialog_content = "大変だ…後で領主さんに謝らなきゃ…",
  ui_story_5029_50290010_14_dialog_content = "どうして、今日は何もかも\nうまく行かないんだろう…？",
  ui_story_5029_50290010_15_option_content = "棚",
  ui_story_5029_50290010_16_dialog_content = "銀の箱はずっと、\nこの棚の中に入れてたって言ってたね。",
  ui_story_5029_50290010_17_dialog_content = "きれいな棚だ。\n中身がなくなっちゃったのが残念だけど。",
  ui_story_5029_50290010_18_option_content = "一通り見て回った",
  ui_story_5029_50290010_19_dialog_content = "別の部屋を見て回ろう。",
  ui_story_5029_50290010_20_option_content = "ホールへ行く",
  ui_story_5029_50290010_21_dialog_content = "ホールは、がらんとしてる。",
  ui_story_5029_50290010_22_dialog_content = "適当に見て回ろう…",
  ui_story_5029_50290010_23_option_content = "植木鉢",
  ui_story_5029_50290010_24_dialog_content = "植木鉢の中に、何かしかけがあったりしないかな？",
  ui_story_5029_50290010_25_dialog_content = "クンクン…",
  ui_story_5029_50290010_26_dialog_content = "お気を付けを！\nその花には毒があるのです、直接触ってはいけません！",
  ui_story_5029_50290010_27_dialog_content = "どうしよう…何だか、頭がクラクラする…",
  ui_story_5029_50290010_28_dialog_content = "そのご様子ですと、毒が少し回ってしまったようですね。\nお休みになれば、いくらか良くなるかと存じます。",
  ui_story_5029_50290010_29_dialog_content = "ありがとう。\nでも、調査は続けられると思う…",
  ui_story_5029_50290010_30_option_content = "ソファー",
  ui_story_5029_50290010_31_dialog_content = "自分だけソファーに座って、\n皆が忙しくしてるのを見ていても、いい気分はしない…",
  ui_story_5029_50290010_32_dialog_content = "あれ？何かを踏んづけちゃったみたいだ。",
  ui_story_5029_50290010_33_dialog_content = "何かが割れた破片かな…？",
  ui_story_5029_50290010_34_dialog_content = "メイドが掃除したって言ってたから、\nもっときれいかと思ってたよ。",
  ui_story_5029_50290010_35_option_content = "飾り",
  ui_story_5029_50290010_36_dialog_content = "この巻貝、すごくきれいだなぁ。",
  ui_story_5029_50290010_37_dialog_content = "でも、事件とは関係ないね。",
  ui_story_5029_50290010_38_option_content = "一通り見て回った",
  ui_story_5029_50290010_39_dialog_content = "別の部屋を見て回ろう。",
  ui_story_5029_50290010_40_option_content = "カフェに行く",
  ui_story_5029_50290010_41_dialog_content = "カフェへ行かれるのですか？\nこちらへどうぞ。",
  ui_story_5029_50290010_42_dialog_content = "主は仕事中に人に会うことを嫌うので、\nここにカフェがあるのです。",
  ui_story_5029_50290010_43_dialog_content = "主みずからお客様にコーヒーを\nいれることもございますね。",
  ui_story_5029_50290010_44_dialog_content = "適当に見て回ろう…",
  ui_story_5029_50290010_45_option_content = "コーヒーカップ",
  ui_story_5029_50290010_46_dialog_content = "趣味がいいなぁ。\nコーヒーカップも、きれいなのがそろってる。",
  ui_story_5029_50290010_47_dialog_content = "あれっ、まだコーヒーが残ってる？",
  ui_story_5029_50290010_48_dialog_content = "<color=#828282>カチャン！</color>",
  ui_story_5029_50290010_49_dialog_content = "コーヒーの中に何かあるみたいだ…？",
  ui_story_5029_50290010_50_dialog_content = "…バッジ？",
  ui_story_5029_50290010_51_dialog_content = "…飲まなくてよかった。\nのどを詰まらせるところだったよ…",
  ui_story_5029_50290010_52_option_content = "床板",
  ui_story_5029_50290010_53_dialog_content = "あっちに何かあるけど、よく見えないな…",
  ui_story_5029_50290010_54_dialog_content = "血のついた果物ナイフ！？",
  ui_story_5029_50290010_55_dialog_content = "うわぁ！？",
  ui_story_5029_50290010_56_dialog_content = "申し訳ございません。\nお伝えするのを失念しておりましたが…",
  ui_story_5029_50290010_57_dialog_content = "果物ナイフについているのは、\nただのジャムです。",
  ui_story_5029_50290010_58_dialog_content = "ご気分がすぐれませんか？\n少しお休みになられては？",
  ui_story_5029_50290010_59_dialog_content = "だ、大丈夫だよ…落ち着けば、何てことない。",
  ui_story_5029_50290010_60_option_content = "壁",
  ui_story_5029_50290010_61_dialog_content = "壁にたくさん、きれいな油絵がかかってる。",
  ui_story_5029_50290010_62_dialog_content = "でも、今は絵を鑑賞する気分じゃない。",
  ui_story_5029_50290010_63_option_content = "一通り見て回った",
  ui_story_5029_50290010_64_dialog_content = "別の部屋を見て回ろう。",
  ui_story_5029_50290010_65_option_content = "もう見て回りたくない",
  ui_story_5029_50290010_66_dialog_content = "こんなにいろいろ調べたのに、\n何の収穫もなかった…",
  ui_story_5029_50290010_67_dialog_content = "ふぅ、皆はまだ調べてるみたいだね。",
  ui_story_5029_50290010_68_dialog_content = "僕は、一休みしよう。",
  ui_story_5029_50290011_1_dialog_content = "このソファー、気持ちいいなぁ。",
  ui_story_5029_50290011_2_dialog_content = "知らないうちに寝ちゃったよ。\nでも、そんなに長くは寝てないよね？",
  ui_story_5029_50290011_3_dialog_content = "この後は、どうしようかな…",
  ui_story_5029_50290011_4_dialog_content = "ほかの皆様は、容疑者を調べるために外出されるようですよ。\nご一緒に行かれますか？",
  ui_story_5029_50290011_5_dialog_content = "えっ、そうなの？",
  ui_story_5029_50290011_6_dialog_content = "皆、待って！",
  ui_story_5029_50290011_7_option_content = "カレンに尋ねる",
  ui_story_5029_50290011_8_dialog_content = "カレン、どこに行くつもり？",
  ui_story_5029_50290011_9_dialog_content = "この屋敷にそぐわない本が\nあったことには気付いた？",
  ui_story_5029_50290011_10_dialog_content = "そぐわない本…？\nここにある本は、そもそもほとんど知らないし…",
  ui_story_5029_50290011_11_dialog_content = "読んだことがあるのなんて、\n<color=#793f76>『赤浪サメ之助伝』</color>ぐらいだよ。",
  ui_story_5029_50290011_12_dialog_content = "そう、まさにその本よ。",
  ui_story_5029_50290011_13_dialog_content = "最初は通俗小説を読むなんて、\nエルビスらしくないと思っていたけれど…",
  ui_story_5029_50290011_14_dialog_content = "気づいたの。屋敷のあらゆるところに、\nその本が置かれている。",
  ui_story_5029_50290011_15_dialog_content = "じゃあ、領主さんも僕と同じで、\n『赤浪サメ之助伝』が好きだったの？",
  ui_story_5029_50290011_16_dialog_content = "いや…違う。\n気に入ってるなら、全巻そろえてるはずだ。",
  ui_story_5029_50290011_17_dialog_content = "でも、さっき探した時、\n『赤浪サメ之助伝』は第1巻しかなかった。",
  ui_story_5029_50290011_18_dialog_content = "さっき、ゼインに聞いてみたわ。\nエルビスはそんな通俗小説を買っていないそうよ。",
  ui_story_5029_50290011_19_dialog_content = "けれど偶然にも、昨日屋敷を訪ねて来た商人は、\nそういう小説の出版事業の話を持ってきていた…",
  ui_story_5029_50290011_20_dialog_content = "それと事件に何の関係があるの？",
  ui_story_5029_50290011_21_dialog_content = "商人の名前を聞けば、\nあなたも納得するでしょうね。",
  ui_story_5029_50290011_22_dialog_content = "え？知り合いなの？",
  ui_story_5029_50290011_23_dialog_content = "ゼインが言うには、\nその商人は、<color=#793f76>ジョム一郎</color>と名乗ったらしいわ。",
  ui_story_5029_50290011_24_dialog_content = "聞いたことないよ。\n雲島の人みたいな名前だけど…",
  ui_story_5029_50290011_25_dialog_content = "あっ、待って！\nジョム一郎って…ジョムのこと！？",
  ui_story_5029_50290011_26_dialog_content = "まったく大胆よね。\nこんなお粗末な仮名で、\n正体が分からないとでも思ったのかしら？",
  ui_story_5029_50290011_27_dialog_content = "でも、商人が本当にジョムだったとしても、\n銀の箱を盗んだのがジョムだとは限らないよ？",
  ui_story_5029_50290011_28_dialog_content = "R・Wはもともと、\nあらゆる悪さに手を染めた略奪者どもの集まりよ。",
  ui_story_5029_50290011_28X1_dialog_content = "盗みぐらい、彼らにとってはいつものことなのでしょう。",
  ui_story_5029_50290011_29_dialog_content = "けれど、不届きにも白夜城の領地に手を出すとは…",
  ui_story_5029_50290011_30_dialog_content = "私みずから、このランスで追い散らす！",
  ui_story_5029_50290011_31_dialog_content = "まぁまぁ…まずはジョムに直接、聞いてみようよ。",
  ui_story_5029_50290011_32_dialog_content = "私もそのつもりよ。",
  ui_story_5029_50290011_33_dialog_content = "ちょうど、ジョムに話を聞きに行く所だったの。",
  ui_story_5029_50290011_34_option_content = "僕も一緒に行くよ",
  ui_story_5029_50290011_35_dialog_content = "いいわ、行きましょう。",
  ui_story_5029_50290011_36_option_content = "がんばって",
  ui_story_5029_50290011_37_dialog_content = "ありがとう。",
  ui_story_5029_50290011_38_option_content = "バイスに尋ねる",
  ui_story_5029_50290011_39_dialog_content = "バイス、どこに行くつもり？",
  ui_story_5029_50290011_40_dialog_content = "そもそもあるはずのない物が\nカフェにあったこと、覚えてる？",
  ui_story_5029_50290011_41_dialog_content = "「あるはずのない物」？",
  ui_story_5029_50290011_42_dialog_content = "コーヒーカップの中に入ってた、\n<color=#793f76>白夜城の騎士のバッジ</color>のことだね。",
  ui_story_5029_50290011_43_dialog_content = "ええ、そのバッジ。",
  ui_story_5029_50290011_44_dialog_content = "領主のコレクションかと思っていたけど…",
  ui_story_5029_50290011_45_dialog_content = "そうだね。ハーバーシティは白夜城の属領だし、\n領主さんが騎士のバッジを持っていてもおかしくはない…",
  ui_story_5029_50290011_46_dialog_content = "でも、コレクションだとしたら、\nきちんと大事に保管してるはずだ。",
  ui_story_5029_50290011_47_dialog_content = "お客に出したコーヒーの中に入ってるなんて、\nそんなはずはない…",
  ui_story_5029_50290011_48_dialog_content = "そう。ということは、\n可能性は1つしかないわ。",
  ui_story_5029_50290011_49_dialog_content = "あのバッジは、お客の誰かのものよ。",
  ui_story_5029_50290011_50_dialog_content = "昨日の客の中に、\nちょうど白夜城の人がいたそうじゃない。",
  ui_story_5029_50290011_51_dialog_content = "白夜城の公爵っていう人？",
  ui_story_5029_50290011_52_dialog_content = "領主さん、その公爵のことは確か…\nイスク公爵って呼んでたかな…？",
  ui_story_5029_50290011_53_dialog_content = "そのイスク公爵のフルネーム、知ってる？",
  ui_story_5029_50290011_54_dialog_content = "<color=#793f76>バーバリー・イスク</color>って言うの。",
  ui_story_5029_50290011_55_dialog_content = "えっ…バーバリー？",
  ui_story_5029_50290011_56_dialog_content = "…でも本当にバーバリーの物だとしても、\n彼女が事件と関係あるって証拠にはならないんじゃない？",
  ui_story_5029_50290011_57_dialog_content = "さっきゼインさんに聞いたの。\n昨日、領主とちょっとした言い争いになってたらしいわ。",
  ui_story_5029_50290011_58_dialog_content = "バーバリーがそれを根に持って、\n銀の箱を盗んだってこと？",
  ui_story_5029_50290011_59_dialog_content = "そんなことするような人じゃないと思うけど…",
  ui_story_5029_50290011_60_dialog_content = "白夜城に留学して、\n気付いたことがあるの。",
  ui_story_5029_50290011_61_dialog_content = "自分は高貴な身分だってひけらかす貴族ほど、\n裏でとんでもないことをしているものよ。",
  ui_story_5029_50290011_62_dialog_content = "バーバリーさんだって、\nいつも「貴族」って言葉を口にしてるし…",
  ui_story_5029_50290011_63_dialog_content = "…と言っても、私も疑いたくないわ。\nだから、ちゃんと話を聞きたいの。",
  ui_story_5029_50290011_64_option_content = "僕も一緒に行くよ",
  ui_story_5029_50290011_65_dialog_content = "そう言うと思ってたわ。\nさあ、行きましょう！",
  ui_story_5029_50290011_66_option_content = "がんばって",
  ui_story_5029_50290011_67_dialog_content = "そういうことは、他の人に言ってあげて。",
  ui_story_5029_50290011_68_option_content = "フィアに尋ねる",
  ui_story_5029_50290011_69_dialog_content = "フィア、何しにいくの？",
  ui_story_5029_50290011_70_dialog_content = "シーッ…大きな声出さないで。",
  ui_story_5029_50290011_71_dialog_content = "大事な手がかりが見つかったの。\nほかの人に知られたらマズいでしょ？",
  ui_story_5029_50290011_72_dialog_content = "大事な手がかりって、\nソファーの下にあった<color=#793f76>破片</color>のこと？",
  ui_story_5029_50290011_73_dialog_content = "破片だからって、バカにしちゃダメ！\nゼインおじさんに聞いたんだよ。",
  ui_story_5029_50290011_74_dialog_content = "ほんとなら、ソファーの下も、\nメイドが掃除しなくちゃいけない場所の1つなんだって。",
  ui_story_5029_50290011_75_dialog_content = "たまたま、そのメイドの仕事が\n雑だっただけじゃないの？",
  ui_story_5029_50290011_76_dialog_content = "ふん、それだけなら\nフィアだって疑ったりしないよ。",
  ui_story_5029_50290011_77_dialog_content = "重要なのは…\nそのメイドの経歴が怪しいってこと！",
  ui_story_5029_50290011_78_dialog_content = "「経歴が怪しい」？\n確か、影ノ街の商会を通してるって話じゃなかった？",
  ui_story_5029_50290011_79_dialog_content = "僕が思うに、\nあの商会は信頼できると思うけど…",
  ui_story_5029_50290011_80_dialog_content = "はあ…PlayerName、もう子供じゃないでしょ？\nなんでそんな単細胞なの？",
  ui_story_5029_50290011_81_dialog_content = "珍獣マスター兼、影ノ街の住民兼、空の末裔のご主人様兼、\n新人探偵でもある、このフィアが教えてあげる！",
  ui_story_5029_50290011_82_dialog_content = "影ノ街もハーバーシティも、\n貿易で大きくなった都市なんだよ。",
  ui_story_5029_50290011_83_dialog_content = "もともとは影ノ街が一番大きくてにぎやかな貿易の場所だったけど…",
  ui_story_5029_50290011_84_dialog_content = "でも、あたしの見た限り…\nハーバーシティの成長ぶりは、影ノ街を追い越す勢い！",
  ui_story_5029_50290011_85_dialog_content = "それで、影ノ街の商会が一体なんのために、\nメイドを紹介したのか…？",
  ui_story_5029_50290011_86_dialog_content = "なんのため？",
  ui_story_5029_50290011_87_dialog_content = "真実は1つ！メイドを使って、\nビジネスの秘密を盗むため！",
  ui_story_5029_50290011_88_dialog_content = "そして、それがきっと、\n銀の箱の中に隠されてたんだ！",
  ui_story_5029_50290011_89_dialog_content = "反論の根拠もない気がするけど、\n信用しがたい話だなぁ…",
  ui_story_5029_50290011_90_dialog_content = "そのマナエっていうメイド、今の時間は別のお屋敷で\n働いてるらしいから、捕まえに行くの！",
  ui_story_5029_50290011_91_dialog_content = "ちょっと待って…\nメイドの名前、何だって？",
  ui_story_5029_50290011_92_dialog_content = "<color=#793f76>マナエ</color>だよ。\nどうかした？",
  ui_story_5029_50290011_93_dialog_content = "聞き覚えのある名前なんだよね…",
  ui_story_5029_50290011_94_option_content = "僕も一緒に行くよ",
  ui_story_5029_50290011_95_dialog_content = "シーッ、こっそり出ないと！\nほかの2人に見つからないようにね！",
  ui_story_5029_50290011_96_option_content = "とにかく、がんばって",
  ui_story_5029_50290011_97_dialog_content = "あたしが見つけた手がかりのこと、\nほかの人には言わないでよね。",
  ui_story_5029_50290011_98_dialog_content = "じゃないと、キャロに追いかけさせるから！",
  ui_story_5029_50290011_99_dialog_content = "ルルル！",
  ui_story_5029_50290011_100_option_content = "自分だけ残る",
  ui_story_5029_50290011_101_dialog_content = "どういうことだろう？",
  ui_story_5029_50290011_102_dialog_content = "なんで、僕1人だけ残ってるんだろう…",
  ui_story_5029_50290012_1_dialog_content = "ジョムのやつ！\nこんな高級ホテルに泊まるお金を持ってたの！？",
  ui_story_5029_50290012_2_dialog_content = "こうなると、僕もジョムが疑わしく思えてきた…\nちゃんと事情を聴かなきゃ！",
  ui_story_5029_50290012_3_dialog_content = "ただ、1つ問題があるわ。",
  ui_story_5029_50290012_4_dialog_content = "エルビスには、秘密で調査してほしいと言われているでしょう。\nジョムの部屋を直接聞くわけにはいかないのよ。",
  ui_story_5029_50290012_5_dialog_content = "僕たちも宿泊客のふりをすればいいよ。",
  ui_story_5029_50290012_6_dialog_content = "そうすれば、正々堂々ホテルの中の様子を観察できる。",
  ui_story_5029_50290012_7_dialog_content = "入ってから、ゆっくりジョムを探せばいいでしょ。",
  ui_story_5029_50290012_8_dialog_content = "悪くないと思うけれど…\n無関係の人たちをだますのは、気が引けるわね。",
  ui_story_5029_50290012_9_dialog_content = "僕たちはただ、事件の調査をしてるだけで、\n誰かを傷つけようとしてるわけじゃないし…",
  ui_story_5029_50290012_10_dialog_content = "こういうのは、「善意のウソ」って\n言っていいんじゃないかな？",
  ui_story_5029_50290012_11_dialog_content = "それに、僕が話すよ。\nカレンは側に立ってるだけでいいから。",
  ui_story_5029_50290012_12_dialog_content = "それはよくないわ。私も全力を尽くす。\n責任を仲間に押し付けるようなことはしたくないの。",
  ui_story_5029_50290012_13_dialog_content = "いらっしゃいませ。\nご予約はございますか？",
  ui_story_5029_50290012_14_dialog_content = "オ、オホン…よ、予約はないの。",
  ui_story_5029_50290012_15_dialog_content = "（カレンはウソが下手だ…）",
  ui_story_5029_50290012_16_dialog_content = "ええと、実は…",
  ui_story_5029_50290012_17_option_content = "僕が環境にうるさいもので",
  ui_story_5029_50290012_18_dialog_content = "え？",
  ui_story_5029_50290012_19_option_content = "彼女が環境にうるさいもので",
  ui_story_5029_50290012_20_dialog_content = "え？",
  ui_story_5029_50290012_21_dialog_content = "まずは中を見てから、\n決めさせてもらいたいなと。",
  ui_story_5029_50290012_22_dialog_content = "承知致しました、構いません。\n失礼ですが、お客様のお名前は？",
  ui_story_5029_50290012_23_dialog_content = "PlayerNameです。",
  ui_story_5029_50290012_24_dialog_content = "PlayerName様、奥様、こちらへどうぞ。",
  ui_story_5029_50290012_25_dialog_content = "当ホテルで一番豪華なお部屋へご案内いたしますね。\nお2人のハネムーンに色を添えられること、間違いございません。",
  ui_story_5029_50290012_26_dialog_content = "…！？",
  ui_story_5029_50290012_27_dialog_content = "あの、僕たちは…",
  ui_story_5029_50290012_28_dialog_content = "失礼、新婚旅行ではございませんでしたか？",
  ui_story_5029_50290012_29_dialog_content = "そうです！",
  ui_story_5029_50290012_30_dialog_content = "違います！",
  ui_story_5029_50290012_31_dialog_content = "おや、お二人で違うお答えとは…？",
  ui_story_5029_50290012_32_dialog_content = "（マズい、疑い始めてる！どうしよう？）",
  ui_story_5029_50290012_33_dialog_content = "（でも、カレンは今、はっきり肯定したし…）",
  ui_story_5029_50290012_34_dialog_content = "（か、考えてる場合じゃない！\nとにかく早く、ごまかさないと）",
  ui_story_5029_50290012_35_dialog_content = "お客様…当ホテルへは、\n本当にご宿泊の意志がおありで？",
  ui_story_5029_50290012_36_dialog_content = "もちろんです…",
  ui_story_5029_50290012_37_dialog_content = "ごめんなさい…わ、私たち、\n実は婚約したばかりで。",
  ui_story_5029_50290012_38_dialog_content = "私にとっては新婚も同然ですけれど…",
  ui_story_5029_50290012_39_dialog_content = "盛大に結婚式を祝ってからでないと、\n新婚とは言えないって、\nこの人はいつも言っているので…",
  ui_story_5029_50290012_40_dialog_content = "そうでしたか。お気持ちはよく分かります！\nこの世にたった1度の結婚式、\n盛大に挙げたいと思うものですよね。",
  ui_story_5029_50290012_41_dialog_content = "これは、見間違いでしょうか…？",
  ui_story_5029_50290012_42_dialog_content = "ジョム…アハハハ、ぐ、偶然だね。",
  ui_story_5029_50290012_43_dialog_content = "ボス、本当にボスなんですか！？\nなんだって白夜城の…むぐっ…\nどうして口を塞ぐんです？",
  ui_story_5029_50290012_44_dialog_content = "あ、あの、偶然、古い友人に会えたので…\n見学の続きは後でいいですか？",
  ui_story_5029_50290012_45_dialog_content = "はい、いつでもお申し付けください！",
  ui_story_5029_50290012_46_dialog_content = "…秘密の調査？そういうことでしたか。\nそれで身分を隠していたんですね。",
  ui_story_5029_50290012_47_dialog_content = "ハハハ！もし本当に空の末裔と\n白夜城の姫が結婚なんてことでしたら、\nボスが何をしでかすか、分からないところでした。",
  ui_story_5029_50290012_48_dialog_content = "うちのボス、毎日のようにPlayerNameさんが\nR・Wに入らないか、期待してますからね。",
  ui_story_5029_50290012_49_dialog_content = "彼に何ができるというのかしら？",
  ui_story_5029_50290012_50_dialog_content = "オッホン！その話はひとまず置いておこう…\nジョム、どうしてハーバーシティにいるの？",
  ui_story_5029_50290012_51_dialog_content = "もちろん、商売のためですよ。",
  ui_story_5029_50290012_52_dialog_content = "また、よからぬことでも企んでいるのかしら？",
  ui_story_5029_50290012_53_dialog_content = "誤解ですよ、濡れ衣です！",
  ui_story_5029_50290012_54_dialog_content = "白夜城のお姫様でしょう？\n根も葉もない風評はカンベンしてくださいよ。",
  ui_story_5029_50290012_55_dialog_content = "きちんとした商談に来たんですよ。\n昨日はハーバーシティの領主ともお話させてもらいました。",
  ui_story_5029_50290012_56_dialog_content = "そう…昨日領主と会ったのは、\n雲島の商人だと聞いているけれど？",
  ui_story_5029_50290012_57_dialog_content = "ジョム一郎は、先祖代々雲島で出版業にたずさわる家柄で、\nアストラ大陸で共同事業のパートナーを探しているのです。",
  ui_story_5029_50290012_58_dialog_content = "極東風の伝記小説を\n広めようと尽力しているところで…",
  ui_story_5029_50290012_59_dialog_content = "で、君がその「ジョム一郎」なの？",
  ui_story_5029_50290012_60_dialog_content = "ボス、ビジネスには欠かせない方便ってヤツですよ。\nそうでも言わなければ、領主様は面会もしてくれないでしょう？",
  ui_story_5029_50290012_61_dialog_content = "書籍出版のための資金や土地、\n人材の投資まで、どうやって引き出せというんです？",
  ui_story_5029_50290012_62_dialog_content = "私の知る限り、あなたの要求があまりにも不合理だったから、\n共同事業は断られたのでしょう？",
  ui_story_5029_50290012_63_dialog_content = "それは今だけのことです。\nきっとそのうち、気が変わりますよ…",
  ui_story_5029_50290012_64_dialog_content = "しかし、妙ですね。\n今日は質問ばかりされる気が…？",
  ui_story_5029_50290012_65_dialog_content = "まさか、俺を調べているんですか？",
  ui_story_5029_50290012_66_option_content = "違うよ",
  ui_story_5029_50290012_67_dialog_content = "誤解しないで。\n僕はただ、友だちを心配してるだけだよ。",
  ui_story_5029_50290012_68_dialog_content = "ボスが俺のことを心配してくれていたとは…\n感動しましたよ！",
  ui_story_5029_50290012_69_dialog_content = "うまく契約出来たら、2人にごちそうしますよ！",
  ui_story_5029_50290012_70_dialog_content = "ありがとう。ただ…",
  ui_story_5029_50290012_71_option_content = "そうだよ",
  ui_story_5029_50290012_72_dialog_content = "シッ…秘密調査だということを忘れないで。",
  ui_story_5029_50290012_73_dialog_content = "オホン！ええ、そうよ。",
  ui_story_5029_50290012_74_dialog_content = "領主様に代わって、口から出まかせばかりの、\nある商人の正体を調べてるの。",
  ui_story_5029_50290012_75_dialog_content = "あなたの説明を聞いて、\n大方のことは分かったわ。",
  ui_story_5029_50290012_76_dialog_content = "確かに、この事業には手を出さないほうがいいわね。",
  ui_story_5029_50290012_77_dialog_content = "…確かに俺は、自分の身分を適度にいつわりましたよ。",
  ui_story_5029_50290012_78_dialog_content = "でも、ビジネスの内容に関しては誠心誠意、\nウソはありません。",
  ui_story_5029_50290012_79_dialog_content = "『赤浪サメ之助伝』は、\nもっと多くの読者を獲得できる本です！",
  ui_story_5029_50290012_80_dialog_content = "そう確信を得てから、\n俺の人生は輝き出したんですよ！",
  ui_story_5029_50290012_81_dialog_content = "この文化の発達した港町へ\n遠路はるばるやってきたのも…",
  ui_story_5029_50290012_81X1_dialog_content = "この本の大規模出版を一緒に手がけてくれる\nパートナーを求めてのことです。",
  ui_story_5029_50290012_82_dialog_content = "俺はもう、あなたたちの知っている、\nインチキ商人ではないんです！",
  ui_story_5029_50290012_83_dialog_content = "どうか、色眼鏡で見ないでください！",
  ui_story_5029_50290012_84_dialog_content = "PlayerName…どう思う？",
  ui_story_5029_50290012_85_dialog_content = "ジョムが言ってること自体は、\nウソじゃない気がする。",
  ui_story_5029_50290012_86_dialog_content = "もし本当に、事業のパートナーを探してるって言うなら、\n物を盗んでトラブルを増やしたりする余裕はないはず。",
  ui_story_5029_50290012_87_dialog_content = "今の話を聞いて、\n私も、少し申し訳なく思えてきたわ。",
  ui_story_5029_50290012_88_dialog_content = "何の理由もなく、彼の動機を疑うべきではなかった。\nただ…",
  ui_story_5029_50290012_89_dialog_content = "いくつか、きちんと\n聞いておくべきことがあるわね。",
  ui_story_5029_50290012_90_dialog_content = "例えば…なぜエルビスの屋敷に、\nあれほど多くの『赤浪サメ之助伝』が置いてあったのか。",
  ui_story_5029_50290012_91_dialog_content = "ジョムが昨日、何気なく部屋に\n置いていったのかもしれないよ…？",
  ui_story_5029_50290012_92_dialog_content = "お2人も領主様のご家族ですか？\nごきげんよう！",
  ui_story_5029_50290012_93_dialog_content = "あなたは…？",
  ui_story_5029_50290012_94_dialog_content = "サニーと申します！ホテルのお庭の雑草刈りをしている庭師です。\n昨日は領主様のお屋敷にもうかがって、\n仕事をさせていただいたんですよ。",
  ui_story_5029_50290012_95_dialog_content = "どうして私たちが領主の家族だと？",
  ui_story_5029_50290012_96_dialog_content = "えっ、間違っていましたか？\n申し訳ございません！",
  ui_story_5029_50290012_97_dialog_content = "先程の緑色の髪をした男性が\n領主様の家の方と言っていたので、\nお2人もてっきりそうなのかと…",
  ui_story_5029_50290012_98_dialog_content = "領主のお屋敷で彼に会ったの？",
  ui_story_5029_50290012_99_dialog_content = "はい！昨日の夜のことです。\n間違いありません。",
  ui_story_5029_50290012_100_dialog_content = "芝生を刈り終わって、地面に座って休んでいたら、\n領主様とあの方が部屋から\n連れ立って出てくるのを見たんです。",
  ui_story_5029_50290012_101_dialog_content = "その後すぐに、忘れ物でもしたのか、\n戻って鍵を開けて、中に入って行きました。\n出てくるまでしばらくかかってました。",
  ui_story_5029_50290012_102_dialog_content = "…",
  ui_story_5029_50290012_103_dialog_content = "PlayerName、まだジョムを信じる？",
  ui_story_5029_50290012_104_dialog_content = "本当にジョムが…？",
  ui_story_5029_50290012_105_dialog_content = "わ、私、何かいけないことを話しましたか…？",
  ui_story_5029_50290012_106_dialog_content = "いいえ、サニー。\nとても助かったわ。",
  ui_story_5029_50290012_107_dialog_content = "あなたの刈ったという芝生も、\nとてもきれいだったわ。",
  ui_story_5029_50290012_108_dialog_content = "チェックアウトは済みました。\nまたのお越しをお待ちしております！",
  ui_story_5029_50290012_109_dialog_content = "また宿泊してほしいなら…\n何冊か『赤浪サメ之助伝』を\nホテルに置いてくださいませんか？",
  ui_story_5029_50290012_110_dialog_content = "ええっ…？",
  ui_story_5029_50290012_111_dialog_content = "ジョム。",
  ui_story_5029_50290012_112_dialog_content = "…これはこれは、お2人でしたか。\nまだお話がありましたか？\n今、商談の最中なんですよ。",
  ui_story_5029_50290012_113_dialog_content = "君にまだ、\nいくつか質問したいことがあるんだ。",
  ui_story_5029_50290012_114_dialog_content = "昨日の晩、領主と会った後。\nこっそり領主の書斎に戻ったわね？",
  ui_story_5029_50290012_115_dialog_content = "ああ、領主様に言われて、\nこっそり俺を訪ねて来たんですね？",
  ui_story_5029_50290012_116_dialog_content = "どうです？領主様も第1巻を読み終わって、\nすっかりこの本のとりこでしょう？",
  ui_story_5029_50290012_117_dialog_content = "今すぐにでも第2巻を\n読みたがっているのではないですか？",
  ui_story_5029_50290012_118_dialog_content = "そして、共同出版事業について、お話をしたいと。\nそういうことですね？",
  ui_story_5029_50290012_119_dialog_content = "領主の書斎に侵入したことを認めるのね？",
  ui_story_5029_50290012_120_dialog_content = "領主様もこの本に魅せられたからには、\n俺にもう隠す理由はありません。",
  ui_story_5029_50290012_121_dialog_content = "昨日は確かに共同事業について、\n合意を得られませんでした。",
  ui_story_5029_50290012_122_dialog_content = "でもそれはきっと、領主様がこの本の素晴らしさを\n知らないからだと俺は思ったんですよ。",
  ui_story_5029_50290012_123_dialog_content = "第1巻を読めば、この本がいかに投資価値のあるものか、\nきっと分かってもらえるはずです！",
  ui_story_5029_50290012_124_dialog_content = "そう思って、俺は書斎に引き返して、\n第1巻を領主様の目につきそうなところにわざと置きました。",
  ui_story_5029_50290012_125_dialog_content = "たっぷり5冊も置いていきましたよ！\nですが、成功のための必要経費というヤツです。",
  ui_story_5029_50290012_126_dialog_content = "領主様の気が変わったなら、\nそのかいはありましたね。ハハハ…",
  ui_story_5029_50290012_127_dialog_content = "私たちの探し方が甘かったみたいね。\n5冊あることまでは把握していなかったわ。",
  ui_story_5029_50290012_128_dialog_content = "本当にそれだけの理由で、\n領主の書斎にこっそり戻ったの？",
  ui_story_5029_50290012_129_dialog_content = "そうですよ。領主様はどちらにいらっしゃいますか？\n今すぐ第2巻をお届けします！",
  ui_story_5029_50290012_130_dialog_content = "今は公務で忙しくしているわ。あと数日留まれるなら、\n私が領主に口をきいて、面会の場を用意してあげましょう。",
  ui_story_5029_50290012_131_dialog_content = "困りましたね。有り金は使い果たしてしまったんです…\nそういうことなら、安宿に換えるしかありませんね。",
  ui_story_5029_50290012_132_dialog_content = "まともな商売とは、実に難しいものです…",
  ui_story_5029_50290013_1_dialog_content = "やっぱり遅かったわね…\nお芝居、もう始まってる！",
  ui_story_5029_50290013_2_dialog_content = "バーバリー、本当にこの劇場にいるの？",
  ui_story_5029_50290013_3_dialog_content = "間違いないわ。",
  ui_story_5029_50290013_4_dialog_content = "バーバリーさんがハーバーシティに来てる一番の目的は、\nこのお芝居を鑑賞するためなの。",
  ui_story_5029_50290013_5_dialog_content = "今日だけでも公演なんて何回もあるよ。\nどうしてこの回だって分かるの？",
  ui_story_5029_50290013_6_dialog_content = "ゼインだって、バーバリーがいつ、\nどのお芝居を観るのかまでは知らなかったんだよ？",
  ui_story_5029_50290013_7_dialog_content = "でも、ゼインさんが言ってたでしょ。\nバーバリーさんは何かの芝居の初演を観に来たって！",
  ui_story_5029_50290013_8_dialog_content = "今日の演目を全部調べてみたけど…",
  ui_story_5029_50290013_9_dialog_content = "まず、今日が初演なのは、3つしかないの。",
  ui_story_5029_50290013_10_dialog_content = "1つは現代劇だから、\nバーバリーさんの好みに合わないわ。",
  ui_story_5029_50290013_11_dialog_content = "もう1つは、白夜城でもよく上演されてるものよ。\nわざわざここまで観に来る必要がないわ。",
  ui_story_5029_50290013_12_dialog_content = "で、残った演目が、この『ロミーとジュリー』なの。",
  ui_story_5029_50290013_13_dialog_content = "バイス、君って…",
  ui_story_5029_50290013_14_option_content = "ホンモノの探偵みたいだ",
  ui_story_5029_50290013_15_dialog_content = "探偵事務所が開けそう！",
  ui_story_5029_50290013_16_dialog_content = "エヘヘ…",
  ui_story_5029_50290013_17_option_content = "ちょっと怖い",
  ui_story_5029_50290013_18_dialog_content = "君には隠し事ができなさそうな気がして…",
  ui_story_5029_50290013_19_dialog_content = "オホン…オホン！",
  ui_story_5029_50290013_20_dialog_content = "そ、そんな大げさなことじゃないわ？",
  ui_story_5029_50290013_21_dialog_content = "もう長い付き合いでしょ。\n私のこと、まだ分かってないの？",
  ui_story_5029_50290013_22_dialog_content = "私の強みなんて行動力ぐらいよ。",
  ui_story_5029_50290013_23_dialog_content = "でも、今から中に入って話を聞くわけにはいかないわ。\n上演が終わるのを待つしかないわね。",
  ui_story_5029_50290013_24_dialog_content = "すでに前座の演目が始まっております。\nお客様、中にお入りにならなくてよろしいのですか？",
  ui_story_5029_50290013_25_dialog_content = "ありがとう。\nでも、実は僕たち、チケットを持ってないんだ…",
  ui_story_5029_50290013_26_dialog_content = "おや？ご存じありませんでしたか？",
  ui_story_5029_50290013_27_dialog_content = "『ロミーとジュリー』初演の御礼として、\n2人組でご観劇の場合、チケットが半額になりますよ。",
  ui_story_5029_50290013_28_dialog_content = "このような機会はめったにございません！",
  ui_story_5029_50290013_29_dialog_content = "2人で半額…大サービスだね！？",
  ui_story_5029_50290013_30_dialog_content = "でも、もう売り切れてるんじゃない？",
  ui_story_5029_50290013_31_dialog_content = "そうだったのですが、先ほどカップルのお客様が\nケンカ別れしてしまったようで。\nちょうど1組様分がキャンセルになったところです。",
  ui_story_5029_50290013_32_dialog_content = "別れた？",
  ui_story_5029_50290013_33_dialog_content = "別れてしまったカップルのチケットというと、\nあまり縁起の良いものではありませんが…",
  ui_story_5029_50290013_34_dialog_content = "お二人はとても仲がよろしいようですので、\nきっと簡単に別れたりはなさらないでしょう！",
  ui_story_5029_50290013_35_dialog_content = "僕たちはそういうわけじゃ…",
  ui_story_5029_50290013_36_dialog_content = "お2人が気になさらないということでしたら、\n90％引きにさせていただきますよ。",
  ui_story_5029_50290013_37_dialog_content = "えっ！？",
  ui_story_5029_50290013_38_dialog_content = "バイス、もしかしてお芝居に興味あるの？",
  ui_story_5029_50290013_39_dialog_content = "どうせ終わるまで待たないといけないなら、\n見ながら待ってもいいんじゃない？",
  ui_story_5029_50290013_40_dialog_content = "ありがとう！PlayerNameのことだから、\nチケット代も出し惜しむかもと思ってたわ。",
  ui_story_5029_50290013_41_dialog_content = "ありがとうございます。\nどうぞ末永くお幸せに！",
  ui_story_5029_50290013_42_dialog_content = "…",
  ui_story_5029_50290013_43_dialog_content = "え、ええと…は、はい…",
  ui_story_5029_50290013_44_dialog_content = "（誤解されてる…）",
  ui_story_5029_50290013_45_dialog_content = "（でも、これだけうれしそうに親切にされると、\n訂正するのも何だか悪い気がしてしまう…）",
  ui_story_5029_50290013_46_dialog_content = "（バイスも…同じ考えなのかな？）",
  ui_story_5029_50290013_47_dialog_content = "さ、さあ、急いで中に入りましょ！",
  ui_story_5029_50290013_48_dialog_content = "うん！",
  ui_story_5029_50290013_49_dialog_content = "<color=#828282>しばらくして</color>",
  ui_story_5029_50290013_50_dialog_content = "ううっ…",
  ui_story_5029_50290013_51_dialog_content = "こんなに感動的だとは思ってなかったわ！",
  ui_story_5029_50290013_52_dialog_content = "前半の、2人が花畑で出会う場面、\nとってもロマンチックだった…！",
  ui_story_5029_50290013_53_dialog_content = "その通りね。",
  ui_story_5029_50290013_54_dialog_content = "バーバリー！？",
  ui_story_5029_50290013_55_dialog_content = "（お芝居に夢中になって、仕事のことを忘れてた！）",
  ui_story_5029_50290013_56_dialog_content = "後半の残酷さを際立たせるための\n前半の美しさと考えると、悲しい気もするけれど。",
  ui_story_5029_50290013_57_dialog_content = "2人はさまざまな障害や誤解が重なって、\n最初に出会った花畑で一人、また一人と倒れてしまう…",
  ui_story_5029_50290013_58_dialog_content = "最初と最後の対照は、\n悲劇の美学における最高の境地と言ってもいいわ。",
  ui_story_5029_50290013_59_dialog_content = "悲劇があんなに美しく描けるなんて、\n思わなかったわ、ぐすん…",
  ui_story_5029_50290013_60_dialog_content = "あなたたち二人もこのお芝居を観に来ているとは、\nわたくしも意外だったわ。",
  ui_story_5029_50290013_61_dialog_content = "オ、オホン！本当だね…すごい偶然だ！",
  ui_story_5029_50290013_62_dialog_content = "このお芝居、表現自体は伝統的な形式だけど、\n話の中心になってた部分は、かなり新しい考え方だったわ。",
  ui_story_5029_50290013_63_dialog_content = "実際、このお芝居は近年で唯一の新作なの。",
  ui_story_5029_50290013_64_dialog_content = "けれど、主人公2人の悲劇は、\n結局のところ、身分の差から生まれたもの…",
  ui_story_5029_50290013_65_dialog_content = "もし2人が出会った時に互いの身分をわきまえて、\nしっかりと線を引いていれば…",
  ui_story_5029_50290013_65X1_dialog_content = "また別の結末になっていたかもしれないわね。",
  ui_story_5029_50290013_66_dialog_content = "わ、私は…そうは思わないわ。",
  ui_story_5029_50290013_67_dialog_content = "2人の死は、世間へのメッセージだと思うの。",
  ui_story_5029_50290013_68_dialog_content = "このお芝居は実のところ、自我の解放を訴えてるのよ。\n身分の縛りを越えて、自由に恋愛しなさいって。",
  ui_story_5029_50290013_69_dialog_content = "なるほど、そうかも知れない…",
  ui_story_5029_50290013_70_dialog_content = "そんなお芝居の上演に領主が許可を出すということ、\n考えてもみなかったわね。",
  ui_story_5029_50290013_71_dialog_content = "バーバリー、領主さんと知り合いなの？",
  ui_story_5029_50290013_72_dialog_content = "ええ、きのう面会に行ったわ。\n残念ながら、おたがいに気まずいまま別れてしまったけれど。",
  ui_story_5029_50290013_73_dialog_content = "どうして？いい人そうに見えたけど。",
  ui_story_5029_50290013_74_dialog_content = "彼は祖先が白夜城に従属したから\n貴族として序列されているにすぎないの。",
  ui_story_5029_50290013_75_dialog_content = "白夜城貴族としての称号を持ってはいるけれど、\n実際には、彼に貴族の血は流れていない。",
  ui_story_5029_50290013_76_dialog_content = "そのことを、軽率に口に出してしまったのよ。",
  ui_story_5029_50290013_77_dialog_content = "発展しているこの街に比べて、\nイスク家の領土は衰退している…\nというような皮肉を返されたわ。",
  ui_story_5029_50290013_78_dialog_content = "わたくしもつい腹を立てて、\nそのまま屋敷を立ち去ってしまったの。",
  ui_story_5029_50290013_79_dialog_content = "今思えば、わたくしも昨日は非礼に過ぎたわ。\n貴族の品位に欠ける行いだった。",
  ui_story_5029_50290013_80_dialog_content = "そんな風に反省できるなら、\nそれだけでもう、大きな進歩よ。",
  ui_story_5029_50290013_81_dialog_content = "『ロミーとジュリー』の2人の家も、\nそういう考えを持って、お互いに譲っていたら…",
  ui_story_5029_50290013_82_dialog_content = "悲劇は起こらなかったんじゃないかしら。",
  ui_story_5029_50290013_83_dialog_content = "ありがとう、バイスさん。",
  ui_story_5029_50290013_84_dialog_content = "わたくし、あなたが先ほど言っていたことを理解するためにも、\nもう1度このお芝居を観るべきね。",
  ui_story_5029_50290013_85_dialog_content = "次の回のチケットを買っておかないと。",
  ui_story_5029_50290013_86_dialog_content = "バーバリーさん、思ったことを誠実に話してくれていた気がする…\n彼女が物を盗むなんて、私には思えないわ。",
  ui_story_5029_50290013_87_dialog_content = "そうだね。本当に自分が貴族だからって威張るような人なら、\n自分の行いを反省したりはしないだろうし。",
  ui_story_5029_50290013_88_dialog_content = "白夜城で生まれ育ったから、どうしても貴族的な思想の\n影響を受けてしまうのでしょうね。",
  ui_story_5029_50290013_89_dialog_content = "「貴族の血統」にこだわることとか、きっとそう。",
  ui_story_5029_50290013_90_dialog_content = "『ロミーとジュリー』を何度も観れば、\nきっと物語の中に隠されてるメッセージが伝わって…",
  ui_story_5029_50290013_90X1_dialog_content = "そういう考えから、抜け出せるかもしれないわ！",
  ui_story_5029_50290013_91_dialog_content = "大事なことを聞き忘れた気がするけど…？",
  ui_story_5029_50290013_92_dialog_content = "すみません…お2人は領主様とお知り合いでしょうか？",
  ui_story_5029_50290013_93_dialog_content = "何ですか？",
  ui_story_5029_50290013_94_dialog_content = "私はワンダと言います。\nさしつかえなければ、\n領主様にお礼をお伝えいただきたいのです。",
  ui_story_5029_50290013_95_dialog_content = "昨日の夜、お屋敷の料理人として応募するため、\n領主様の所にうかがったのですが…",
  ui_story_5029_50290013_96_dialog_content = "領主様は私の作った料理を試食して誉めてくださいました。\nただ、私を料理人として雇うとはおっしゃいませんでした。",
  ui_story_5029_50290013_97_dialog_content = "望みはないものとあきらめていたところ、\n今朝になって、領主様から「開店資金」が届いたのです。",
  ui_story_5029_50290013_98_dialog_content = "それでようやく、領主様は私がこの街でレストランを開き、\nより多くの人が私の料理を食べることを望まれていると気づきました。",
  ui_story_5029_50290013_99_dialog_content = "自分の店を持つなんて、考えたこともありませんでした。\n一言お礼をとお屋敷にうかがったのですが、護衛の方に止められまして。",
  ui_story_5029_50290013_100_dialog_content = "そこでちょうど、お2人をお見かけしたものですから、\n失礼ながら、お礼を伝えていただきたいと思ったのです。",
  ui_story_5029_50290013_101_dialog_content = "エルビスさん、本当にみんなのことを考えてる人なんだなぁ…\nもちろん！機会を見て、お礼を伝えておきます。",
  ui_story_5029_50290013_102_dialog_content = "ただ…どうして私たちが\n領主様の知り合いだと分かったんですか？",
  ui_story_5029_50290013_103_dialog_content = "先ほどお2人とお話されていた貴族の方を、\n昨日の夜に領主様のお屋敷でお見かけしたからです。",
  ui_story_5029_50290013_104_dialog_content = "それに皆さん、ちょうど領主様のことをお話しされてましたよね。\nそれで、失礼とは思いつつ、声をおかけしたんです。",
  ui_story_5029_50290013_105_dialog_content = "私たちと話していた人を…\n昨日の夜に、見かけたんですか？",
  ui_story_5029_50290013_106_dialog_content = "そうです。お屋敷の庭で結果を待っている時…",
  ui_story_5029_50290013_107_dialog_content = "あのきれいな貴族の方がお屋敷の部屋から出てきました…",
  ui_story_5029_50290013_107X1_dialog_content = "部屋にはたくさん本棚がありましたから、\nきっと書斎だと思います。",
  ui_story_5029_50290013_108_dialog_content = "とにかく…領主様に、どうかお伝えください！\n私のレストランが開店したら、ぜひいらしてくださいね！",
  ui_story_5029_50290013_109_dialog_content = "…と、いうことは…",
  ui_story_5029_50290013_110_dialog_content = "確か、エルビスさんとバーバリーさんが会ったのは午後だったわよね。\nなんで夜に見かけたのかしら…？",
  ui_story_5029_50290013_111_dialog_content = "バーバリーはまだチケットを買いにいってるはず、\nもう1度聞いてみよう！",
  ui_story_5029_50290013_112_dialog_content = "昨日の夜どこへ行ったか？",
  ui_story_5029_50290013_113_dialog_content = "フン、はっきりおっしゃればいいのよ。\nわたくしを調べるよう言われたのでしょう？",
  ui_story_5029_50290013_114_option_content = "いいや",
  ui_story_5029_50290013_115_dialog_content = "君がどんなところを見て回ったのか、聞きたいだけだよ。\n観光の参考にしようと思って。アハハ…",
  ui_story_5029_50290013_116_dialog_content = "あら、そう？",
  ui_story_5029_50290013_117_dialog_content = "彼に言われて、昨日の夜なぜわたくしが書斎に入ったのか、\n調べにきたのかと思ったわ。",
  ui_story_5029_50290013_118_option_content = "そうだよ",
  ui_story_5029_50290013_119_dialog_content = "シーッ…PlayerName、これは秘密調査よ！",
  ui_story_5029_50290013_120_dialog_content = "隠すことはないわ、全部聞こえているもの。",
  ui_story_5029_50290013_121_dialog_content = "わたくしが昨日、なぜ領主の書斎に入ったのか\n調べているのでしょう？",
  ui_story_5029_50290013_122_dialog_content = "え！？",
  ui_story_5029_50290013_123_dialog_content = "昨日の夜、本当に領主さんの書斎に入ったの？",
  ui_story_5029_50290013_124_dialog_content = "ええ、何も隠すようなことではないわ。",
  ui_story_5029_50290013_125_dialog_content = "昨日、彼と別れた後、騎士の徽章（きしょう）が\n見当たらないことに気づいたの。",
  ui_story_5029_50290013_126_dialog_content = "あれは、わたくしにとって、\nとても大切なもの…",
  ui_story_5029_50290013_127_dialog_content = "でも、その時はまだ腹を立てていたから、\n頭を下げて探してもらえるよう頼む気にもなれなくて。",
  ui_story_5029_50290013_128_dialog_content = "だから、自分で探すしかなかったのよ。\n結局見つからなかったけれど…",
  ui_story_5029_50290013_129_dialog_content = "本当にそれだけ…？",
  ui_story_5029_50290013_130_dialog_content = "よくお聞きなさい。\nエルビスに頼まれているかどうかは問わないわ。",
  ui_story_5029_50290013_130X1_dialog_content = "わたくしが書斎に入ったことに\n気付いているのかどうかも聞かずにおきましょう…",
  ui_story_5029_50290013_131_dialog_content = "いずれにしても、わたくしは彼にも、彼の書斎にも、\nいっさい害する意図はないと伝えておいて。",
  ui_story_5029_50290013_132_dialog_content = "わたくしはただ、\n徽章を見つけたいだけよ。",
  ui_story_5029_50290014_1_dialog_content = "PlayerName、どこ行くの？",
  ui_story_5029_50290014_2_dialog_content = "メイドの休憩室はこっちだよ！",
  ui_story_5029_50290014_3_dialog_content = "分かった、今行くよ。",
  ui_story_5029_50290014_4_dialog_content = "一体誰ですか？大声を出しているのは！",
  ui_story_5029_50290014_5_dialog_content = "ここは休憩室ですよ、\n規則を知らないのですか！？",
  ui_story_5029_50290014_6_dialog_content = "このおばさん、誰？",
  ui_story_5029_50290014_7_dialog_content = "おばさん？？？",
  ui_story_5029_50290014_8_dialog_content = "まあ、なんて礼儀知らずの小娘でしょう！\n一体どこから入ってきたのです！？",
  ui_story_5029_50290014_9_dialog_content = "メイド長とお呼びなさい！",
  ui_story_5029_50290014_10_dialog_content = "ふん、えらそ～に！",
  ui_story_5029_50290014_11_dialog_content = "あなた…！",
  ui_story_5029_50290014_12_dialog_content = "すみませんメイド長さん、\nどうか怒らないであげてください。",
  ui_story_5029_50290014_13_option_content = "まだ子供なんです",
  ui_story_5029_50290014_14_dialog_content = "どうか真に受けないでください。",
  ui_story_5029_50290014_15_dialog_content = "ちょっと、どういうこと！？",
  ui_story_5029_50290014_16_option_content = "この子はいい子なんです",
  ui_story_5029_50290014_17_dialog_content = "ただ、時どき、失礼なことを言ってしまうだけなんです。\nどうか、許してあげてください。",
  ui_story_5029_50290014_18_dialog_content = "ふん…",
  ui_story_5029_50290014_19_dialog_content = "…それで、何かご用かしら？",
  ui_story_5029_50290014_20_dialog_content = "ゼインから、ここに行けば…",
  ui_story_5029_50290014_21_dialog_content = "ゼインさんのご紹介だったの？",
  ui_story_5029_50290014_22_dialog_content = "ゼインさんは領主様が\n最も信頼されている方の1人ですから…",
  ui_story_5029_50290014_23_dialog_content = "あのお方の推薦というなら、\n無下に断ることもできませんわね。",
  ui_story_5029_50290014_24_dialog_content = "紹介…？推薦？",
  ui_story_5029_50290014_25_dialog_content = "なんのこと…？",
  ui_story_5029_50290014_26_dialog_content = "それで、お名前は？",
  ui_story_5029_50290014_27_dialog_content = "PlayerNameです。僕たちは…",
  ui_story_5029_50290014_28_dialog_content = "お兄さんに聞いているのではありません。\nお嬢さんには口がついていないのですか？",
  ui_story_5029_50290014_29_dialog_content = "PlayerNameはあたしのお兄ちゃんじゃないよ。",
  ui_story_5029_50290014_29X1_dialog_content = "あたしにお兄ちゃんなんていないもん。\nパパとママと、それから師匠と先輩がいるだけ！",
  ui_story_5029_50290014_30_dialog_content = "そのようなことは聞いていません。",
  ui_story_5029_50290014_31_dialog_content = "で、何か特技は？",
  ui_story_5029_50290014_32_dialog_content = "い、いっぱいあるよ！",
  ui_story_5029_50290014_33_dialog_content = "あたしは珍獣マスターなの！\n珍獣の育成とか進化とか繁殖とかを手伝えるんだから！",
  ui_story_5029_50290014_34_dialog_content = "動物の飼育は、素晴らしい技術ですが…\nここは牧場ではありませんよ。",
  ui_story_5029_50290014_35_dialog_content = "まぁ、厨房（ちゅうぼう）ぐらいなら\n任せられるかもしれませんね。",
  ui_story_5029_50290014_36_dialog_content = "あたしが？料理でもするの？",
  ui_story_5029_50290014_37_dialog_content = "どうしました？何か不満でも？",
  ui_story_5029_50290014_38_dialog_content = "その様子からすると、\nメイドの経験はありませんね。",
  ui_story_5029_50290014_39_dialog_content = "領主様のお屋敷で働けるなど、\nあなたには十分ぜいたくな仕事始めですよ？",
  ui_story_5029_50290014_40_dialog_content = "メイド長さん、\n誤解されてるみたいですけど…",
  ui_story_5029_50290014_41_dialog_content = "め、メイド長！",
  ui_story_5029_50290014_42_dialog_content = "面接に来た方が、外でお待ちです！",
  ui_story_5029_50290014_43_dialog_content = "「外で」？\nでは、この2人は…？",
  ui_story_5029_50290014_44_dialog_content = "ナビゲーター様？",
  ui_story_5029_50290014_45_dialog_content = "どうしてここにいるの？",
  ui_story_5029_50290014_46_dialog_content = "それは…話すと長くなるのですが…\nナビゲーター様こそ、なぜハーバーシティに…？",
  ui_story_5029_50290014_47_dialog_content = "あたしとPlayerName、\nマナエっていうメイドを探しにきたの。知ってる？",
  ui_story_5029_50290014_48_dialog_content = "それは、その…",
  ui_story_5029_50290014_49_dialog_content = "ゼインに言われて、\nマナエを訪ねに来られたのですか？",
  ui_story_5029_50290014_50_dialog_content = "てっきりメイドの面接に来たとかん違いしておりました。\n申し訳ございません！",
  ui_story_5029_50290014_51_dialog_content = "マナエ。",
  ui_story_5029_50290014_52_dialog_content = "は、はい！",
  ui_story_5029_50290014_53_dialog_content = "こちらのお客様にきちんとおもてなしを。\n私は面接に向かいます。",
  ui_story_5029_50290014_54_dialog_content = "はい！",
  ui_story_5029_50290014_55_dialog_content = "あんたがマナエなの！？",
  ui_story_5029_50290014_56_dialog_content = "正直に話しなさい！\nあんた、なにか隠してるでしょ！？",
  ui_story_5029_50290014_57_dialog_content = "わ、わわわわ、私は…",
  ui_story_5029_50290014_58_dialog_content = "サナエ…マナエって、\n確か「お姉さん」の名前だったよね？",
  ui_story_5029_50290014_59_dialog_content = "え？名前からウソだったの？",
  ui_story_5029_50290014_60_dialog_content = "やっぱり、フィアの目に狂いはなかったよ！\nいくらなんでも怪しすぎ！",
  ui_story_5029_50290014_61_dialog_content = "フィア、僕の知る限り、\nサナエは君の思うような怪しい人じゃないよ。",
  ui_story_5029_50290014_62_dialog_content = "まずはちゃんと話を聞こう、ね？",
  ui_story_5029_50290014_63_dialog_content = "ナビゲーター様…あ、ありがとうございます…",
  ui_story_5029_50290014_64_dialog_content = "影ノ街でニナの側にいると思ってたよ。\nなんでここに？",
  ui_story_5029_50290014_65_dialog_content = "わ、私…アンデルセン家をクビになったので…",
  ui_story_5029_50290014_66_dialog_content = "それで商会にお願いして、\nここのメイドのお仕事を紹介してもらったんです…",
  ui_story_5029_50290014_67_dialog_content = "ニナが君のこと、クビにする…？",
  ui_story_5029_50290014_68_dialog_content = "ニナお嬢様は…そもそも私とは身分が違いますし…",
  ui_story_5029_50290014_69_dialog_content = "私はただのメイドに過ぎませんので…\nお嬢様が気にかけるような存在ではもともと…",
  ui_story_5029_50290014_70_dialog_content = "あ、新しい生活にも慣れてきましたし、その…",
  ui_story_5029_50290014_71_dialog_content = "だとしても、やっぱり怪しいよ。\nなんで名前まで変えてるの？",
  ui_story_5029_50290014_72_dialog_content = "そ、それは…クビにされたことを\n人に知られたくなかったので…",
  ui_story_5029_50290014_73_dialog_content = "ああああ、そ、そうでした！\n庭のお掃除がまだ残っていたんでした！",
  ui_story_5029_50290014_74_dialog_content = "じ、時間がありません！\n急がないと、またクビになっちゃいます！",
  ui_story_5029_50290014_75_dialog_content = "キャロ、この緑の髪の女の人、\n逃がさないで。",
  ui_story_5029_50290014_76_dialog_content = "ルルル！",
  ui_story_5029_50290014_77_dialog_content = "ああああ、マナエ姉さん…",
  ui_story_5029_50290014_78_dialog_content = "どこのノラ犬！？\nどきなさい！",
  ui_story_5029_50290014_79_dialog_content = "ル…",
  ui_story_5029_50290014_80_dialog_content = "サナエには仕事があるのよ！\nあんたたちの目はふし穴？",
  ui_story_5029_50290014_81_dialog_content = "サナエがクビになったら、責任とれるの！？",
  ui_story_5029_50290014_82_dialog_content = "サナエ、こんなヤツら放っといて、行くわよ！",
  ui_story_5029_50290014_83_dialog_content = "ル…",
  ui_story_5029_50290014_84_dialog_content = "キャロ、大丈夫だよ、こわくないよ。\nもう行っちゃったよ。",
  ui_story_5029_50290014_85_dialog_content = "ルルル！",
  ui_story_5029_50290014_86_dialog_content = "PlayerName、今のが\nあんたの信じてる友だちなワケ？",
  ui_story_5029_50290014_87_dialog_content = "今、どう見ても話をそらしてたじゃない！",
  ui_story_5029_50290014_88_dialog_content = "あの様子じゃ…確かに怪しいと言うしかないね。",
  ui_story_5029_50290014_89_dialog_content = "僕の知ってるサナエは、\nあんなふうに隠し事なんてしないし…",
  ui_story_5029_50290014_90_dialog_content = "お客様、あのメイドを調べていらっしゃるんですか？\n実は…私も怪しいと思っていたんですよ。",
  ui_story_5029_50290014_91_dialog_content = "おじさん、誰？",
  ui_story_5029_50290014_92_dialog_content = "ややっ、これは申し訳ない。",
  ui_story_5029_50290014_93_dialog_content = "申し遅れました。私はクックと申します。\n祖父の代から領主様の一族にお仕えする者です。",
  ui_story_5029_50290014_94_dialog_content = "昨年足を痛めてしまいましてな。\n今はメイド長の雑用の手伝いをしております。\nそれで、メイドたちとも交流があるのですよ。",
  ui_story_5029_50290014_95_dialog_content = "私が思うに、あのマナエというメイド…\n何かあるでしょうな。",
  ui_story_5029_50290014_96_dialog_content = "どうしてそう思うんですか？",
  ui_story_5029_50290014_97_dialog_content = "影ノ街商会の紹介だというので、\n領主様も断るわけにはいかず、雇ったのですが…",
  ui_story_5029_50290014_98_dialog_content = "あのメイドときたら、面倒ばかり起こしましてね。\n皿を割るわ、グラスを割るわで…\n給料がもう数か月分も差し押さえられてるんですよ。",
  ui_story_5029_50290014_99_dialog_content = "それにもかかわらず、\n本人はまったく気にかける様子もないし、\n機をうかがっては領主様のお側に近づこうとするので…",
  ui_story_5029_50290014_100_dialog_content = "何か目的があるとしか思えませんな。",
  ui_story_5029_50290014_101_dialog_content = "きのうの晩などは、あのメイドがこっそり\n領主様の書斎に入っていくのを見かけたのです。",
  ui_story_5029_50290014_102_dialog_content = "昨日の夜！？",
  ui_story_5029_50290014_103_dialog_content = "書斎の掃除はお昼に終わってたんでしょ？",
  ui_story_5029_50290014_104_dialog_content = "私もおかしいと思いましてね…ただ、商会が後ろ盾とあっては、\nおおっぴらに調べるわけにもいきませんのでね。",
  ui_story_5029_50290014_105_dialog_content = "ただ、あのメイドが領主様に\n不利になるようなことをしないかと、心配でならないのです。",
  ui_story_5029_50290014_106_dialog_content = "ですから、この件…どうか、お2人にお願いします。",
  ui_story_5029_50290014_107_dialog_content = "PlayerName、これであんたも、\nお友だちを見逃してとは言わないよね？",
  ui_story_5029_50290014_108_dialog_content = "まずは本人に話を聞こう…",
  ui_story_5029_50290014_109_dialog_content = "え？…領主様に言われて、\n私を調べてるのですか？",
  ui_story_5029_50290014_110_option_content = "いいや",
  ui_story_5029_50290014_111_dialog_content = "領主様はこのことを知らないよ。",
  ui_story_5029_50290014_112_dialog_content = "僕たちはただ、話を聞いて…",
  ui_story_5029_50290014_113_option_content = "そうだよ",
  ui_story_5029_50290014_114_dialog_content = "（マズい、秘密調査だってこと忘れてた！）",
  ui_story_5029_50290014_115_dialog_content = "コホン、ええと…\nとにかく、聞いた話では…",
  ui_story_5029_50290014_116_dialog_content = "昨日の夜、君は許可なく領主の書斎に入ったね？",
  ui_story_5029_50290014_117_dialog_content = "クックさんから聞いたんですか！？",
  ui_story_5029_50290014_118_dialog_content = "ほ、他の人には言わないって、\n約束してくれたのに…",
  ui_story_5029_50290014_119_dialog_content = "ふ～ん、口止めまでしようとしてたんだ？",
  ui_story_5029_50290014_120_dialog_content = "ち、違います…そんなことは！",
  ui_story_5029_50290014_121_dialog_content = "じゃあ、昨日の夜…君はどうして、\nこっそり書斎に入ったの？",
  ui_story_5029_50290014_122_dialog_content = "ひ、昼間、掃除している時に…\nホールのテーブルに置いてあった花瓶をうっかり割ってしまったんです。",
  ui_story_5029_50290014_123_dialog_content = "でも、その時にお客様が到着されて、\n急いで下がるよう、ゼインさんに急かされて…",
  ui_story_5029_50290014_124_dialog_content = "花瓶を割ってしまったことが分かれば、\nまたクビになるって心配になって、私…",
  ui_story_5029_50290014_125_dialog_content = "夜に人がいなくなってから戻って拾おうと思って…\n花瓶の破片をソファーの下に隠したんです。",
  ui_story_5029_50290014_126_dialog_content = "フッフッフ…その破片、\nこのフィアが見つけちゃったもんね！",
  ui_story_5029_50290014_127_dialog_content = "私のお掃除、やっぱり行き届いてなかったんですね。\nうううう…",
  ui_story_5029_50290014_128_dialog_content = "でも、ホールのテーブルと花瓶、\nちゃんと数は合ってたよ。",
  ui_story_5029_50290014_129_dialog_content = "ええと、それは…\nまったく同じものを買って来たので…",
  ui_story_5029_50290014_130_dialog_content = "でも、お給料はほとんど弁償で消えてるって聞いたよ。\nそんな高級な花瓶を買うお金、どこにあったの？",
  ui_story_5029_50290014_131_dialog_content = "…うぅ…あああああ…！",
  ui_story_5029_50290014_132_dialog_content = "そのお金はどこから？",
  ui_story_5029_50290014_133_dialog_content = "に、ニナお嬢様が…",
  ui_story_5029_50290014_134_dialog_content = "ナビゲーター様…自分にはこんなこと\n向いていないって分かっていたんです…",
  ui_story_5029_50290014_135_dialog_content = "でも、ニナお嬢様に頼まれたからには、\nお嬢様に悲しい思いをさせるわけにはいきません…",
  ui_story_5029_50290014_136_dialog_content = "つまり、ニナのところをクビにはなってないんだね？",
  ui_story_5029_50290014_137_dialog_content = "ううう…はい。",
  ui_story_5029_50290014_138_dialog_content = "ニナが君をここに送り込んだのは、\n盗みを働かせるため？",
  ui_story_5029_50290014_139_dialog_content = "盗みを…？な、なんの話ですか…？",
  ui_story_5029_50290014_140_dialog_content = "私はただ、ニナお嬢様に代わって、\n領主様のお人柄と好みを調べに来ただけです…",
  ui_story_5029_50290014_141_dialog_content = "相手のことを知っておけば、貿易の商談なども、\nやりやすくなるから、と…",
  ui_story_5029_50290014_142_dialog_content = "こんなのすぐにバレちゃうって思ってましたが…\nやっぱり、ナビゲーター様に見つかってしまいました…",
  ui_story_5029_50290014_143_dialog_content = "ニナお嬢様になんとお伝えすればいいか…うううう。",
  ui_story_5029_50290015_1_dialog_content = "今日は皆なんだか、近づきがたいなぁ…",
  ui_story_5029_50290015_2_dialog_content = "もう皆にまかせた方がいいかな…？",
  ui_story_5029_50290015_3_dialog_content = "いや、ダメだ。僕にだってちゃんと頭と足が付いてるんだ。\n一人で調査すればいい。",
  ui_story_5029_50290015_4_dialog_content = "僕が一番に真犯人を見つけられたら、\n皆、競い合わなくてすむかもしれないしね。",
  ui_story_5029_50290015_5_dialog_content = "よし、今すぐ行動だ！",
  ui_story_5029_50290015_6_dialog_content = "この部屋は、もう調べ終わった…",
  ui_story_5029_50290015_7_dialog_content = "部屋の外に何か手がかりはあるかな？",
  ui_story_5029_50290015_8_dialog_content = "それにしても、このお屋敷、いい所にあるなぁ。",
  ui_story_5029_50290015_9_dialog_content = "海も見えるし、別の方向には森もある。",
  ui_story_5029_50290015_10_dialog_content = "ゼイン、この森もお屋敷の庭のうちだって言ってたけど…",
  ui_story_5029_50290015_11_dialog_content = "<color=#828282>カサカサ…</color>",
  ui_story_5029_50290015_12_dialog_content = "あれ？",
  ui_story_5029_50290015_13_dialog_content = "今、誰か通ったような…",
  ui_story_5029_50290015_14_dialog_content = "誰かいる！錯覚じゃない！",
  ui_story_5029_50290015_15_dialog_content = "ちょっと、ここで何してるの？",
  ui_story_5029_50290015_16_dialog_content = "…な、なんで黙ってるの？",
  ui_story_5029_50290015_17_dialog_content = "何をする気！？",
  ui_story_5029_50290015_18_dialog_content = "ちゃんと話をしようよ。\nそんなもの持って、危ないよ…",
  ui_story_5029_50290015_19_dialog_content = "<color=#828282>ドンッ！</color>",
  ui_story_5029_50290015_20_dialog_content = "うっ…",
  ui_story_5029_50290015_21_dialog_content = "君は、いったい…",
  ui_story_5029_50290015_22_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5029_50290015_23_dialog_content = "おかえりなさいませ。",
  ui_story_5029_50290015_24_dialog_content = "占いが中断してしまったようです。\n申し訳ございません…",
  ui_story_5029_50290015_25_dialog_content = "選択の過ちが、こうした結末を招くのです。",
  ui_story_5029_50290015_26_dialog_content = "ですが、そうですね…\n少し視点を変えてみてはいかがでしょう？",
  ui_story_5029_50290015_27_dialog_content = "たった今見たものは…\n単なる、あまり良くない夢だったとお考え下さい。",
  ui_story_5029_50290015_28_dialog_content = "現実世界のあなたには、\nまったく関わりのないことなのです。",
  ui_story_5029_50290015_29_dialog_content = "どうしました？\nまだ残念そうな顔をしていらっしゃいますね。",
  ui_story_5029_50290015_30_dialog_content = "幸いなことに…まだ時間はあります。",
  ui_story_5029_50290015_31_dialog_content = "もう一度夢を見ればよいのです。",
  ui_story_5029_50290015_32_dialog_content = "それこそ夢のいい所です。\nそうは思われませんか？",
  ui_story_5029_50290016_1_dialog_content = "あのジョムが本当に心を入れ替えて、\nまともな商売を始めるなんて…？",
  ui_story_5029_50290016_2_dialog_content = "でも、ホテル代も払えないなんて意外だったよ。",
  ui_story_5029_50290016_3_dialog_content = "高級なホテルには泊まれないというだけでしょう？\n宿なしにはならないはずよ。",
  ui_story_5029_50290016_4_dialog_content = "だったら、なんでわざわざ\nタダで泊まれるところを紹介してあげたの？",
  ui_story_5029_50290016_5_dialog_content = "紹介したのは領主の私有地よ。\n私兵が見張っているわ。",
  ui_story_5029_50290016_6_dialog_content = "ジョムに何か動きがあれば、\nすぐに知ることができるでしょう。",
  ui_story_5029_50290016_7_dialog_content = "やっぱり、ジョムの言ったことを\n完全には信じてなかったんだね？",
  ui_story_5029_50290016_8_dialog_content = "とはいえ、あの様子だと、\nジョムは本当に銀の箱のことを知らなさそうだ。",
  ui_story_5029_50290016_9_dialog_content = "私もそう思うわ。\nハーバーシティに留まる気があるということは、\n逃げる気はないということ。",
  ui_story_5029_50290016_10_dialog_content = "宿を紹介したのは、\nあくまでも万が一に備えただけのことよ。",
  ui_story_5029_50290016_11_dialog_content = "あとは、領主に合わせると約束もしたから。",
  ui_story_5029_50290016_12_dialog_content = "ジョムから疑われないように、\nとりあえず口約束しただけかと思ってたよ。",
  ui_story_5029_50290016_13_dialog_content = "それも間違っていないわ。\nでも、口にしたからには、約束を果たしたいの。",
  ui_story_5029_50290016_14_dialog_content = "そうでなければ、騎士としての名誉に傷がつくわ。\n私を尊重し、信頼してくれる人たちに申し訳が立たない。",
  ui_story_5029_50290016_15_dialog_content = "（じゃあ、さっきホテルで言った婚約の話も…？）",
  ui_story_5029_50290016_16_dialog_content = "ひゃあ！全部聞いちゃった！",
  ui_story_5029_50290016_17_dialog_content = "え…？僕の考えてること、口に出てた…！？",
  ui_story_5029_50290016_18_dialog_content = "ジョムはもう疑わないのね？",
  ui_story_5029_50290016_19_dialog_content = "（なんだ、そっちのことか…）",
  ui_story_5029_50290016_20_dialog_content = "バイス、フィア！いつの間に…",
  ui_story_5029_50290016_21_dialog_content = "なんて言ってる場合じゃないわ！\n急いで調査を進めないと！",
  ui_story_5029_50290016_22_dialog_content = "ってことは～…フィアが追ってる人が、\n真犯人かもってことだね？",
  ui_story_5029_50290016_23_dialog_content = "キャロ、行くよ！",
  ui_story_5029_50290016_24_dialog_content = "ルルル！",
  ui_story_5029_50290016_25_dialog_content = "2人とも、話はまだ…",
  ui_story_5029_50290016_26_dialog_content = "ふぅ、ふぅ…2人とも、どこ行っちゃったんだろ？",
  ui_story_5029_50290016_27_dialog_content = "PlayerName、追いかけなくていいわ。",
  ui_story_5029_50290016_28_dialog_content = "部屋に戻ってもう一度、\nほかに手がかりはないか調べましょう。",
  ui_story_5029_50290016_29_dialog_content = "そうだね…",
  ui_story_5029_50290016_30_dialog_content = "はあ、いっそ犯人が僕の目の前に飛び込んで来たりしないかな。",
  ui_story_5029_50290016_31_dialog_content = "<color=#828282>ドンッ！</color>",
  ui_story_5029_50290016_32_dialog_content = "おい、どこ見てやがんだ！？",
  ui_story_5029_50290016_33_dialog_content = "…",
  ui_story_5029_50290016_34_dialog_content = "おい、どこに行く気だ！？\nぶつかっておいて詫びの一つも言えねえのか！？",
  ui_story_5029_50290016_35_dialog_content = "…チッ、ツイてねえな！",
  ui_story_5029_50290016_36_dialog_content = "あのローブを着た人、変だね。\nこんな暑い日にきっちり着込んでる。",
  ui_story_5029_50290016_37_dialog_content = "顔を隠して、あわただしく先を急ぐ…\nおおかた、何かやましいことがあるのでしょう。",
  ui_story_5029_50290016_38_dialog_content = "「やましいこと」…？",
  ui_story_5029_50290016_39_dialog_content = "そういえば、ローブの下に何か大きなモノを抱えてるのが\nちらっと見えたけど…",
  ui_story_5029_50290016_40_dialog_content = "…",
  ui_story_5029_50290016_41_dialog_content = "銀の箱！？",
  ui_story_5029_50290016_42_dialog_content = "そこのあなた、待ちなさい！",
  ui_story_5029_50290016_43_dialog_content = "マズい、迷わず逃げ出した！！",
  ui_story_5029_50290016_44_dialog_content = "やはり怪しいわ、追うわよ！",
  ui_story_5029_50290017_1_dialog_content = "僕たちが聞かなかったら、バッジを失くしたこと、\nいつまでも一人で抱え込んでたかもね。",
  ui_story_5029_50290017_2_dialog_content = "バーバリーさんの言ってることと、\n領主様の言ってることはほぼ一致してるわ。ただ…",
  ui_story_5029_50290017_3_dialog_content = "エルビスさんの話だと、\nバーバリーさんの領地の発展を支援するって\n申し出ただけのこと…",
  ui_story_5029_50290017_4_dialog_content = "それを皮肉だと誤解したのかな。\nだから、あんなに怒ってたんだ。",
  ui_story_5029_50290017_5_dialog_content = "時どき、白夜城の貴族と私って\n全く違う生き物なんじゃないかって、本気で思っちゃうわ…",
  ui_story_5029_50290017_6_dialog_content = "はっきり説明して、握手すれば済むことを、\nどうしてわざわざ複雑にするのかしら。",
  ui_story_5029_50290017_7_dialog_content = "その割には、僕も分からないことがあるけど…\n僕たち、バーバリーのバッジの場所、知ってるよね？",
  ui_story_5029_50290017_8_dialog_content = "なんで教えちゃいけないの？",
  ui_story_5029_50290017_9_dialog_content = "考えてもみてよ。\nバッジがお屋敷のカフェにあると知ったら…",
  ui_story_5029_50290017_10_dialog_content = "バーバリーさん、バッジを見つけたら、\nさっさと立ち去ってしまうんじゃない？",
  ui_story_5029_50290017_11_dialog_content = "うん、その可能性はあるね。",
  ui_story_5029_50290017_12_dialog_content = "そうなったら、きっとバーバリーさんは今後一切、\nエルビスさんと関わろうとしないわ。",
  ui_story_5029_50290017_13_dialog_content = "つまり…バーバリーのバッジがカフェにあるって、\nエルビスさんに気付かせて…",
  ui_story_5029_50290017_14_dialog_content = "向こうから返すように仕向けるってこと？",
  ui_story_5029_50290017_15_dialog_content = "そうすれば、和解のきっかけになるかもしれないでしょ？",
  ui_story_5029_50290017_16_dialog_content = "バイス、本当に皆のことを考えてるんだね…",
  ui_story_5029_50290017_17_dialog_content = "はあ、おせっかいだって分かってるんだけどね…",
  ui_story_5029_50290017_18_dialog_content = "バーバリーさんもエルビスさんも、\n貴族的な物言いが引っかかることはあるけど、\nいい人たちには違いないわ。",
  ui_story_5029_50290017_19_dialog_content = "お互い誤解してるって分かってるのに、\n見て見ぬふりはできないでしょ。",
  ui_story_5029_50290017_20_dialog_content = "『ロミーとジュリー』みたいな悲劇が\n身近で起こるなんてごめんだわ！",
  ui_story_5029_50290017_21_dialog_content = "じゃあ、もうバーバリーを疑ってないんだね？",
  ui_story_5029_50290017_22_dialog_content = "ええ！",
  ui_story_5029_50290017_23_dialog_content = "でも…犯人さがしは振り出しに戻ったわね。",
  ui_story_5029_50290017_24_dialog_content = "ひゃあ！\nいいこと聞いちゃった！",
  ui_story_5029_50290017_25_dialog_content = "バーバリーの疑いは晴れたのね？",
  ui_story_5029_50290017_26_dialog_content = "カレン、フィア？\nあなたたち、いつの間に…",
  ui_story_5029_50290017_27_dialog_content = "邪魔したわね。\n私は調査に戻ることにするわ。",
  ui_story_5029_50290017_28_dialog_content = "それなら、フィアが追ってる人が、\n真犯人かもってことだね？",
  ui_story_5029_50290017_29_dialog_content = "キャロ、行くよ！",
  ui_story_5029_50290017_30_dialog_content = "君たちの方は、何か進展あった…？\n…って、ちょっと！行かないで！",
  ui_story_5029_50290017_31_dialog_content = "ふぅ、ふぅ…2人とも、どこ行っちゃったんだろ？",
  ui_story_5029_50290017_32_dialog_content = "PlayerName、とりあえずは放っておきましょ。",
  ui_story_5029_50290017_33_dialog_content = "私たちは戻って、他の疑わしいことを調べましょう。",
  ui_story_5029_50290017_34_dialog_content = "僕もそう思ってるけど…",
  ui_story_5029_50290017_35_dialog_content = "どうやって戻るか知ってる？",
  ui_story_5029_50290017_36_dialog_content = "えっ？",
  ui_story_5029_50290017_37_dialog_content = "フィアとカレンを追うのに夢中で、\n道を見てなかったんだ。",
  ui_story_5029_50290017_38_dialog_content = "気付いた時には、このヘンな小道に…",
  ui_story_5029_50290017_39_dialog_content = "大丈夫よ、あそこに人がいるわ。\n道を聞けばいいだけのことよ。",
  ui_story_5029_50290017_40_dialog_content = "すみません、ちょっといいですか…？",
  ui_story_5029_50290017_41_dialog_content = "…",
  ui_story_5029_50290017_42_dialog_content = "待ってください、怪しい者じゃありません！\n領主のお屋敷に行く道を聞きたいだけなんです！",
  ui_story_5029_50290017_43_dialog_content = "…！",
  ui_story_5029_50290017_44_dialog_content = "ヘンな人ね…\nなんで話も聞こうとせずに逃げちゃったのかしら。",
  ui_story_5029_50290017_45_dialog_content = "それに、こんなに暑い日にローブなんか着て、\n顔まで隠してたら…暑くないの？",
  ui_story_5029_50290017_46_dialog_content = "僕の見間違いじゃなければ…",
  ui_story_5029_50290017_47_dialog_content = "今の人、ローブの下に何か銀色に光るものを抱えてたね。",
  ui_story_5029_50290017_48_dialog_content = "…",
  ui_story_5029_50290017_49_dialog_content = "銀の箱！？",
  ui_story_5029_50290017_50_dialog_content = "行きましょ、急いで追いかけるのよ！",
  ui_story_5029_50290018_1_dialog_content = "PlayerName、ほんとに話さないつもり？",
  ui_story_5029_50290018_2_dialog_content = "何日かしたら自分から辞めるって、\nサナエが約束してくれたでしょ。",
  ui_story_5029_50290018_3_dialog_content = "ニナが自分で交渉の場で\nエルビスさんに謝ればいいことだよ。",
  ui_story_5029_50290018_4_dialog_content = "ニナにとってはきっと\nすごく大事な交渉の相手なんだろうね。",
  ui_story_5029_50290018_5_dialog_content = "何とか好みを調べて、\nあらかじめ合わせようとしてたんだよ。",
  ui_story_5029_50290018_6_dialog_content = "ニナって…アンデルセン家のお嬢様？\n影ノ街にもうたくさん店を持ってるのに、まだ店を増やす気？",
  ui_story_5029_50290018_7_dialog_content = "フィアだって、そうでしょ？",
  ui_story_5029_50290018_8_dialog_content = "もう一人前の珍獣マスターなのに、\n努力を続けてる。",
  ui_story_5029_50290018_9_dialog_content = "ふん、トーゼンでしょ！",
  ui_story_5029_50290018_10_dialog_content = "フィアは師匠よりもすごい珍獣の専門家になって、\n誰よりすごい珍獣の本を書くんだから！",
  ui_story_5029_50290018_11_dialog_content = "…でも確かに…そう言われると、分かる気がしてきたよ。",
  ui_story_5029_50290018_12_dialog_content = "ところで、ほんとにあのサナエって人は\nまったく疑わなくていいの？",
  ui_story_5029_50290018_13_dialog_content = "やっぱり魔が差して盗んだとか…",
  ui_story_5029_50290018_14_dialog_content = "僕の知る限り、サナエはそんなこと考えないし…\n度胸もないんじゃないかな。",
  ui_story_5029_50290018_15_dialog_content = "でも、重要な手がかりは手に入れたでしょ？",
  ui_story_5029_50290018_16_dialog_content = "まぁ、あの人の言ってることが\nほんとに信用できるならだけどね…",
  ui_story_5029_50290018_17_dialog_content = "書斎に入った時には、\n部屋のドアの鍵がもう開いてたんだよね。",
  ui_story_5029_50290018_18_dialog_content = "影ノ街から紹介されてきたメイドって、\nあのニナさんのお世話をしてる人のことだったのね？",
  ui_story_5029_50290018_19_dialog_content = "ということは、サナエの疑いは晴れたのね？",
  ui_story_5029_50290018_20_dialog_content = "うひゃあ！？",
  ui_story_5029_50290018_21_dialog_content = "あたしたちが見つけた大事な手がかりなのに、\n盗み聞きするなんて！",
  ui_story_5029_50290018_22_dialog_content = "ごめんなさい。戻って新しい手がかりを探していたら、\n偶然、あなたたちの話が聞こえてきたの。",
  ui_story_5029_50290018_23_dialog_content = "秘密の話だというなら、\n私はこれ以上邪魔立てしないことにするわ。",
  ui_story_5029_50290018_24_dialog_content = "先を越されちゃいそう…\n急いで調査を進めないと！",
  ui_story_5029_50290018_25_dialog_content = "君たちの方は、何か進展あった…？",
  ui_story_5029_50290018_26_dialog_content = "…って、ちょっと！行かないで！",
  ui_story_5029_50290018_27_dialog_content = "うかうかしてたら、\nフィアの懸賞金がとられちゃう！",
  ui_story_5029_50290018_28_dialog_content = "キャロ、急いで追いつくよ！",
  ui_story_5029_50290018_29_dialog_content = "ルルル…",
  ui_story_5029_50290018_30_dialog_content = "あれ？キャロ？\n窓辺で何見てるの？早く来なさい！",
  ui_story_5029_50290018_31_dialog_content = "外なんてどうせ、木しかないよ…",
  ui_story_5029_50290018_32_dialog_content = "うーん、静かな庭園だなぁ。",
  ui_story_5029_50290018_33_dialog_content = "あれ？森の中に…誰かいる？",
  ui_story_5029_50290018_34_dialog_content = "PlayerName、見て見て、\n外のあの人、怪しいよ！",
  ui_story_5029_50290018_35_dialog_content = "こんな暑い日に、すごく着込んでる…",
  ui_story_5029_50290018_36_dialog_content = "あたしの目がよくなかったら、\n暗鬼か、見たことのない珍獣かと思うとこだったよ。",
  ui_story_5029_50290018_37_dialog_content = "あの人、何してるんだろう？",
  ui_story_5029_50290018_38_dialog_content = "なにかフトコロに隠したみたいだね？",
  ui_story_5029_50290018_39_dialog_content = "おっきくて、銀色の…",
  ui_story_5029_50290018_40_dialog_content = "…",
  ui_story_5029_50290018_41_dialog_content = "銀の箱！？",
  ui_story_5029_50290018_42_dialog_content = "まさか、真犯人が庭にいたってこと！？",
  ui_story_5029_50290018_43_dialog_content = "…",
  ui_story_5029_50290018_44_dialog_content = "マズい、気づかれた！",
  ui_story_5029_50290018_45_dialog_content = "キャロ、急いで追うよ！",
  ui_story_5029_50290018_46_dialog_content = "ルルル！",
  ui_story_5029_50290019_1_dialog_content = "止まりなさい！",
  ui_story_5029_50290019_2_dialog_content = "…",
  ui_story_5029_50290019_3_dialog_content = "よく聞きなさい。\n今ならまだ、自訴を許すわ。",
  ui_story_5029_50290019_4_dialog_content = "私に捕まれば、\n全く違う話になるわよ。",
  ui_story_5029_50290019_5_dialog_content = "ふぅ…ふぅ…",
  ui_story_5029_50290019_6_dialog_content = "僕たちの忠告をまったく聞かずに、\nものすごいスピードで山の上に逃げていったね。",
  ui_story_5029_50290019_7_dialog_content = "どうあろうと、民にランスを\n向けたくはなかったのだけれど…",
  ui_story_5029_50290019_8_dialog_content = "忠告にも耳を貸さない悪党ならば、\n私も容赦はしない！",
  ui_story_5029_50290019_9_dialog_content = "カレン、僕たち、武器は持ってきてないよ…？",
  ui_story_5029_50290019_10_dialog_content = "シッ…これは作戦よ。",
  ui_story_5029_50290019_11_dialog_content = "（ホテルではあれだけウソが下手だったのに…）",
  ui_story_5029_50290019_12_dialog_content = "（戦いになると「ウソ」も使いこなせるんだ？）",
  ui_story_5029_50290019_13_dialog_content = "（あれ？何かカレンに向かって飛んでくる？）",
  ui_story_5029_50290019_14_dialog_content = "カレン！危ない――！",
  ui_story_5029_50290019_15_dialog_content = "<color=#828282>ドンッ！</color>",
  ui_story_5029_50290019_16_dialog_content = "PlayerName、私の声が聞こえる？",
  ui_story_5029_50290019_17_dialog_content = "うん…",
  ui_story_5029_50290019_18_dialog_content = "か、カレンは大丈夫？",
  ui_story_5029_50290019_19_dialog_content = "PlayerName、バカね…",
  ui_story_5029_50290019_20_dialog_content = "あなたがかばってくれたのよ。\n私を心配するなんて…",
  ui_story_5029_50290019_21_dialog_content = "だって、君に何か…\nせっかくの新しいドレスに何かあったら、大変じゃない。",
  ui_story_5029_50290019_22_dialog_content = "こんな時にドレスの心配？",
  ui_story_5029_50290019_23_dialog_content = "どこを痛めたの、見せて。",
  ui_story_5029_50290019_24_dialog_content = "僕は大丈夫だよ、一休みすれば平気。",
  ui_story_5029_50290019_25_dialog_content = "気を失っていたのよ。\n平気なわけないでしょう？",
  ui_story_5029_50290019_26_dialog_content = "そうやって傷を隠されるほど、\n私は辛くなるわ…",
  ui_story_5029_50290019_27_dialog_content = "仲間が自分のせいでけがをするなんて、耐えられない…\nそんなことが、起こってはならないの！",
  ui_story_5029_50290019_28_dialog_content = "カレン…今まで僕は、\nずっとみんなに助けられてきたんだよ。",
  ui_story_5029_50290019_29_dialog_content = "それで、ようやく自分が\n誰かのナイトになれるチャンスがあって、\n正真正銘のお姫様を助けられたんだ。",
  ui_story_5029_50290019_30_dialog_content = "これって光栄なことじゃない？",
  ui_story_5029_50290019_31_dialog_content = "…そこまで余裕なら、本当に何ともなさそうね。",
  ui_story_5029_50290019_32_dialog_content = "これを見て。",
  ui_story_5029_50290019_33_dialog_content = "銀の箱？まさか、探していた…？",
  ui_story_5029_50290019_34_dialog_content = "きっと、捕まるのが怖くて、\n銀の箱を僕たちに投げつけて逃げたんだ。",
  ui_story_5029_50290019_35_dialog_content = "そう遠くへは行ってないはずだよ。\nこのまま追いかければ…イタタ！",
  ui_story_5029_50290019_36_dialog_content = "その状態でどうやって追うつもり？",
  ui_story_5029_50290019_37_dialog_content = "今は冗談が言えるとしても、\nもし内臓でも傷つけていたら、\nとんでもないことになるわ。",
  ui_story_5029_50290019_38_dialog_content = "世界でたった１人の空の末裔に、\n私のせいで何かあったら困るもの。",
  ui_story_5029_50290019_39_dialog_content = "そんなことになったら、\n私の名前が歴史書に大罪人として残されるわ。",
  ui_story_5029_50290019_40_dialog_content = "とにかく、このままではだめよ…\n急いで山を下りて、お医者様に見せましょう。",
  ui_story_5029_50290019_41_dialog_content = "僕は…",
  ui_story_5029_50290019_42_option_content = "山を下りる",
  ui_story_5029_50290019_43_dialog_content = "エルビスさんは銀の箱が見つかればいいって言ってたね。",
  ui_story_5029_50290019_44_dialog_content = "誰が犯人かは分からないけど、気の迷いで盗んだだけで、\n今後こんなことはしないことを願うよ…",
  ui_story_5029_50290019_45_dialog_content = "1度よこしまな心を生じた者は、\n2度目、3度目の誘惑にかられるものよ。",
  ui_story_5029_50290019_46_dialog_content = "だったら、どうして戻りたがるの？",
  ui_story_5029_50290019_47_dialog_content = "勝利への道を仲間の命で作りたくはないの。",
  ui_story_5029_50290019_48_dialog_content = "あなたに何かあってもらっては困る。\nただそれだけのことよ。",
  ui_story_5029_50290019_49_dialog_content = "本当にそれだけ…？",
  ui_story_5029_50290019_50_dialog_content = "何か言った？",
  ui_story_5029_50290019_51_dialog_content = "な、何でもないよ！",
  ui_story_5029_50290019_52_dialog_content = "カレン殿下、PlayerNameさん、\n感謝いたします。",
  ui_story_5029_50290019_53_dialog_content = "こんなに早く見つけてくださるとは。",
  ui_story_5029_50290019_54_dialog_content = "さすがは、直々に白夜上の見回りまでされているという、\n我らが白夜城の姫君。",
  ui_story_5029_50290019_55_dialog_content = "あなたが治める白夜城は\nさらに穏やかで華やかに発展していくことでしょう。",
  ui_story_5029_50290019_56_dialog_content = "礼など結構よ、\n大したことはしていないわ。",
  ui_story_5029_50290019_57_dialog_content = "エルビスさん、人が良さそうな割に、\nずいぶんお世辞が上手ね…",
  ui_story_5029_50290019_58_dialog_content = "それに、PlayerNameはケガしてるし…",
  ui_story_5029_50290019_59_dialog_content = "お医者さんが何でもないって言ってたよ。\n心配しないで。",
  ui_story_5029_50290019_60_dialog_content = "えっ？あれが無くしたっていう銀の箱？",
  ui_story_5029_50290019_61_dialog_content = "思ったよりフツーだね。",
  ui_story_5029_50290019_62_dialog_content = "街で犯人にばったり会うなんてラッキーね。\n私もそれぐらい運が良ければ…",
  ui_story_5029_50290019_63_dialog_content = "バイスさんとフィアさんも\nありがとうございました。",
  ui_story_5029_50290019_64_dialog_content = "ささやかながら、皆さんにお礼をご用意させていただきました。\nハーバーシティならではの晩さん会も準備しております。",
  ui_story_5029_50290019_65_dialog_content = "こちらへどうぞ。",
  ui_story_5029_50290019_66_option_content = "追いかける",
  ui_story_5029_50290019_67_dialog_content = "銀の箱が見つかればいいって言われてるけど…",
  ui_story_5029_50290019_68_dialog_content = "やっぱり僕は、犯人を捕まえたい。",
  ui_story_5029_50290019_69_dialog_content = "カレンが誰より白夜城や領地の人たちを愛してること、\n僕はよく分かってるよ。",
  ui_story_5029_50290019_70_dialog_content = "君だって犯人がまた悪事を働くなんて、\n望んでないでしょ？",
  ui_story_5029_50290019_71_dialog_content = "でも…",
  ui_story_5029_50290019_72_dialog_content = "僕は空の末裔だよ。\n暗鬼との戦いだって乗り越えてきたんだ。\nこれしきのこと、なんてことないよ。",
  ui_story_5029_50290019_73_dialog_content = "安心して、僕はそこまでひ弱じゃない。",
  ui_story_5029_50290019_74_dialog_content = "PlayerName…分かったわ。",
  ui_story_5029_50290019_75_dialog_content = "犯人の逃げた方向を感知できる？",
  ui_story_5029_50290019_76_dialog_content = "うん！",
  ui_story_5029_50290020_1_dialog_content = "ふぅ、はぁ…ここ、もうハーバーシティの郊外だよね。",
  ui_story_5029_50290020_2_dialog_content = "こんなに走って、犯人は疲れないのかな？",
  ui_story_5029_50290020_3_dialog_content = "前よ、背中が見えたわ！",
  ui_story_5029_50290020_4_dialog_content = "でも…だいぶ離されてるね。",
  ui_story_5029_50290020_5_dialog_content = "こんなことなら、弓を持ってくるんだったわ！",
  ui_story_5029_50290020_6_dialog_content = "僕も調査の途中でばったり犯人に会うなんて、\n思ってなかったよ…",
  ui_story_5029_50290020_7_dialog_content = "ふぅ、ふぅ…それにしても、すごい体力だ。\n僕たちじゃ追いつけそうにない…",
  ui_story_5029_50290020_8_dialog_content = "…",
  ui_story_5029_50290020_9_dialog_content = "バイス？なんで止まったの？",
  ui_story_5029_50290020_10_dialog_content = "こうなったら、試してみるしかないわ。",
  ui_story_5029_50290020_11_dialog_content = "なんで石を拾って僕の方を見てるの…？",
  ui_story_5029_50290020_12_dialog_content = "お、脅されたって、僕はこれ以上速く走れないよ…",
  ui_story_5029_50290020_13_dialog_content = "確か、あなたのヘアバンド、けっこう弾性があったわよね。\nちょっと貸してくれない？",
  ui_story_5029_50290020_14_dialog_content = "まさか、ヘアバンドを弓代わりにするの？",
  ui_story_5029_50290020_15_dialog_content = "そんなはずないでしょ…\nヘアバンドで石をくるんで、投げるのよ。",
  ui_story_5029_50290020_16_dialog_content = "そういうことか…\nはい、使って！",
  ui_story_5029_50290020_17_dialog_content = "ありがとう、これで決めるわ。",
  ui_story_5029_50290020_18_dialog_content = "外さない！",
  ui_story_5029_50290020_19_dialog_content = "命中した…倒れたよ！",
  ui_story_5029_50290020_20_dialog_content = "授業で習った技が\n本当に役に立つなんて…",
  ui_story_5029_50290020_21_dialog_content = "すごいよバイス！",
  ui_story_5029_50290020_22_dialog_content = "大した威力じゃないわ。\n今のうちに早く追いつきましょ！",
  ui_story_5029_50290020_23_dialog_content = "うん！",
  ui_story_5029_50290020_24_dialog_content = "急いで、もうすぐよ！",
  ui_story_5029_50290020_25_dialog_content = "…",
  ui_story_5029_50290020_26_dialog_content = "あっ、もう立ちあがってる！",
  ui_story_5029_50290020_27_dialog_content = "何か投げ捨てた！",
  ui_story_5029_50290020_28_dialog_content = "銀の箱だ！？",
  ui_story_5029_50290020_29_dialog_content = "箱が谷底に転がっていっちゃうよ！",
  ui_story_5029_50290020_30_dialog_content = "落ちたら、探すのは大変ね…",
  ui_story_5029_50290020_31_dialog_content = "私が拾いに行くわ！",
  ui_story_5029_50290020_32_dialog_content = "バイス？気を付けて――！",
  ui_story_5029_50290020_33_dialog_content = "ゲホゲホ…",
  ui_story_5029_50290020_34_dialog_content = "バイス…バイス？大丈夫？",
  ui_story_5029_50290020_35_dialog_content = "私は…大丈夫よ。",
  ui_story_5029_50290020_36_dialog_content = "なんで僕に何の相談もなく、\n突っ込んでいっちゃったの？",
  ui_story_5029_50290020_37_dialog_content = "危ないよ！",
  ui_story_5029_50290020_38_dialog_content = "PlayerName、私を甘く見過ぎじゃない？",
  ui_story_5029_50290020_39_dialog_content = "ゲホゲホ…見てのとおり、\n無事に上がってきたでしょ。",
  ui_story_5029_50290020_40_dialog_content = "そうは言うけど、本当に心配したよ…",
  ui_story_5029_50290020_41_dialog_content = "安心して。",
  ui_story_5029_50290020_42_dialog_content = "私は啓光で長いこと訓練を受けてるのよ！\nこんな小さな山で遭難するわけないでしょ？",
  ui_story_5029_50290020_43_dialog_content = "それに…見て！",
  ui_story_5029_50290020_44_dialog_content = "とうとう見つけたわ。ゲホッ…",
  ui_story_5029_50290020_45_dialog_content = "そんなにせきこんで…\nやっぱり、どこかケガしてるよね？",
  ui_story_5029_50290020_46_dialog_content = "本当に大丈夫だって。",
  ui_story_5029_50290020_47_dialog_content = "それより、犯人はまだそう遠くまで逃げてないわ。",
  ui_story_5029_50290020_48_dialog_content = "追いかけましょ！",
  ui_story_5029_50290020_49_dialog_content = "あ…",
  ui_story_5029_50290020_50_dialog_content = "バイス…？",
  ui_story_5029_50290020_51_dialog_content = "くるぶしの辺りが赤くなってる…\nはれてるんじゃないの？",
  ui_story_5029_50290020_52_dialog_content = "無理するのはよそうよ。\n早く戻ってお医者さんに診てもらおう。",
  ui_story_5029_50290020_53_dialog_content = "でも、あと1歩なのよ！犯人がすぐ近くにいるの！",
  ui_story_5029_50290020_54_dialog_content = "PlayerName、逃がすわけには行かないわ！",
  ui_story_5029_50290020_55_dialog_content = "あなただって、捕まえたいでしょ？",
  ui_story_5029_50290020_56_option_content = "バイスを説得する",
  ui_story_5029_50290020_57_dialog_content = "さっきからずっと「大丈夫」って言ってるけど、\n僕だって3歳の子供じゃないんだよ。",
  ui_story_5029_50290020_58_dialog_content = "ケガを隠してることぐらい、分かるよ。",
  ui_story_5029_50290020_59_dialog_content = "真犯人を捕まえたい気持ちがあることは認めるよ。\nでも、それより君のケガの方が心配なんだ。",
  ui_story_5029_50290020_60_dialog_content = "PlayerName…",
  ui_story_5029_50290020_61_dialog_content = "エルビスさんも言ってたでしょ。\n銀の箱が見つかればそれでいいって。",
  ui_story_5029_50290020_62_dialog_content = "だから、もう依頼は達成できたんだ。\n無理しないで。ねっ？",
  ui_story_5029_50290020_63_dialog_content = "…うん、分かった。",
  ui_story_5029_50290020_64_dialog_content = "PlayerNameさん、バイスさん、\nありがとうございます。",
  ui_story_5029_50290020_65_dialog_content = "こんなに早く見つけてくださるとは。",
  ui_story_5029_50290020_66_dialog_content = "バイスさんは啓光連邦で\n探索隊の隊長をしていらっしゃるとか？",
  ui_story_5029_50290020_67_dialog_content = "さすが、素晴らしい調査能力をお持ちです。\nお2人に助けて頂いて、私も光栄に思います！",
  ui_story_5029_50290020_68_dialog_content = "とんでもない！こちらこそ、わざわざ良い医者を\n呼んでくださってありがとうございます。",
  ui_story_5029_50290020_69_dialog_content = "箱を探すだけのことで、そんなケガをするなんて…",
  ui_story_5029_50290020_70_dialog_content = "えっ？あれが無くしたっていう銀の箱？",
  ui_story_5029_50290020_71_dialog_content = "思ったよりフツーだね。",
  ui_story_5029_50290020_72_dialog_content = "この度は、カレン殿下にもお力添えを頂き、\n誠にありがとうございました。",
  ui_story_5029_50290020_73_dialog_content = "この後はぜひ、ハーバーシティの旅を存分にお楽しみください！",
  ui_story_5029_50290020_74_dialog_content = "フィアもいるよ！",
  ui_story_5029_50290020_75_dialog_content = "もちろんです。\nフィアさんも、ありがとうございました。",
  ui_story_5029_50290020_76_dialog_content = "ささやかながら、皆さんにお礼をご用意させていただきました。\nハーバーシティならではの晩さん会も準備しております。",
  ui_story_5029_50290020_77_dialog_content = "こちらへどうぞ。",
  ui_story_5029_50290020_78_option_content = "バイスに合わせる",
  ui_story_5029_50290020_79_dialog_content = "もちろん、犯人を捕まえたいのは確かだよ。",
  ui_story_5029_50290020_80_dialog_content = "でも、君がケガしてるのに、放っておくことも…",
  ui_story_5029_50290020_81_dialog_content = "今日はどうしたの？",
  ui_story_5029_50290020_82_dialog_content = "私たち、一緒にいろんなことを経験してきたでしょ。\n私がくじけることなんてあった？",
  ui_story_5029_50290020_83_dialog_content = "…いや、君はいつだって勇敢だったね。",
  ui_story_5029_50290020_84_dialog_content = "PlayerName、私を信じて！",
  ui_story_5029_50290020_85_dialog_content = "これぐらいかすり傷よ、なんてことないわ。",
  ui_story_5029_50290020_86_dialog_content = "それに犯人は野放しにすれば、\n別の悪事を働くかもしれない…",
  ui_story_5029_50290020_87_dialog_content = "今、犯人を捕まえて裁きを受けさせられるのは、\n私たちだけよ。",
  ui_story_5029_50290020_88_dialog_content = "うん！",
  ui_story_5029_50290021_1_dialog_content = "キャロ、上出来！",
  ui_story_5029_50290021_2_dialog_content = "さっきはキャロが裏山への道を塞いでくれて助かったよ。",
  ui_story_5029_50290021_3_dialog_content = "山登りになったら、\n僕じゃ追いつけなかっただろうしね…",
  ui_story_5029_50290021_4_dialog_content = "でも、街の中だってアイツの方が速そうだよ？",
  ui_story_5029_50290021_5_dialog_content = "僕たちにはキャロが付いてるでしょ？",
  ui_story_5029_50290021_6_dialog_content = "ル…",
  ui_story_5029_50290021_7_dialog_content = "キャロ、あんただけが頼りだよ！",
  ui_story_5029_50290021_8_dialog_content = "さっきのアイツ、足止めして！",
  ui_story_5029_50290021_9_dialog_content = "ルルルル？",
  ui_story_5029_50290021_10_dialog_content = "キャロ、どうしたの？\n何をもたもたしてるの！",
  ui_story_5029_50290021_11_dialog_content = "悪いヤツがすぐ近くにいるの！",
  ui_story_5029_50290021_12_dialog_content = "ル…",
  ui_story_5029_50290021_13_dialog_content = "人どおりが増えてる…\n誰が犯人か分からなくなっちゃったんだ。",
  ui_story_5029_50290021_14_dialog_content = "それなら…大丈夫！\nマーキングガン、持ってるから。",
  ui_story_5029_50290021_15_dialog_content = "悪いヤツにマーキング弾を当てるから、\n銀の箱を持っていかれないように足止めして！",
  ui_story_5029_50290021_16_dialog_content = "キャロ、分かった？",
  ui_story_5029_50290021_17_dialog_content = "ルルル！",
  ui_story_5029_50290021_18_dialog_content = "必殺ショット…バシューン！！",
  ui_story_5029_50290021_19_dialog_content = "…？",
  ui_story_5029_50290021_20_dialog_content = "ル…ルルル！！！",
  ui_story_5029_50290021_21_dialog_content = "そう、その調子だよ、キャロ！\n追いついて、手にガブッとかみついて！",
  ui_story_5029_50290021_22_dialog_content = "ルルル～！",
  ui_story_5029_50290021_23_dialog_content = "！！！",
  ui_story_5029_50290021_24_dialog_content = "フィアがそんなにいい射撃の腕してるなんて、\n知らなかったよ。",
  ui_story_5029_50290021_25_dialog_content = "実はあたしも知らなかったの！",
  ui_story_5029_50290021_26_dialog_content = "<color=#828282>バシューン！</color>",
  ui_story_5029_50290021_27_dialog_content = "え？なんでもう1発撃ったの？",
  ui_story_5029_50290021_28_dialog_content = "あわわわ…どこに飛んだかな？",
  ui_story_5029_50290021_29_dialog_content = "キャロ、2発目は追わなくていいよ！",
  ui_story_5029_50290021_30_dialog_content = "銀の箱が持っていかれないように、\nそのままかみついてて！",
  ui_story_5029_50290021_31_dialog_content = "…！",
  ui_story_5029_50290021_32_dialog_content = "転んだ！",
  ui_story_5029_50290021_33_dialog_content = "キャロと銀の箱も巻き込まれちゃったね…",
  ui_story_5029_50290021_34_dialog_content = "キャロ、大丈夫？",
  ui_story_5029_50290021_35_dialog_content = "ルルル！",
  ui_story_5029_50290021_36_dialog_content = "キャロのおかげで銀の箱は無傷だよ！",
  ui_story_5029_50290021_37_dialog_content = "今日は大手柄だね。",
  ui_story_5029_50290021_38_dialog_content = "ヘヘヘ…銀の箱を持ち帰れば、\n賞金はあたしのもの！",
  ui_story_5029_50290021_39_dialog_content = "まずい、あいつが港の方へ逃げてく！",
  ui_story_5029_50290021_40_dialog_content = "ふん、フィアから\n逃げられると思ってるの？",
  ui_story_5029_50290021_41_dialog_content = "追いかけるよ！",
  ui_story_5029_50290021_42_dialog_content = "待て！",
  ui_story_5029_50290021_43_dialog_content = "えっ？あたし？",
  ui_story_5029_50290021_44_dialog_content = "さっき街中で発砲したのはお前だな？\nたいした度胸じゃないか。",
  ui_story_5029_50290021_45_dialog_content = "正直に吐け！\n一体誰に言われて俺を襲った？",
  ui_story_5029_50290021_46_dialog_content = "あっ…2発目が当たっちゃってたのか…",
  ui_story_5029_50290021_47_dialog_content = "つまり、何度も撃ったということか？",
  ui_story_5029_50290021_48_dialog_content = "ハーバーシティの治安を故意に乱そうとしたのだな！\n一緒に来てもらおうか！",
  ui_story_5029_50290021_49_dialog_content = "フィア、今は大事な用事の最中なんだよ。\nそれどころじゃないの！",
  ui_story_5029_50290021_50_dialog_content = "抵抗する気か！？",
  ui_story_5029_50290021_51_dialog_content = "ちょっと待ってください！\n誤解なんです。",
  ui_story_5029_50290021_52_dialog_content = "お前はこのガキの兄か何かか？",
  ui_story_5029_50290021_53_dialog_content = "そんなわけないでしょ！\nフィアにお兄ちゃんはいないもん！\nPlayerNameはフィアが捕まえた珍獣！",
  ui_story_5029_50290021_54_dialog_content = "…？よく分からんが、仲間というワケだな！？\nならば、一緒に来てもらおう！",
  ui_story_5029_50290021_55_dialog_content = "ええと、さっき僕たちは、\nちょっとあわてていて…ほら、フィア…",
  ui_story_5029_50290021_56_dialog_content = "2発目のことは、確かに僕たちが悪いんだ。\nここは素直に謝ろう。",
  ui_story_5029_50290021_57_dialog_content = "ふん…",
  ui_story_5029_50290021_58_dialog_content = "フィア？",
  ui_story_5029_50290021_59_dialog_content = "ふん…わかったって。\nさっきのは、あたしの不注意。ごめんなさい。",
  ui_story_5029_50290021_60_dialog_content = "すみませんでした。",
  ui_story_5029_50290021_61_dialog_content = "謝って済むなら、\n衛兵なんかいらんだろうが？",
  ui_story_5029_50290021_62_dialog_content = "とにかく、取り調べを受けてもらうぞ！",
  ui_story_5029_50290021_63_option_content = "私兵について行く",
  ui_story_5029_50290021_64_dialog_content = "分かりました、ついて行きます。",
  ui_story_5029_50290021_65_dialog_content = "PlayerName、何言ってんの？\n犯人はどうするの…？",
  ui_story_5029_50290021_66_dialog_content = "エルビスさんも言ってたでしょ。\n銀の箱が見つかればそれでいいって。",
  ui_story_5029_50290021_67_dialog_content = "僕も犯人を捕まえたいとは思ってるけど、\nこの人に今すぐ事情を分かってもらうのは無理だよ。",
  ui_story_5029_50290021_68_dialog_content = "余計な面倒は増やさないでおこう。",
  ui_story_5029_50290021_69_dialog_content = "わかったよ…ま、あたしは賞金をもらえれば、\nそれでいいし。",
  ui_story_5029_50290021_70_dialog_content = "何をごちゃごちゃ言ってる？",
  ui_story_5029_50290021_71_dialog_content = "大人しくついていきます。\nただ、領主さんのところに連れて行ってもらえますか？",
  ui_story_5029_50290021_72_dialog_content = "領主様はこんなちっぽけなことにかまうほど、\nヒマじゃないぞ。",
  ui_story_5029_50290021_73_dialog_content = "とにかく…直接会えば、\n事情が分かるはずです。",
  ui_story_5029_50290021_74_dialog_content = "このお2人は私の客人だ。\n彼らのしたことについては私が責任を持つ。",
  ui_story_5029_50290021_75_dialog_content = "これだけあれば、マーキング弾の\n汚れを落とすのに十分か？",
  ui_story_5029_50290021_76_dialog_content = "十分です、十分すぎます！\nありがとうございました、領主様！",
  ui_story_5029_50290021_77_dialog_content = "PlayerNameさん、フィアさん、\nありがとうございます！",
  ui_story_5029_50290021_78_dialog_content = "こんなに早く見つけてくださるとは。",
  ui_story_5029_50290021_79_dialog_content = "フィアさんは、珍獣マスターで\nいらっしゃるそうですね？",
  ui_story_5029_50290021_80_dialog_content = "私も珍獣に関する書物を\n少しばかり読みあさったことがございまして。\n機会があれば、ぜひお話をうかがいたいものです！",
  ui_story_5029_50290021_81_dialog_content = "ヘヘヘ、あたしが弟子をとる日がくるなんて、\n思ってもなかったよ…",
  ui_story_5029_50290021_82_dialog_content = "フィア、エルビスさんはそういう意味で\n言ったんじゃないと思うよ。",
  ui_story_5029_50290021_83_dialog_content = "いずれにせよ、お2人に助けて頂いたことは、\n私にとって大変な光栄です。",
  ui_story_5029_50290021_84_dialog_content = "もう、領主のおじさん、\nそんなにかしこまらないでいいの！",
  ui_story_5029_50290021_85_dialog_content = "でも、途中でジャマが入らなかったら、\nきっと犯人も捕まえられてたんだけどな～…",
  ui_story_5029_50290021_86_dialog_content = "フィア、まさか、\n街中の人たちに知られてないわよね…？",
  ui_story_5029_50290021_87_dialog_content = "それでは秘密調査にならないわよ？",
  ui_story_5029_50290021_88_dialog_content = "大丈夫だよ。犯人を追ってるところを見られたとしても、\n理由までは誰も分からないでしょ。",
  ui_story_5029_50290021_89_dialog_content = "カレン殿下とバイスさんにも、\nお時間をとらせてしまいました。",
  ui_story_5029_50290021_90_dialog_content = "この後はぜひ、ハーバーシティの旅を存分にお楽しみください！",
  ui_story_5029_50290021_91_dialog_content = "ささやかながら、皆さんにお礼をご用意させていただきました。\nハーバーシティならではの晩さん会も準備しております。",
  ui_story_5029_50290021_92_dialog_content = "こちらへどうぞ。",
  ui_story_5029_50290021_93_option_content = "ついて行かない",
  ui_story_5029_50290021_94_dialog_content = "すみません。僕たち、領主さん直々に頼まれた\n本当に大事な用があるんです。",
  ui_story_5029_50290021_95_dialog_content = "よく考えてください。\nもし、僕たちのジャマをして…",
  ui_story_5029_50290021_96_dialog_content = "僕たちが依頼を失敗したとなったら、\nあなたの責任も問われますよ。",
  ui_story_5029_50290021_97_dialog_content = "むっ…",
  ui_story_5029_50290021_98_dialog_content = "だったら、証拠はあるのか？\n口先だけで信じろと言うのか？",
  ui_story_5029_50290021_99_dialog_content = "信じられないなら、今すぐ僕たちを連れて\n領主さんのところに行けばいいでしょう。",
  ui_story_5029_50290021_100_dialog_content = "直接事情が聞けますよ。",
  ui_story_5029_50290022_1_dialog_content = "うわ～！！",
  ui_story_5029_50290022_2_dialog_content = "ハーバーシティに来てから初めて\nこんなにたくさん、おいしそうなものを見たよ…",
  ui_story_5029_50290022_3_dialog_content = "領主のおじさん、なかなかいい人だね！",
  ui_story_5029_50290022_4_dialog_content = "今日は走り回ったから、もうお腹と背中がくっつきそう！\nじゃ、エンリョなく…いっただっきま～す！！",
  ui_story_5029_50290022_5_dialog_content = "…ゆっくり食べなさい。\n誰も取ったりしないわ。",
  ui_story_5029_50290022_6_dialog_content = "この箱一杯の白夜コイン、\n全部、私たちがもらっていいの？",
  ui_story_5029_50290022_7_dialog_content = "太っ腹すぎるわ！",
  ui_story_5029_50290022_8_dialog_content = "全員にってことだし、\nどう分けたものかしら。",
  ui_story_5029_50290022_9_dialog_content = "一番の功労者は…",
  ui_story_5029_50290022_10_dialog_content = "バイス、学生時代から\nそんなにお金にうるさい方だったかしら？",
  ui_story_5029_50290022_11_dialog_content = "そ、それは…オホン！\n生きていくために、必要な事でしょ？",
  ui_story_5029_50290022_12_dialog_content = "私は白夜城のお嬢様とか王子様みたいに、\nどこでも誰かが面倒みてくれるわけじゃないもの。",
  ui_story_5029_50290022_13_dialog_content = "…そういうことなら、お金はあなたたちで分けて。\n私の分は計算に入れなくていいわ。",
  ui_story_5029_50290022_14_dialog_content = "えええええっ！？いらないの！？\nだったら、フィアにちょうだい！",
  ui_story_5029_50290022_15_dialog_content = "シーラ先輩にプレゼント買ってあげるんだ。\nそうすれば、ちょっとは優しくしてくれるようになるでしょ！",
  ui_story_5029_50290022_16_dialog_content = "カレンの分も均等に分けましょ。\nそれが公平ってことよ。",
  ui_story_5029_50290022_17_dialog_content = "キャロ、キャロ！\nはい、口開けて！",
  ui_story_5029_50290022_18_dialog_content = "フィア、ペットを食卓に上げてはいけないわ。",
  ui_story_5029_50290022_19_dialog_content = "キャロはあたしの仲間だよ。\nペットじゃないもん！",
  ui_story_5029_50290022_20_dialog_content = "（うっ、3人の空気が怪しくなってきた…）",
  ui_story_5029_50290022_21_dialog_content = "（それにしてもエルビスさん、席を外してからずいぶん経つなぁ。\n戻って来てくれれば、このフンイキも何とかなるかもしれないのに…）",
  ui_story_5029_50290022_22_dialog_content = "（はあ、こんなことなら始めから…）",
  ui_story_5029_50290022_23_dialog_content = "領主様…",
  ui_story_5029_50290022_24_dialog_content = "何だと！？",
  ui_story_5029_50290022_25_dialog_content = "（やっと戻って来た…）",
  ui_story_5029_50290022_26_dialog_content = "（と思ったら、何か耳打ちされた？）",
  ui_story_5029_50290022_27_dialog_content = "（どうして顔色が急に変わったんだろう？）",
  ui_story_5029_50290022_28_dialog_content = "（うっ…息が急にあがってきた）",
  ui_story_5029_50290022_29_dialog_content = "（なんでだろう、イヤな予感がする…）",
  ui_story_5029_50290022_30_dialog_content = "（一体何が？）",
  ui_story_5029_50290022_31_dialog_content = "（…まさか、銀の箱の泥棒が！？）",
  ui_story_5029_50290022_32_dialog_content = "（また、戻ってきた？）",
  ui_story_5029_50290022_33_dialog_content = "（今度は何をしたんだろう…）",
  ui_story_5029_50290022_34_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5029_50290022_35_dialog_content = "おかえりなさいませ。",
  ui_story_5029_50290022_36_dialog_content = "僕の顔を見てがっかりなさいましたか？",
  ui_story_5029_50290022_37_dialog_content = "これでお分かりになったでしょう？\n運命を己の手に握ることは、簡単ではないのです。",
  ui_story_5029_50290022_38_dialog_content = "それに、あなたはご自分で作り出した結末に、\n満足していらっしゃらないご様子。",
  ui_story_5029_50290022_39_dialog_content = "疑問や戸惑いがたくさん浮かんでいるのではないですか？\nフフフ…",
  ui_story_5029_50290022_40_dialog_content = "とはいえそれは、夢の世界のことだけではありません。\n現実の世界でも同じことでしょう？",
  ui_story_5029_50290022_41_dialog_content = "明確な答えなど、どこにもないのです。",
  ui_story_5029_50290022_42_dialog_content = "ですが、選ぶことをいつも他人にゆだねていては、\nいつまで経っても自分の物語を得ることはできません。",
  ui_story_5029_50290022_43_dialog_content = "幸い、僕たちにはまだ時間があります。",
  ui_story_5029_50290022_44_dialog_content = "ただし、あなたがまだ、\n夢の中の結末を書き換えたいと思っていればの話、ですが。",
  ui_story_5029_50290023_1_dialog_content = "カレン、どう？",
  ui_story_5029_50290023_2_dialog_content = "…",
  ui_story_5029_50290023_3_dialog_content = "ずるがしこい手合いね。\n痕跡がまったく残っていない…",
  ui_story_5029_50290023_4_dialog_content = "僕も感知できない…",
  ui_story_5029_50290023_5_dialog_content = "私としたことが、\n犯人を逃してしまうなんて…",
  ui_story_5029_50290023_6_dialog_content = "僕のせいだ。気を失ったりしなければ、\nとっくに犯人を捕まえてられてたはず…",
  ui_story_5029_50290023_7_dialog_content = "私をかばってのことよ。\nそんなことを言わないで。",
  ui_story_5029_50290023_8_dialog_content = "だけど…あの時、僕はもっとうまくやれたはず…",
  ui_story_5029_50290023_9_dialog_content = "それにあいつは僕が今まで会った中で、\n逃げ足が誰よりも早かった。",
  ui_story_5029_50290023_10_dialog_content = "上り坂でも息がぜんぜん切れる様子がなかった。\n暗鬼でもああは行かないよ。",
  ui_story_5029_50290023_11_dialog_content = "なぐさめは無用よ、PlayerName。",
  ui_story_5029_50290023_12_dialog_content = "私の気持ちを楽にしようと\nしてくれているのよね。",
  ui_story_5029_50290023_13_dialog_content = "でも…知っているかしら。",
  ui_story_5029_50290023_14_dialog_content = "騎士というものは、\n率いている兵の数や経験した戦いの数ではない…",
  ui_story_5029_50290023_15_dialog_content = "騎士とは、責任を負う器なのよ。\n失敗も含めた自分の行い、すべてに対して。",
  ui_story_5029_50290023_16_dialog_content = "カレン…",
  ui_story_5029_50290023_17_dialog_content = "どうしたの？突然そんな顔をして。",
  ui_story_5029_50290023_18_dialog_content = "君が同じ年ぐらいの僕たちよりもずっと、\n冷静で気品の高い人だってことはとっくに知ってたけど…",
  ui_story_5029_50290023_19_dialog_content = "最近、今まで以上に大人みたいに感じるよ。",
  ui_story_5029_50290023_20_dialog_content = "ほめ言葉として受け取っておくわ。\nありがとう。",
  ui_story_5029_50290023_21_dialog_content = "…君はいつも、自分を抑えてるように見えるね。",
  ui_story_5029_50290023_22_dialog_content = "え？",
  ui_story_5029_50290023_23_dialog_content = "僕の錯覚かもしれないけど…",
  ui_story_5029_50290023_24_dialog_content = "カレンは何でもできる、弱点のない聖人に\nなろうとして、無理をしてるような気がするんだ。",
  ui_story_5029_50290023_25_dialog_content = "…",
  ui_story_5029_50290023_26_dialog_content = "そのせいなのかな。\n君が強く、決然としようとしてるほど、僕の心が痛んでくる。",
  ui_story_5029_50290023_27_dialog_content = "君が僕みたいに大ざっぱでいられないのが、苦しいんだ。",
  ui_story_5029_50290023_28_dialog_content = "君が自分の感情を吐き出せてないのも、苦しい。",
  ui_story_5029_50290023_29_dialog_content = "もうたくさんのものを背負ってるのに、\nたくさんの人から弱々しい温室育ちの花だと笑われてるのが…",
  ui_story_5029_50290023_30_dialog_content = "…",
  ui_story_5029_50290023_31_dialog_content = "…フッ…クスクスクス…",
  ui_story_5029_50290023_32_dialog_content = "な、何がおかしいの？",
  ui_story_5029_50290023_33_dialog_content = "ごめんなさい。\n私もどうして笑ったのか、分からないわ。",
  ui_story_5029_50290023_34_dialog_content = "ただ…今までそんなことを言われたことがないから、\nどう答えていいのか、少し分からなくなったの。",
  ui_story_5029_50290023_35_dialog_content = "うん、き、気にしないで。\n急にヘンなこと言っちゃって、ごめん。",
  ui_story_5029_50290023_36_dialog_content = "さっき頭をぶつけちゃったせいかな…",
  ui_story_5029_50290023_37_dialog_content = "それよりも、今は戻ったらエルビスさんに\nどう説明するか、考えないと。",
  ui_story_5029_50290023_38_dialog_content = "何も収穫がなかったわけではないわ。\n少なくとも銀の箱は取り返したもの。",
  ui_story_5029_50290023_39_dialog_content = "それに…偶然だけど、\nもう一つ、宝の隠し場所を見つけたわ。",
  ui_story_5029_50290023_40_dialog_content = "「宝の隠し場所」？",
  ui_story_5029_50290023_41_dialog_content = "PlayerName、上を見て。",
  ui_story_5029_50290023_42_dialog_content = "えっ？",
  ui_story_5029_50290023_43_dialog_content = "ほら、山頂に古い展望台があるわ。",
  ui_story_5029_50290023_44_dialog_content = "ハーバーシティの夜景を一望できそう。",
  ui_story_5029_50290023_45_dialog_content = "きっと、ハーバーシティの向こうに見えていた山にいるのよね？",
  ui_story_5029_50290023_46_dialog_content = "この見晴らしもうなずけるわ。",
  ui_story_5029_50290023_47_dialog_content = "ハーバーシティにこんな素敵な所があるなんて\n聞いたこともなかった！",
  ui_story_5029_50290023_48_dialog_content = "（カレン…急に楽しそうになった？）",
  ui_story_5029_50290023_49_dialog_content = "どうしたの？PlayerName。",
  ui_story_5029_50290023_50_dialog_content = "いい景色だわ。本当に。",
  ui_story_5029_50290023_51_dialog_content = "海は深い眠りについた黒い獣のよう。\nそして、ハーバーシティだけが消えない灯…",
  ui_story_5029_50290023_52_dialog_content = "街全体がアストラ大陸にはめ込まれた、\nらでん細工のように輝いているわ…",
  ui_story_5029_50290023_53_dialog_content = "本当に…きれいだね。",
  ui_story_5029_50290023_54_option_content = "ありがとう、カレン",
  ui_story_5029_50290023_55_dialog_content = "私の方こそ、ありがとう。",
  ui_story_5029_50290023_56_dialog_content = "僕が何にありがとうって言ったのか、\nまだ話してなかったんだけど…",
  ui_story_5029_50290023_57_dialog_content = "お互い様よ。私も言っていないから。",
  ui_story_5029_50290023_58_dialog_content = "ど、どうしたの…？\n急にそんな子供っぽい言い返し方…",
  ui_story_5029_50290023_59_dialog_content = "さっき、私が大人びてると\n文句を言われたばかりだもの？",
  ui_story_5029_50290023_60_option_content = "何か僕に言いたいことでも？",
  ui_story_5029_50290023_61_dialog_content = "そうね…",
  ui_story_5029_50290023_62_dialog_content = "知っているかしら？\n白夜城の夜景もハーバーシティに劣らないわ。",
  ui_story_5029_50290023_63_dialog_content = "ただ、あの頃の私はいつも一人で、\n任務を遂行しているか、そのためにどこかへ行く途中だった。",
  ui_story_5029_50290023_64_dialog_content = "私が何とかしないと、\n白夜城がどうにかなってしまうと思っていたわ。",
  ui_story_5029_50290023_65_dialog_content = "そうして、どんどん思い詰めて…",
  ui_story_5029_50290023_66_dialog_content = "足を止めることもせず、\n夜の美しさを愛でるということもしなかった。",
  ui_story_5029_50290023_67_dialog_content = "あの頃の私は、きっと想像できなかったでしょうね。\n数年後のある日…",
  ui_story_5029_50290023_68_dialog_content = "無事に依頼を片づけた後、\nここでゆっくり景色を楽しむなんて。",
  ui_story_5029_50290023_69_dialog_content = "ハハハ…そうかも。昔のカレンだったら、\nきっとこんな日が来るとは思わなかっただろうね。",
  ui_story_5029_50290023_70_dialog_content = "隣に空の末裔が一緒にいるなどということも、\nきっと想像できなかったわ。",
  ui_story_5029_50290023_71_dialog_content = "なんだか、僕が君を悪い方に\n導いちゃったみたいな言い方だね…",
  ui_story_5029_50290023_72_dialog_content = "私はあなたに出会えて\nよかったと思っているわ。",
  ui_story_5029_50290023_73_dialog_content = "それが答えだと思って。",
  ui_story_5029_50290023_74_dialog_content = "えっ？な、何の…？",
  ui_story_5029_50290023_75_dialog_content = "さっき、誰かさんが何か\n言っていなかったかしら？",
  ui_story_5029_50290023_76_dialog_content = "僕は…",
  ui_story_5029_50290023_77_dialog_content = "見て…あれってサーカスではないかしら？",
  ui_story_5029_50290023_78_dialog_content = "それから、あそこは…\n今日、私たちが調べた高級ホテルね。",
  ui_story_5029_50290023_79_dialog_content = "（今のカレンはまったく警戒してないみたいだ）",
  ui_story_5029_50290023_80_dialog_content = "（こんなに楽しそうに笑ったり、\nはしゃいだりするカレン、\n今まで見たことなかったな…）",
  ui_story_5029_50290023_81_dialog_content = "（こういう子供っぽい素顔も、\n一種の秘密になるのかな）",
  ui_story_5029_50290023_82_dialog_content = "（僕たち2人だけの秘密…）",
  ui_story_5029_50290023_83_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5029_50290023_84_dialog_content = "おかえりなさいませ。",
  ui_story_5029_50290023_85_dialog_content = "僕の顔を見てがっかりなさいましたか？",
  ui_story_5029_50290023_86_dialog_content = "申し訳ありません、\nうっかりお2人の秘密をのぞいてしまったようです…",
  ui_story_5029_50290023_87_dialog_content = "ですが、そんなにガッカリすることはありませんよ。",
  ui_story_5029_50290023_88_dialog_content = "夢は現実をもとに造りあげられるものです。",
  ui_story_5029_50290023_89_dialog_content = "つまり…あなたと彼女の間は、\n現実世界でも同じような状態である可能性があるのです。",
  ui_story_5029_50290023_90_dialog_content = "ただ、夢の世界と異なることは…\n現実世界に、タネやしかけがないということです。",
  ui_story_5029_50290023_91_dialog_content = "僕が生み出す虚構の世界の中で生き続けるというのは…\nやはり難しいでしょうね。",
  ui_story_5029_50290023_92_dialog_content = "それでは、自ら書き上げられた結末に、\nご満足はいただけましたか？",
  ui_story_5029_50290023_93_dialog_content = "心残りはございませんか？",
  ui_story_5029_50290023_94_dialog_content = "僕が言いたいのは…\nまだ時間はあるということです。",
  ui_story_5029_50290023_95_dialog_content = "夢の中の、あの謎を解きたい、答えを知りたいと\nあなたがまだ思っていればの話ですが。",
  ui_story_5029_50290024_1_dialog_content = "見つけたわ！",
  ui_story_5029_50290024_2_dialog_content = "あそこの草むらに隠れてる…",
  ui_story_5029_50290024_3_dialog_content = "え？",
  ui_story_5029_50290024_4_dialog_content = "よく見て、服のすそが見えてる！\nあいつを捕まえてくるわね。",
  ui_story_5029_50290024_5_dialog_content = "ちょっと待って……",
  ui_story_5029_50290024_6_dialog_content = "今度こそ逃がさないわ…",
  ui_story_5029_50290024_7_dialog_content = "当たって！",
  ui_story_5029_50290024_8_dialog_content = "<color=#828282>ドカン！</color>",
  ui_story_5029_50290024_9_dialog_content = "あ…",
  ui_story_5029_50290024_10_dialog_content = "バイス！！！",
  ui_story_5029_50290024_11_dialog_content = "PlayerName…ごめんなさい…",
  ui_story_5029_50290024_12_dialog_content = "ふぅ…なんで急に謝ったの？",
  ui_story_5029_50290024_13_dialog_content = "ずっと考えてたの。私って時どき衝動的になっちゃうわよね。\nとにかく早く、問題を解決しようって…",
  ui_story_5029_50290024_14_dialog_content = "それで、すぐ近くの危険を見落とすことも多いわ。",
  ui_story_5029_50290024_15_dialog_content = "今も…そうだった。",
  ui_story_5029_50290024_16_dialog_content = "犯人を見つけたからって、何も考えずにあなたを連れて、\nこんなところまで来ちゃって…",
  ui_story_5029_50290024_17_dialog_content = "その結果、ワナにかかるなんて。",
  ui_story_5029_50290024_18_dialog_content = "足首をくじいただけならまだしも、\nあなたに背負ってもらうなんて…迷惑をかけちゃったわ。",
  ui_story_5029_50290024_19_dialog_content = "だから、ごめん…",
  ui_story_5029_50290024_20_dialog_content = "ハハ…バイス、そんなこと言わないでよ。",
  ui_story_5029_50290024_21_dialog_content = "追いかけるって、2人で決めたことだよ。\nぜんぶ君のせいってわけじゃない。",
  ui_story_5029_50290024_22_dialog_content = "それに、直前まで僕が先頭を歩いてたんだ。\n君をあそこまで連れていったのは僕だ…",
  ui_story_5029_50290024_23_dialog_content = "謝るとしたら、僕の方だよ。",
  ui_story_5029_50290024_24_dialog_content = "PlayerName、なぐさめてくれなくていいの。",
  ui_story_5029_50290024_25_dialog_content = "今日、犯人を取り逃がしたのは、\n私のせいなんだから。",
  ui_story_5029_50290024_26_dialog_content = "ねぇ、覚えてる？",
  ui_story_5029_50290024_27_dialog_content = "君がもし、後先考えずに\nソラヴァンに穴を開けてなかったら…",
  ui_story_5029_50290024_28_dialog_content = "僕は君と出会うこともなかった。\nきっと一生、地下から出られなかった。",
  ui_story_5029_50290024_29_dialog_content = "あれは別の話よ…",
  ui_story_5029_50290024_30_dialog_content = "あの時はちゃんと調べてから…",
  ui_story_5029_50290024_31_dialog_content = "あっ、ちょっと待って。\n今までずっと「後先考えずに」やったと思ってたの？",
  ui_story_5029_50290024_32_dialog_content = "えっ、違った？アハハ…",
  ui_story_5029_50290024_33_dialog_content = "今までずっと、心の中で私のことを笑ってたのね？",
  ui_story_5029_50290024_34_dialog_content = "ちょっと、叩かないで。",
  ui_story_5029_50290024_35_dialog_content = "あ、ごめんなさい…痛かった？",
  ui_story_5029_50290024_36_dialog_content = "痛くはないよ。ただ、す、少しだけ…\n背負ってるのが厳しくなってきた…",
  ui_story_5029_50290024_37_dialog_content = "あそこに芝生があるわ。\nそこで私を下ろして。",
  ui_story_5029_50290024_38_dialog_content = "うん。また足を痛めないように気を付けてね。",
  ui_story_5029_50290024_39_dialog_content = "ふぅ…一日中走り回って、\nようやく横になれた…",
  ui_story_5029_50290024_40_dialog_content = "私、重すぎたかしら…",
  ui_story_5029_50290024_41_dialog_content = "そんなことないよ、ただ…",
  ui_story_5029_50290024_42_dialog_content = "ただ…？",
  ui_story_5029_50290024_43_dialog_content = "帰り道、まだ先は長そうだね。",
  ui_story_5029_50290024_44_dialog_content = "…また笑われるのかと思ったわ。",
  ui_story_5029_50290024_45_dialog_content = "バイス。",
  ui_story_5029_50290024_46_dialog_content = "え？",
  ui_story_5029_50290024_47_dialog_content = "僕は君のこと、笑ったりしないよ。",
  ui_story_5029_50290024_48_dialog_content = "…",
  ui_story_5029_50290024_49_dialog_content = "君は僕を地下から出してくれた。\nそして、いつも前に進むようにはげましてくれてる。",
  ui_story_5029_50290024_50_dialog_content = "君がいなかったら、僕はたくさんの人と知り合うことも、\nこんなにたくさんの景色を見ることもなかった。",
  ui_story_5029_50290024_51_dialog_content = "もう、分かってるわ。",
  ui_story_5029_50290024_52_dialog_content = "何度も聞いてるもの。\nなんだってまた、その話なの？",
  ui_story_5029_50290024_53_dialog_content = "ほかの皆は君がこんなに一生懸命事件を追ってるのは、\nお金が目当てだって思ってるかもしれないけど…",
  ui_story_5029_50290024_54_dialog_content = "皆、君が啓光の人だってことを忘れてる。\nお金をもらったところで、君自身には大した意味がない。",
  ui_story_5029_50290024_55_dialog_content = "そんなに必死になってるのは、\n巨像の予算にしたいからだよね。",
  ui_story_5029_50290024_56_dialog_content = "あはは、分かっちゃった…？\nいいのよ。皆、仲間なんだから！",
  ui_story_5029_50290024_57_dialog_content = "これが私のやるべきことなの。",
  ui_story_5029_50290024_58_dialog_content = "さっき君を背負いながら、\nいろいろ考えてたんだ。",
  ui_story_5029_50290024_59_dialog_content = "今まで君が、いつも側でなぐさめたり、\nはげましたりしてくれたから、\n僕は仲間に頼ることを覚えたんだ。",
  ui_story_5029_50290024_60_dialog_content = "でも、僕は考えたことなかった…",
  ui_story_5029_50290024_61_dialog_content = "バイス、いつもそんなに強くなくてもいいんだよ。",
  ui_story_5029_50290024_62_dialog_content = "えっ？",
  ui_story_5029_50290024_63_dialog_content = "君も、今日みたいに…",
  ui_story_5029_50290024_64_dialog_content = "たまには仲間に…僕に頼ってもいいんだ！",
  ui_story_5029_50290024_65_dialog_content = "PlayerName…",
  ui_story_5029_50290024_66_option_content = "いつも本当にありがとう！",
  ui_story_5029_50290024_67_dialog_content = "あなたがそういうなら、私…",
  ui_story_5029_50290024_68_dialog_content = "フフフ…遠慮しないわよ？",
  ui_story_5029_50290024_69_dialog_content = "それじゃ…これからも、よろしくね！",
  ui_story_5029_50290024_70_dialog_content = "お互いにね。",
  ui_story_5029_50290024_71_dialog_content = "ステキね…",
  ui_story_5029_50290024_72_dialog_content = "え？何が？",
  ui_story_5029_50290024_73_dialog_content = "ここから見る夕日よ。",
  ui_story_5029_50290024_74_dialog_content = "足のケガがなかったら、\nもっと良かったんだけど。",
  ui_story_5029_50290024_75_option_content = "ねぇ、大丈夫？",
  ui_story_5029_50290024_76_dialog_content = "大丈夫よ…",
  ui_story_5029_50290024_77_dialog_content = "ちょっと考えてただけ。\n今日起こった事を、一通り。",
  ui_story_5029_50290024_78_dialog_content = "蔵書館で調査していた時のこと…",
  ui_story_5029_50290024_79_dialog_content = "劇場でお芝居を観たこと…",
  ui_story_5029_50290024_80_dialog_content = "それから、私がケガをしてから、\nあなたがずっと色々気を使ってること…",
  ui_story_5029_50290024_81_dialog_content = "今までぜんぜん考えてなかったわ。\nあなたがそんなに他人を気づかってたなんて。",
  ui_story_5029_50290024_82_dialog_content = "PlayerNameは本当に頼りがいのある仲間だわ。",
  ui_story_5029_50290024_83_dialog_content = "当たり前でしょ！",
  ui_story_5029_50290024_84_dialog_content = "それから…今、この時間を大切にしたい。",
  ui_story_5029_50290024_85_dialog_content = "<color=#828282>ヒュウゥ…</color>",
  ui_story_5029_50290024_86_dialog_content = "心地よい風が芝生の上に吹いて、\n髪の毛をなでていく…",
  ui_story_5029_50290024_87_dialog_content = "夕日も雲に絵を描いてるみたいだわ。",
  ui_story_5029_50290024_88_dialog_content = "その真ん中で、私たち2人だけ、\n静かにぼうっとしてる…",
  ui_story_5029_50290024_89_dialog_content = "こんな時間がずっと続けばいいのにって、思えて来るわ。",
  ui_story_5029_50290024_90_dialog_content = "なんだかステキだね。でも…",
  ui_story_5029_50290024_91_dialog_content = "それってずっと足をくじいたまま、\n僕に背負われてたいってこと？",
  ui_story_5029_50290024_92_dialog_content = "もう、ほめてあげて損した！",
  ui_story_5029_50290024_93_dialog_content = "やっぱりあなたって、\n女の子の気持ちが分かってないわね…",
  ui_story_5029_50290024_94_dialog_content = "黙って夕日を見てた方がマシよ！",
  ui_story_5029_50290024_95_dialog_content = "エヘン、エヘン…冗談だよ。",
  ui_story_5029_50290024_96_dialog_content = "じゃあ、こうしようか？",
  ui_story_5029_50290024_97_dialog_content = "ケガが治ったら、\nまた一緒にここで夕日を見に来よう。",
  ui_story_5029_50290024_98_dialog_content = "約束よ！破ったら許さないから。",
  ui_story_5029_50290024_99_dialog_content = "もし破ったら、\nトゲトゲに刺されても文句は言わないよ！",
  ui_story_5029_50290024_100_dialog_content = "アハハ。だったら約束、守ってね…",
  ui_story_5029_50290024_101_dialog_content = "（バイスはケガこそしてるけど、\nいつもよりずっと肩の力が抜けて、楽しそうだ）",
  ui_story_5029_50290024_102_dialog_content = "（風が冷たくなったな…\n鼻から入った空気を胸に感じる）",
  ui_story_5029_50290024_103_dialog_content = "（急に世界全部が遠くにいってしまったみたいだ。\n自分の鼓動だけがはっきり聞こえる）",
  ui_story_5029_50290024_104_dialog_content = "（僕、何かに期待しちゃってるみたいだ…）",
  ui_story_5029_50290024_105_dialog_content = "（2人だけの、秘密の約束…）",
  ui_story_5029_50290024_106_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5029_50290024_107_dialog_content = "おかえりなさいませ。",
  ui_story_5029_50290024_108_dialog_content = "僕の顔を見てがっかりなさいましたか？",
  ui_story_5029_50290024_109_dialog_content = "申し訳ありません、\nうっかりお2人の秘密をのぞいてしまったようです…",
  ui_story_5029_50290024_110_dialog_content = "ですが、そんなにガッカリすることはありませんよ。",
  ui_story_5029_50290024_111_dialog_content = "夢は現実をもとに造りあげられるものです。",
  ui_story_5029_50290024_112_dialog_content = "つまり…あなたと彼女の間は、\n現実世界でも同じような状態である可能性があるのです。",
  ui_story_5029_50290024_113_dialog_content = "ただ、夢の世界と異なることは…\n現実世界に、タネやしかけがないということです。",
  ui_story_5029_50290024_114_dialog_content = "僕が生み出す虚構の世界の中で生き続けるというのは…\nやはり難しいでしょうね。",
  ui_story_5029_50290024_115_dialog_content = "それでは、自ら書き上げられた結末に、\nご満足はいただけましたか？",
  ui_story_5029_50290024_116_dialog_content = "心残りはございませんか？",
  ui_story_5029_50290024_117_dialog_content = "僕が言いたいのは…\nまだ時間はあるということです。",
  ui_story_5029_50290024_118_dialog_content = "夢の中の、あの謎を解きたい、答えを知りたいと\nあなたがまだ思っていればの話ですが。",
  ui_story_5029_50290025_1_dialog_content = "PlayerName、カッコよかった！",
  ui_story_5029_50290025_2_dialog_content = "あのおじさん、最初はあんなに怖そうだったのに、\nあんたがちょっと話しただけでビビっちゃって！",
  ui_story_5029_50290025_3_dialog_content = "フィアの撃ったマーキング弾が\n間違って当たっただけのことなのに…",
  ui_story_5029_50290025_4_dialog_content = "別に痛いものでもないのに、\n捕まえようとするのが悪いの、フン！",
  ui_story_5029_50290025_5_dialog_content = "痛いかどうかは置いておいて、\n当てちゃったのは、確かに僕たちがいけないんだ。",
  ui_story_5029_50290025_6_dialog_content = "さっきの君の謝り方じゃ、\n謝ってないも同然だよ。",
  ui_story_5029_50290025_7_dialog_content = "犯人を捕まえたら、\nあの人にきちんと謝りに行こう。",
  ui_story_5029_50290025_8_dialog_content = "そういうことは捕まえてから考えるよ。",
  ui_story_5029_50290025_9_dialog_content = "で、どう？感知でアイツの居場所、分かる？",
  ui_story_5029_50290025_10_dialog_content = "…いや、ここは人が多すぎる…",
  ui_story_5029_50290025_11_dialog_content = "それもそうだろうね。\n港全体がお祭り騒ぎだもん。",
  ui_story_5029_50290025_12_dialog_content = "そこに目を付けて、\n人の多い場所に逃げ込んだんだろうね。",
  ui_story_5029_50290025_13_dialog_content = "とにかく、もう一度試してみるよ…",
  ui_story_5029_50290025_14_dialog_content = "うん！フィアもぼーっとしてられない！\nどこかにまだいないか、探してみるね。",
  ui_story_5029_50290025_15_dialog_content = "キャロ、行くよ！",
  ui_story_5029_50290025_16_dialog_content = "あれ？キャロ？",
  ui_story_5029_50290025_17_dialog_content = "ルル…ムシャムシャ。",
  ui_story_5029_50290025_18_dialog_content = "キャロ、なに食べてるの？",
  ui_story_5029_50290025_19_dialog_content = "ムシャムシャ…",
  ui_story_5029_50290025_20_dialog_content = "わっ、気持ち悪～い…",
  ui_story_5029_50290025_21_dialog_content = "キャロ、そんなの食べちゃダメだよ。\n毒があったらどうするの？",
  ui_story_5029_50290025_22_dialog_content = "アハハ、なにも知らないんだ。",
  ui_story_5029_50290025_23_dialog_content = "それ、海藻味のアイスだよ。見た目は悪いけど、\n涼しくなるし、ノドも乾かなくなるんだ！",
  ui_story_5029_50290025_24_dialog_content = "そ、それぐらい、あたしだって知ってるもん！",
  ui_story_5029_50290025_25_dialog_content = "…あれ？俺のアイス、どこいった…？",
  ui_story_5029_50290025_26_dialog_content = "まさか、お前のワンコが食ってたの、\n俺のアイスだったのか！？",
  ui_story_5029_50290025_27_dialog_content = "がんばって貯めたおこづかいで買ったアイスなんだぞ！\nベンショーしろよ！",
  ui_story_5029_50290025_28_dialog_content = "え、キャロがあんたのアイスを食べちゃったの？\nご、ごめんなさい…",
  ui_story_5029_50290025_X28_dialog_content = "謝って済むか！\nアイス5個分の金を払ってくれたら、許してやるよ。",
  ui_story_5029_50290025_X29_dialog_content = "でもあたし、お金なんて持ってないし…",
  ui_story_5029_50290025_X30_dialog_content = "そのワンコを売っちまえばいいだろ？",
  ui_story_5029_50290025_X31_dialog_content = "ちゃんとお金は払うよ…でも、キャロは売らない！\nあと、キャロはワンコじゃないよ。",
  ui_story_5029_50290025_29_dialog_content = "そいつが犬じゃねえってなら、\n犬はお前だ！",
  ui_story_5029_50290025_30_dialog_content = "あ、あたしも違うよ…",
  ui_story_5029_50290025_31_dialog_content = "いいや、違わない！\n他人のアイスを盗んで食べる犬っころだ！",
  ui_story_5029_50290025_32_dialog_content = "フィア、ネックレス、あげる。",
  ui_story_5029_50290025_33_dialog_content = "きっとよく似合うよ！",
  ui_story_5029_50290025_34_dialog_content = "ほんとに？ありがとう！\nじゃあ、今すぐつけてみるね！",
  ui_story_5029_50290025_35_dialog_content = "みんな～！早く早く！\nフィアが犬の首輪つけてるよ！",
  ui_story_5029_50290025_36_dialog_content = "やーい！犬だ、犬だ！",
  ui_story_5029_50290025_37_dialog_content = "フィアは…",
  ui_story_5029_50290025_38_dialog_content = "フィアは犬じゃないもん…",
  ui_story_5029_50290025_39_dialog_content = "泣いたってムダだぞ！\nさっさとアイス、ベンショーしろよ！",
  ui_story_5029_50290025_40_dialog_content = "ちょっと！\n小さい子になんてヒドいことするんだ！",
  ui_story_5029_50290025_41_dialog_content = "味方が増えたって、\n怖くなんかないぞ！",
  ui_story_5029_50290025_42_dialog_content = "こいつのワンコが俺のアイスを食っちまったんだ。\n被害者はこっちだぞ！",
  ui_story_5029_50290025_X42_dialog_content = "だったら、僕が代わりに謝るよ。\nごめん。",
  ui_story_5029_50290025_43_dialog_content = "ほら、これだけあれば、\n10個ぐらい買えるでしょ？",
  ui_story_5029_50290025_44_dialog_content = "それでいいんだよ…",
  ui_story_5029_50290025_45_dialog_content = "まだ話は終わってないよ。",
  ui_story_5029_50290025_46_dialog_content = "君だって、わざとじゃないって分かってるよね。\nどうして困らせるの？",
  ui_story_5029_50290025_47_dialog_content = "女の子をイジメて泣かせるなんて、\nそれでも男の子？",
  ui_story_5029_50290025_48_dialog_content = "…",
  ui_story_5029_50290025_49_dialog_content = "今度また誰かをイジメたら、\n簡単には見逃さないよ！",
  ui_story_5029_50290025_50_dialog_content = "分かった？",
  ui_story_5029_50290025_51_dialog_content = "わかった…",
  ui_story_5029_50290025_52_dialog_content = "だったら、もうこんなことしないって約束して。",
  ui_story_5029_50290025_53_dialog_content = "もうこんなことしない。",
  ui_story_5029_50290025_54_dialog_content = "ほら、フィア。もう大丈夫だよ。",
  ui_story_5029_50290025_55_dialog_content = "フィア、いつも怖いものなしでしょ。\nなんで男の子にちょっとイヤなことを言われたぐらいで…？",
  ui_story_5029_50290025_56_dialog_content = "君の師匠が…",
  ui_story_5029_50290025_57_dialog_content = "うわああああん…！",
  ui_story_5029_50290025_58_dialog_content = "PlayerName、遅い！",
  ui_story_5029_50290025_59_dialog_content = "えっ？",
  ui_story_5029_50290025_60_dialog_content = "あ…ごめんごめん、来るのが遅かったね。",
  ui_story_5029_50290025_61_dialog_content = "うわあああん！キャロは犬じゃないもん！\nフィアも犬じゃないもん！！",
  ui_story_5029_50290025_62_dialog_content = "キャロだってわざと食べたわけじゃないもん！\nあんなところにアイスを置いといたのがいけないんだ、\nうわあああ～ん！",
  ui_story_5029_50290025_X62_dialog_content = "ぐすっ…それにフィア、ちゃんと謝ったよ…",
  ui_story_5029_50290025_63_dialog_content = "分かってるよ、大丈夫だから。\nもう終わったことだよ。",
  ui_story_5029_50290025_64_dialog_content = "フィア、ああいうヘリクツ\n言ってくる子供が一番キライ！！",
  ui_story_5029_50290025_65_dialog_content = "自分だって子供じゃない…",
  ui_story_5029_50290025_66_dialog_content = "フィアは子供じゃないもん！\nもう大人だよ！！",
  ui_story_5029_50290025_67_dialog_content = "そ、それに…",
  ui_story_5029_50290025_68_dialog_content = "フィアは他の小さい子をイジメたり、笑ったりしないもん！\nうわあああ～ん！！",
  ui_story_5029_50290025_69_dialog_content = "ハハハ…分かってるよ。\n時どき大きい子はイジメてるけどね。",
  ui_story_5029_50290025_70_dialog_content = "そんなことないもん！",
  ui_story_5029_50290025_71_dialog_content = "ルルル！",
  ui_story_5029_50290025_72_dialog_content = "ほら、キャロが心配してる。",
  ui_story_5029_50290025_73_dialog_content = "どこかで座って話さない？",
  ui_story_5029_50290025_74_dialog_content = "うん…",
  ui_story_5029_50290025_75_dialog_content = "…もし、もしもの話だけど、\nフィアが本当に、あんたを怒らせたことがあるなら…",
  ui_story_5029_50290025_76_dialog_content = "フィア、ちゃんと謝るよ…",
  ui_story_5029_50290025_77_option_content = "大丈夫だよ！",
  ui_story_5029_50290025_78_dialog_content = "僕はずっと、フィアはいい子だって分かってる。",
  ui_story_5029_50290025_79_dialog_content = "口が悪くても、実際にやってることはいつだって\n皆を助けることだし、いつも皆のことを考えてる。",
  ui_story_5029_50290025_80_dialog_content = "今回だって、懸賞金を狙ってるのは\n師匠たちにプレゼントをあげるためでしょ？",
  ui_story_5029_50290025_81_dialog_content = "プレゼントはついでだよ。",
  ui_story_5029_50290025_82_dialog_content = "師匠が旅費をケチらなかったら、\nフィアもキャロもこんな苦労しなかったのに！",
  ui_story_5029_50290025_83_dialog_content = "…あんなふうに言われて泣くこともなかったのに…",
  ui_story_5029_50290025_84_dialog_content = "そうだ、PlayerName…\n約束して！",
  ui_story_5029_50290025_85_option_content = "どうしたの、急に？",
  ui_story_5029_50290025_86_dialog_content = "あたし、小さい頃…\n同い年の友だちと遊びたくて仕方なかったの。",
  ui_story_5029_50290025_87_dialog_content = "でも、みんなはあたしがからかいやすいって思って…\nそのうち、みんなにイジメられるようになったの。",
  ui_story_5029_50290025_88_dialog_content = "フィア、強いお兄ちゃんが欲しくてたまらなかったんだ。",
  ui_story_5029_50290025_89_dialog_content = "フィアをイジメる子たちを\nこらしめてくれたらいいのにって思ってた…",
  ui_story_5029_50290025_90_dialog_content = "それでいつか、その子たちに\nうらやましがられるような存在になりたいって思ってたんだよ。",
  ui_story_5029_50290025_91_dialog_content = "でも…",
  ui_story_5029_50290025_92_dialog_content = "フィアは家に隠れてることしかできなかった。",
  ui_story_5029_50290025_93_dialog_content = "イジメっ子たちに会っても、\nフィアはいつも気にしないふりしかできなかった。",
  ui_story_5029_50290025_94_dialog_content = "でも、そうすればするほど、\nみんながエスカレートしていって、フィア、辛くて…",
  ui_story_5029_50290025_95_dialog_content = "さっきの男の子に会って、\n昔を思い出しちゃったの。",
  ui_story_5029_50290025_96_dialog_content = "誰も助けてくれなかった時に戻ったって思った。",
  ui_story_5029_50290025_97_dialog_content = "でも、今日は違った。今日はフィアをかばって、\nフィアをイジメた子をこらしめてくれた人がいたんだよ！",
  ui_story_5029_50290025_98_dialog_content = "それがPlayerName…",
  ui_story_5029_50290025_99_dialog_content = "だから、もしPlayerNameがほんとに\nお兄ちゃんだったらいいのにって、つい思っちゃったんだ。",
  ui_story_5029_50290025_100_dialog_content = "小さい時からPlayerNameが側で守ってくれてたら、\nどんなによかったかなって思ったの。",
  ui_story_5029_50290025_101_dialog_content = "構わないよ。僕は君より年上だし、\n最初から君の「お兄ちゃん」でしょ。",
  ui_story_5029_50290025_102_dialog_content = "でも、フィアももう、\n昔の誰も頼れる人がいない子供じゃない。",
  ui_story_5029_50290025_103_dialog_content = "君は自分の力で、\n立派な珍獣マスターになったでしょ？",
  ui_story_5029_50290025_104_dialog_content = "同い年の子たちには、\nそんなことできっこないでしょ？",
  ui_story_5029_50290025_105_dialog_content = "…そんなことはどうでもいいの！",
  ui_story_5029_50290025_106_dialog_content = "とにかく、これからずっと、今日みたいにフィアを守って！\nフィアに辛い思いさせないで！",
  ui_story_5029_50290025_107_dialog_content = "分かった、約束するよ。",
  ui_story_5029_50290025_108_dialog_content = "絶対だよ？",
  ui_story_5029_50290025_109_dialog_content = "うん、絶対だ！",
  ui_story_5029_50290025_110_dialog_content = "PlayerName、お兄ちゃん…",
  ui_story_5029_50290025_111_dialog_content = "お兄ちゃんとしての最初のシゴトは――",
  ui_story_5029_50290025_112_dialog_content = "フィアが今日泣いてたって、\n他の人には内緒にすること！",
  ui_story_5029_50290025_113_dialog_content = "じゃないと、また笑われちゃう…",
  ui_story_5029_50290025_114_dialog_content = "約束するよ。絶対に誰にも言わない。",
  ui_story_5029_50290025_115_dialog_content = "はぁ、疲れた…",
  ui_story_5029_50290025_116_dialog_content = "それはそうだよ。\n泣くのも体力が必要だからね。",
  ui_story_5029_50290025_117_dialog_content = "でも…結局…",
  ui_story_5029_50290025_118_dialog_content = "犯人…逃がしちゃったね…",
  ui_story_5029_50290025_119_dialog_content = "大丈夫だよ、少なくとも銀の箱は取り返してる。",
  ui_story_5029_50290025_120_dialog_content = "すぅ…すぅ…",
  ui_story_5029_50290025_121_dialog_content = "フィア、座ったまま寝ちゃったの？",
  ui_story_5029_50290025_122_dialog_content = "（こんなに騒がしい場所なのに、\n気持ちよさそうに寝てるなぁ）",
  ui_story_5029_50290025_123_dialog_content = "（涙で濡れた服のすそも、\n夕日に照らされてゆっくり乾いていく…）",
  ui_story_5029_50290025_124_dialog_content = "（もし僕に妹がいたら、\n今はきっと、フィアくらいの歳だったかも…）",
  ui_story_5029_50290025_125_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5029_50290025_126_dialog_content = "おかえりなさいませ。",
  ui_story_5029_50290025_127_dialog_content = "僕の顔を見てがっかりなさいましたか？",
  ui_story_5029_50290025_128_dialog_content = "申し訳ありません、\nうっかりお2人の秘密をのぞいてしまったようです…",
  ui_story_5029_50290025_129_dialog_content = "ですが、そんなにガッカリすることはありませんよ。",
  ui_story_5029_50290025_130_dialog_content = "夢は現実をもとに造りあげられるものです。",
  ui_story_5029_50290025_131_dialog_content = "つまり…あなたと彼女の間は、\n現実世界でも同じような状態である可能性があるのです。",
  ui_story_5029_50290025_132_dialog_content = "ただ、夢の世界と異なることは…\n現実世界に、タネやしかけがないということです。",
  ui_story_5029_50290025_133_dialog_content = "僕が生み出す虚構の世界の中で生き続けるというのは…\nやはり難しいでしょうね。",
  ui_story_5029_50290025_134_dialog_content = "それでは、自ら書き上げられた結末に、\nご満足はいただけましたか？",
  ui_story_5029_50290025_135_dialog_content = "心残りはございませんか？",
  ui_story_5029_50290025_136_dialog_content = "僕が言いたいのは…\nまだ時間はあるということです。",
  ui_story_5029_50290025_137_dialog_content = "夢の中の、あの謎を解きたい、答えを知りたいと\nあなたがまだ思っていればの話ですが。",
  ui_story_5029_50290026_1_dialog_content = "（うう…）",
  ui_story_5029_50290026_2_dialog_content = "（ここは…エルビスさんの蔵書館だ）",
  ui_story_5029_50290026_3_dialog_content = "（どうして、また戻って来ちゃったんだ？）",
  ui_story_5029_50290026_4_dialog_content = "（あれ、おかしいな。どうして僕「また」って言ったんだろう）",
  ui_story_5029_50290026_5_dialog_content = "皆様はこの後、自由に屋敷の中を調べていただいて結構です。",
  ui_story_5029_50290026_6_dialog_content = "私はホールにおりますので、\n何かありましたら、いつでもお声がけください。",
  ui_story_5029_50290026_7_dialog_content = "（この言葉、もう聞いたことある気がする…）",
  ui_story_5029_50290026_8_option_content = "ゼインの所へ行く",
  ui_story_5029_50290026_9_option_content = "適当にブラブラする",
  ui_story_5029_50290026_10_dialog_content = "（ちがう！）",
  ui_story_5029_50290026_11_dialog_content = "（今はそんな選択をしてる場合じゃない）",
  ui_story_5029_50290026_12_dialog_content = "（このままじゃ、僕たちは真犯人を見つけられない）",
  ui_story_5029_50290026_13_dialog_content = "（犯人が見つからなかったら、エルビスさんに危険が及ぶかもしれない…\n僕も永遠にここで迷い続けるだけだ）",
  ui_story_5029_50290026_14_dialog_content = "（…あれ？「永遠に迷い続ける」？\n僕、何を言ってるんだろう？とにかく…）",
  ui_story_5029_50290026_15_option_content = "皆、早く来て！",
  ui_story_5029_50290026_16_option_content = "カレン、バイス、フィア！",
  ui_story_5029_50290026_17_dialog_content = "PlayerName、どうしたの？\n急にそんな大声出して。",
  ui_story_5029_50290026_18_dialog_content = "何か手がかりを見つけたの？",
  ui_story_5029_50290026_19_dialog_content = "話があるならさっさと話してよ！\nこっちはあと一歩ってとこなんだから！",
  ui_story_5029_50290026_20_dialog_content = "この事件はゲームじゃないし、競争でもない。",
  ui_story_5029_50290026_21_dialog_content = "だから、皆で協力して、一緒に調査しよう！",
  ui_story_5029_50290026_22_dialog_content = "なんで？そんなことしたら、\n懸賞金を分けないといけなくなるでしょ？",
  ui_story_5029_50290026_23_dialog_content = "PlayerName、もし一人で困ってるなら、\nいつでも私のところへ来てくれればいいのよ。",
  ui_story_5029_50290026_24_dialog_content = "いつでも歓迎するわ！",
  ui_story_5029_50290026_25_dialog_content = "みんな、僕の話を聞いて。\n本当に時間がないんだ…",
  ui_story_5029_50290026_26_dialog_content = "僕たちみんなが協力して犯人を見つけないと、\n大変なことになる。",
  ui_story_5029_50290026_27_dialog_content = "言われなくても分かっているわ。",
  ui_story_5029_50290026_28_dialog_content = "皆、僕を信じて。予感がするんだ。",
  ui_story_5029_50290026_29_dialog_content = "犯人がもうすぐ銀の箱を持って逃げ出す。\nバラバラじゃ、捕まえられないんだ。",
  ui_story_5029_50290026_30_dialog_content = "逃げられる前に犯人が誰か突き止めて、\n先に行動しなくちゃダメなんだ！",
  ui_story_5029_50290026_31_dialog_content = "なんであんたの予感なんて信じなきゃいけないの？",
  ui_story_5029_50290026_32_dialog_content = "フィア、カフェの床の隅にキャロを行かせちゃいけないよ。",
  ui_story_5029_50290026_33_dialog_content = "そこにいちごジャムのついたナイフが落ちてるんだ。\n気を付けないと、ケガするよ。",
  ui_story_5029_50290026_34_dialog_content = "そ、そうなの…？",
  ui_story_5029_50290026_35_dialog_content = "カレン、2階のデスクにボロボロの古い本があるんだ。",
  ui_story_5029_50290026_36_dialog_content = "手に取ろうとするとたぶん本が破けて、\nエルビスさんにどうお詫びしたらいいのか、悩むことになる。",
  ui_story_5029_50290026_37_dialog_content = "え…？",
  ui_story_5029_50290026_38_dialog_content = "バイス…君がきれいだと思ってるホールの花、\n毒があるんだ。近づかない方がいい。",
  ui_story_5029_50290026_39_dialog_content = "でも、口に入れなければ、大ごとにはならないよ。",
  ui_story_5029_50290026_40_dialog_content = "え？どうしてあの花が\n気になってたこと、知ってるの？",
  ui_story_5029_50290026_41_dialog_content = "よ、予感だよ。",
  ui_story_5029_50290026_42_dialog_content = "あたしたちが気付かないうちに、\nこのお屋敷全部、調べちゃったの？",
  ui_story_5029_50290026_43_dialog_content = "そう…いうことになるかもね。",
  ui_story_5029_50290026_44_dialog_content = "そう言いだした以上、完璧な計画があるのでしょうね？",
  ui_story_5029_50290026_45_dialog_content = "完璧とはいかないけど、僕の言った通りに動いてくれれば…",
  ui_story_5029_50290026_46_dialog_content = "<color=#828282>1時間後</color>",
  ui_story_5029_50290026_47_dialog_content = "本当にPlayerNameの言った通りだったわ。\n商談に来ていたのは、ジョムだった。",
  ui_story_5029_50290026_48_dialog_content = "PlayerNameに言われた通り、\nジョムにエルビスともう一度会う機会を作ると約束したわ。",
  ui_story_5029_50290026_49_dialog_content = "それで、知っていることは全部話してくれた。",
  ui_story_5029_50290026_50_dialog_content = "領主様がドアにカギをかけて立ち去った後、\nこっそりドアをこじ開けたんですよ。",
  ui_story_5029_50290026_51_dialog_content = "ヘヘ…ちょっと話はそれますが、\nドアを開けることに関しては、\nR・Wの中でも自信があるんです。",
  ui_story_5029_50290026_52_dialog_content = "それから、『赤浪サメ之助伝』を\n目立つ所に置いて立ち去りました。",
  ui_story_5029_50290026_53_dialog_content = "ええ、それから白夜城の公爵…バーバリーさんね。\n彼女が言うには…",
  ui_story_5029_50290026_54_dialog_content = "しばらく待っていたら、\n緑色の髪の背の低い男が、屋敷から出てきたわ。",
  ui_story_5029_50290026_55_dialog_content = "それから周りに人がいないことを確認して、\n中に入って失くした徽章を探した…",
  ui_story_5029_50290026_56_dialog_content = "でも、ずいぶん探したけど見つからなかったわ。\nその後、誰かが来たような音がしたから、その場を離れたの。",
  ui_story_5029_50290026_57_dialog_content = "その「誰か」って…「マナエ」だよね？\nえっと、あんたたちが「サナエ」って呼んでる人。その人は…",
  ui_story_5029_50290026_58_dialog_content = "と、扉に鍵がかかっていなかったので、\nそっと中に入りました…",
  ui_story_5029_50290026_59_dialog_content = "ソファーの下に隠した花瓶の破片を片付けて、\n新しい花瓶を置いて…",
  ui_story_5029_50290026_60_dialog_content = "誰にも見つからないと思っていたのですが、\n結局、クックさんに見つかってしまい…",
  ui_story_5029_50290026_61_dialog_content = "クックさんが誰にも言わないと約束してくれて、\n戸締りをしっかりするよう言われました…",
  ui_story_5029_50290026_62_dialog_content = "それでエルビスが戻った時には、\nドアも窓も鍵がかかっていたのね…",
  ui_story_5029_50290026_63_dialog_content = "屋敷に出入りした順序は、それで間違いなさそうだ。",
  ui_story_5029_50290026_64_dialog_content = "さっき目撃者3人に聞いたんだ。\nそれで証明できる。",
  ui_story_5029_50290026_65_dialog_content = "領主様がカギをかけてちょっとしたら、\n緑色の髪のお兄ちゃんがまた戻ってきたんだ。",
  ui_story_5029_50290026_66_dialog_content = "夕飯時…確かにとても美しい貴族の女性をお見かけしました。",
  ui_story_5029_50290026_67_dialog_content = "「マナエ」がこっそり領主様の書斎に入っていくのを見ましてね。\n怪しいと思っていました。",
  ui_story_5029_50290026_68_dialog_content = "PlayerNameの予感ってすごいな～。",
  ui_story_5029_50290026_69_dialog_content = "3人が誰か当てただけじゃなくて、\n目撃者まで見つけるなんて…？",
  ui_story_5029_50290026_70_dialog_content = "事情は聞き出せたけれど、\n結果として、捜査は振り出しに戻ってしまったわね。",
  ui_story_5029_50290026_71_dialog_content = "3人とも一人ずつ、連続して\n書斎に入っている…",
  ui_story_5029_50290026_72_dialog_content = "ということは、犯人はやっぱり\n3人の中にいるってことになるかしら…",
  ui_story_5029_50290026_73_dialog_content = "でも、PlayerNameはその3人を\n疑いたくはないようね。",
  ui_story_5029_50290026_74_dialog_content = "ううん、4人目はいないの？",
  ui_story_5029_50290026_75_dialog_content = "4人目…？",
  ui_story_5029_50290026_76_dialog_content = "その可能性はあるわ。",
  ui_story_5029_50290026_77_dialog_content = "例えば、ずっと私たちの側にいたために、\n私たちが疑いもしなかった人物…",
  ui_story_5029_50290026_78_dialog_content = "フィア、昨日キャロが何か\n金属を盗み食いしてなかった？",
  ui_story_5029_50290026_79_dialog_content = "ルルルル？",
  ui_story_5029_50290026_80_dialog_content = "キャロはそんなおバカさんじゃないよ！",
  ui_story_5029_50290026_81_dialog_content = "犯人はゼインって人じゃないの？",
  ui_story_5029_50290026_82_dialog_content = "ゼイン？そんなはずないでしょ？",
  ui_story_5029_50290026_83_dialog_content = "可能性がない人ほど、可能性があるんだよ！",
  ui_story_5029_50290026_84_dialog_content = "スキがなく組み立てられた推理の鎖は、\n1つでも掛け違うと、鎖全体が動かなくなるもの…",
  ui_story_5029_50290026_85_dialog_content = "きっと、どこか見落としてるところがあるんだ。",
  ui_story_5029_50290026_86_dialog_content = "すでに目に入っているのに、気付いていない何かが…",
  ui_story_5029_50290026_87_dialog_content = "ゼインおじさんに聞いてみる気はないの？",
  ui_story_5029_50290026_88_dialog_content = "疑ってるの、まさか、\nあたしだけじゃないよね？",
  ui_story_5029_50290026_89_dialog_content = "「疑う」…",
  ui_story_5029_50290026_90_dialog_content = "…サナエ？",
  ui_story_5029_50290026_91_dialog_content = "PlayerName、やっぱりサナエが怪しいと思ってるの？",
  ui_story_5029_50290026_92_dialog_content = "僕じゃないよ…",
  ui_story_5029_50290026_93_dialog_content = "でも、僕にそのことを強調した人がいる。",
  ui_story_5029_50290026_94_dialog_content = "ルルル！",
  ui_story_5029_50290026_95_dialog_content = "キャロ、窓際でなにを見てるの？",
  ui_story_5029_50290026_96_dialog_content = "外には木しかないよ…",
  ui_story_5029_50290026_97_dialog_content = "（マズい、犯人がもう動き出した！？）",
  ui_story_5029_50290026_98_dialog_content = "あれ？みんな、見て。\n外にいるあの人、なんかおかしいよ！",
  ui_story_5029_50290027_1_dialog_content = "（やっぱり、間に合わなかったか…）",
  ui_story_5029_50290027_2_dialog_content = "（いや、まだチャンスはある！）",
  ui_story_5029_50290027_3_dialog_content = "（皆で力を合わせれば、\n今度こそきっとうまく行く！）",
  ui_story_5029_50290027_4_dialog_content = "（深呼吸して…早く方法を考えるんだ。\n犯人を捕まえる方法を…）",
  ui_story_5029_50290027_5_dialog_content = "あの人、確かに怪しいわね。\nこんな暑い日にずいぶん着込んでる。",
  ui_story_5029_50290027_6_dialog_content = "何かを掘っているようね？",
  ui_story_5029_50290027_7_dialog_content = "（「掘ってる」…）",
  ui_story_5029_50290027_8_dialog_content = "（そういうことか！犯人はずっと、\n盗んだものを庭の土の中に隠してたんだ）",
  ui_story_5029_50290027_9_dialog_content = "皆、聞いて！そいつが銀の箱を盗んだ犯人だ！",
  ui_story_5029_50290027_10_dialog_content = "土の中に埋めておいた銀の箱を掘りだして、\n逃げるつもりだ！",
  ui_story_5029_50290027_11_dialog_content = "なら、なにをモタモタしてるの！？\n早く捕まえなきゃ！",
  ui_story_5029_50290027_12_dialog_content = "フィア、待ちなさい。",
  ui_story_5029_50290027_13_dialog_content = "PlayerName、準備はできた？",
  ui_story_5029_50290027_14_dialog_content = "皆…？",
  ui_story_5029_50290027_15_dialog_content = "あなたが力を合わせろと言ったのよ？",
  ui_story_5029_50290027_16_dialog_content = "暗鬼との戦いじゃないけど、\nチームの指揮ときたら、\nあなたが一番得意でしょ？",
  ui_story_5029_50290027_17_dialog_content = "うん…よし！",
  ui_story_5029_50290027_18_dialog_content = "フィア、キャロを連れて、\n裏山に通じる道を塞いでおいて。",
  ui_story_5029_50290027_19_dialog_content = "山道に逃げられたら、\n追いかけるのが大変になる。",
  ui_story_5029_50290027_20_dialog_content = "わかった！",
  ui_story_5029_50290027_21_dialog_content = "バイス、カレンは\nそれぞれ左右に分かれて。",
  ui_story_5029_50290027_22_dialog_content = "何かあった時のために、\n武器も忘れずに持って行って。",
  ui_story_5029_50290027_23_dialog_content = "来た道を戻られないように、\n僕は真後ろから犯人を追う。",
  ui_story_5029_50290027_24_dialog_content = "了解！",
  ui_story_5029_50290027_25_dialog_content = "今度こそ…逃がさないぞ！",
  ui_story_5029_50290027_26_dialog_content = "どんな状況？",
  ui_story_5029_50290027_27_dialog_content = "うまくいったよ！\n犯人は港に向かって逃げてる。",
  ui_story_5029_50290027_28_dialog_content = "ふぅ…本当に逃げ足が速いなぁ。",
  ui_story_5029_50290027_29_dialog_content = "心配いらないよ、\nフィアがマーキング銃持ってるから！",
  ui_story_5029_50290027_30_dialog_content = "あたしが犯人に当てるから、\n銀の箱を持っていかれないように足止めして！",
  ui_story_5029_50290027_31_dialog_content = "ルルル！",
  ui_story_5029_50290027_32_dialog_content = "あれ…？\nこういうこと言うの、初めてじゃない気がする…",
  ui_story_5029_50290027_33_dialog_content = "まぁいっか！必殺ショット…バシューン！！",
  ui_story_5029_50290027_34_dialog_content = "…？",
  ui_story_5029_50290027_35_dialog_content = "ル…ルルル！！！",
  ui_story_5029_50290027_36_dialog_content = "そう、その調子だよ、キャロ！\n追いついて、手にガブッとかみついて！",
  ui_story_5029_50290027_37_dialog_content = "ルルル～！",
  ui_story_5029_50290027_38_dialog_content = "あ…銀の箱を投げてきた！",
  ui_story_5029_50290027_39_dialog_content = "キャロ、気を付けて！",
  ui_story_5029_50290027_40_dialog_content = "<color=#828282>ドンッ！</color>",
  ui_story_5029_50290027_41_dialog_content = "あら…この箱、ほんとに重いわね。",
  ui_story_5029_50290027_42_dialog_content = "バイスお姉ちゃんが\n銀の箱を受け止めた！？",
  ui_story_5029_50290027_43_dialog_content = "キャロ、これ、大切に持っててね。\nこの後は、私とカレンに任せて。",
  ui_story_5029_50290027_44_dialog_content = "バイス、急いで。\nもうずいぶん離されたわ。",
  ui_story_5029_50290027_45_dialog_content = "大丈夫よ、狙撃は得意だから！",
  ui_story_5029_50290027_46_dialog_content = "ターゲット追跡！",
  ui_story_5029_50290027_47_dialog_content = "うぐっ…",
  ui_story_5029_50290027_48_dialog_content = "バイスお姉ちゃん、すご～い！",
  ui_story_5029_50290027_49_dialog_content = "…バイス、ケガさせないように手加減したね？",
  ui_story_5029_50290027_50_dialog_content = "まだ起き上がろうとしてるみたいだ。",
  ui_story_5029_50290027_51_dialog_content = "もう逃げられないよ！\nカレンお姉ちゃんが追い付いてる！",
  ui_story_5029_50290027_52_dialog_content = "往生際が悪いわね。\nまだ逃げるつもり？",
  ui_story_5029_50290027_53_dialog_content = "なにっ！？",
  ui_story_5029_50290027_54_dialog_content = "我がランスのもとに、影は無し！",
  ui_story_5029_50290027_55_dialog_content = "うっ…",
  ui_story_5029_50290027_56_dialog_content = "やっと…",
  ui_story_5029_50290027_57_dialog_content = "犯人を捕まえられた…？",
  ui_story_5029_50290027_58_dialog_content = "バイス、やったわね。",
  ui_story_5029_50290027_59_dialog_content = "フフ、カレンこそ。",
  ui_story_5029_50290027_60_dialog_content = "あの距離で命中させるなんて、\n本当に素晴らしい腕だわ。",
  ui_story_5029_50290027_61_dialog_content = "足がとにかく速かったわ…",
  ui_story_5029_50290027_62_dialog_content = "カレンがいてくれてよかった。\nさすがは白夜城を守ってるだけあるわ！",
  ui_story_5029_50290027_63_dialog_content = "あなたがいれば、どんな犯人も逃げられないでしょうね。",
  ui_story_5029_50290027_64_dialog_content = "その程度にしておいて…\nそれ以上言われたら、全身に鳥肌が立ちそうよ。",
  ui_story_5029_50290027_65_dialog_content = "ほめてるのよ？\n別に恥ずかしがらなくていいのに。",
  ui_story_5029_50290027_66_dialog_content = "私はカレンのほめ言葉、\n全部素直に受け取ったわよ？",
  ui_story_5029_50290027_67_dialog_content = "バイスお姉ちゃん、カレンお姉ちゃん、待って…\nあたしもいるの忘れないで！",
  ui_story_5029_50290027_68_dialog_content = "もちろん、忘れてないわ。",
  ui_story_5029_50290027_69_dialog_content = "あなたが裏山に通じる道を塞いでいてくれたから、\nうまく行ったのだもの。",
  ui_story_5029_50290027_70_dialog_content = "エヘヘ、フィアも役に立てた…",
  ui_story_5029_50290027_71_dialog_content = "でも、一番大事な人を忘れちゃいけないわ。",
  ui_story_5029_50290027_72_dialog_content = "私たちだけでは、庭の人影が犯人だとは、\nまったく気づかなかったでしょうね。",
  ui_story_5029_50290027_73_dialog_content = "キャロ、バイスお姉ちゃんと\nカレンお姉ちゃんがほめてくれたよ！",
  ui_story_5029_50290027_74_dialog_content = "ル…？",
  ui_story_5029_50290027_75_dialog_content = "ええ、確かにそうよね。",
  ui_story_5029_50290027_76_dialog_content = "キャロもありがとう。\n今晩おいしいものを食べに連れてってあげるわ！",
  ui_story_5029_50290027_77_dialog_content = "ルルル～！",
  ui_story_5029_50290027_78_dialog_content = "あれ？PlayerName、\n犯人と何を話してるんだろう？",
  ui_story_5029_50290027_79_dialog_content = "本当にあなたが…？",
  ui_story_5029_50290027_80_dialog_content = "フン…",
  ui_story_5029_50290027_81_dialog_content = "だから、色々と手を尽くして、\n僕が他の人を疑うように仕向けたんですね。",
  ui_story_5029_50290027_82_dialog_content = "それもこれも全部、\n銀の箱を盗むためだけに？",
  ui_story_5029_50290027_83_dialog_content = "…",
  ui_story_5029_50290027_84_dialog_content = "PlayerName、ありがとう。\n今日の成功はあなたの計画のおかげよ。",
  ui_story_5029_50290027_85_dialog_content = "そうね。",
  ui_story_5029_50290027_85X1_dialog_content = "一番大事な時にあなたが皆をまとめてくれなかったら、\n犯人を捕まえることなんて到底できなかったわ。",
  ui_story_5029_50290027_86_dialog_content = "でも、やはり腑に落ちないわね。\nあの時、私たちはただ、庭にいる人物が怪しいと思っただけ…",
  ui_story_5029_50290027_87_dialog_content = "どうしてそれが銀の箱を盗んだ犯人だと分かったの？\nまさか、それも予感かしら？",
  ui_story_5029_50290027_88_dialog_content = "アハハ、経験を積んでたってところかな…",
  ui_story_5029_50290027_89_dialog_content = "え？",
  ui_story_5029_50290027_90_dialog_content = "フィア、誰なのか興味あるな～。\nやっぱりゼインおじさん！？",
  ui_story_5029_50290027_91_dialog_content = "PlayerName、さっきサナエがどうって言ってたわね。",
  ui_story_5029_50290027_92_dialog_content = "仮面で顔を隠してるけど、\nサナエってことはあり得ないでしょ？",
  ui_story_5029_50290027_93_dialog_content = "僕がサナエを疑うように仕向けた人物…\nそれが犯人だよ。",
  ui_story_5029_50290027_94_dialog_content = "つまり、お屋敷の使用人、\nサナエが書斎に入るところを目撃した人物――",
  ui_story_5029_50290027_95_dialog_content = "クックさん…いや、クック。",
  ui_story_5029_50290027_96_dialog_content = "…",
  ui_story_5029_50290028_1_dialog_content = "クック？",
  ui_story_5029_50290028_2_dialog_content = "サナエからその名前、聞いたよ。",
  ui_story_5029_50290028_3_dialog_content = "サナエに書斎の戸締りをしっかりするように言ったって。\nなんか、いいおじさんっぽい感じがしたけど。",
  ui_story_5029_50290028_4_dialog_content = "サナエ、どこで会ったか言ってなかった？",
  ui_story_5029_50290028_5_dialog_content = "たしか、書斎…あれ？",
  ui_story_5029_50290028_6_dialog_content = "その人こそ書斎に入った4人目の人物なんだ。",
  ui_story_5029_50290028_7_dialog_content = "僕はやってはいけないミスをしてたんだ――\n無意識に、目撃者を容疑者から外してた。",
  ui_story_5029_50290028_8_dialog_content = "では、そこに縛り付けられているのは\nクックだとおっしゃるのですか？",
  ui_story_5029_50290028_9_dialog_content = "わ、領主のおじさん！",
  ui_story_5029_50290028_10_dialog_content = "僕はただ、推理を話してるだけです。",
  ui_story_5029_50290028_11_dialog_content = "犯人の顔はまだ見てないので…",
  ui_story_5029_50290028_12_dialog_content = "構いませんよ。\n私もPlayerNameさんの推理を拝聴したいところです。",
  ui_story_5029_50290028_13_dialog_content = "僕の予想が間違っていなければ…",
  ui_story_5029_50290028_14_dialog_content = "<color=#828282>ギィ…</color>",
  ui_story_5029_50290028_15_dialog_content = "誰か来たようね…",
  ui_story_5029_50290028_16_dialog_content = "また日を改めて探しにきましょう。",
  ui_story_5029_50290028_17_dialog_content = "…ハハハハ、天の助けだ！",
  ui_story_5029_50290028_18_dialog_content = "新聞を届けるだけのつもりだったが、\n領主は不在で、書斎の鍵もかかっていない…",
  ui_story_5029_50290028_19_dialog_content = "領主の宝を手に入れるチャンスだ！",
  ui_story_5029_50290028_20_dialog_content = "<color=#828282>ギィ…</color>",
  ui_story_5029_50290028_21_dialog_content = "誰だ！？",
  ui_story_5029_50290028_22_dialog_content = "…あいつか。ハハハ、あの小娘ならごまかすのは簡単だ。",
  ui_story_5029_50290028_23_dialog_content = "だが、銀の箱を抱えているのを\n見られるわけにはいかない…",
  ui_story_5029_50290028_24_dialog_content = "窓から投げ捨てて、あとで拾うとするか。",
  ui_story_5029_50290028_25_dialog_content = "<color=#828282>ドンッ！</color>",
  ui_story_5029_50290028_26_dialog_content = "（チッ…窓際の鉢植えにぶつけちまった）",
  ui_story_5029_50290028_27_dialog_content = "あれ、何の音でしょう？",
  ui_story_5029_50290028_28_dialog_content = "こんな遅くに領主様の書斎で、\n何をしているのですか？",
  ui_story_5029_50290028_29_dialog_content = "わ、私は…",
  ui_story_5029_50290028_30_dialog_content = "また、領主様のものを壊したのですね？",
  ui_story_5029_50290028_31_dialog_content = "あ、新しいのを買ってきました…\n皆さんには、何の損失もありませんので…",
  ui_story_5029_50290028_32_dialog_content = "お願いです、領主様とメイド長には\n言わないでください…",
  ui_story_5029_50290028_33_dialog_content = "じゃないと、ク、クビになってしまいます…",
  ui_story_5029_50290028_34_dialog_content = "ううん…新しいものを買って来たというのなら、\n他の人は気付かないかもしれませんね。",
  ui_story_5029_50290028_35_dialog_content = "えっ？",
  ui_story_5029_50290028_36_dialog_content = "見なかったことにしてあげましょう。",
  ui_story_5029_50290028_37_dialog_content = "ただ、この書斎の戸締りをしっかりしておくんですよ。",
  ui_story_5029_50290028_38_dialog_content = "つまり、バーバリーさんの後にサナエじゃなくて\nクックが書斎に入ってたのね！",
  ui_story_5029_50290028_39_dialog_content = "あのバカ娘、最後に床掃除までしてくれてな。\n俺の足跡を消してくれたんだ。",
  ui_story_5029_50290028_40_dialog_content = "ハハハハ、あと少しでうまくいったのにな！",
  ui_story_5029_50290028_41_dialog_content = "この声は…",
  ui_story_5029_50290028_42_dialog_content = "…",
  ui_story_5029_50290028_43_dialog_content = "クック、本当にお前なのか！？",
  ui_story_5029_50290028_44_dialog_content = "PlayerNameの言った通りだ！\n本当に名探偵だったの！？",
  ui_story_5029_50290028_45_dialog_content = "今日、俺があわてて逃げたりしなかったら、\nお前たちは一生犯人が誰だか知ることはなかっただろう！",
  ui_story_5029_50290028_46_dialog_content = "いいえ、あなたは手がかりを残していました！",
  ui_story_5029_50290028_47_dialog_content = "そんなはずはない！",
  ui_story_5029_50290028_48_dialog_content = "カフェにあった新聞を忘れていませんか？",
  ui_story_5029_50290028_49_dialog_content = "エルビスさんはきのう、一日中お客さんに会っていた。\n新聞は受け取っていないはずです。",
  ui_story_5029_50290028_50_dialog_content = "なのに、昨日の新聞がどうしてカフェにあったのか…",
  ui_story_5029_50290028_51_dialog_content = "…",
  ui_story_5029_50290028_52_dialog_content = "最初にあなたと会った時、不思議に思ったんです。",
  ui_story_5029_50290028_53_dialog_content = "足を悪くしたって言ってる人の靴に\nどうして泥がついているんだろうって。",
  ui_story_5029_50290028_54_dialog_content = "今思えば、あなたは疑いをそらすために、\n夜通しで銀の箱を庭に埋めてたんですね。",
  ui_story_5029_50290028_54X1_dialog_content = "だから、靴に泥がついていたんです。",
  ui_story_5029_50290028_55_dialog_content = "これだけ証拠があれば、あなたが犯人だと分かるのは\n時間の問題だったでしょう。",
  ui_story_5029_50290028_56_dialog_content = "残念なのは…もう少し早く推理ができていれば、\nこんな騒ぎを起こすこともなかったはず。",
  ui_story_5029_50290028_57_dialog_content = "クック、足のケガはまだ\n治っていないのではなかったか？",
  ui_story_5029_50290028_58_dialog_content = "俺に一番に聞きたいことがそれか？",
  ui_story_5029_50290028_59_dialog_content = "フン、お前への恨みがなかったら、\n俺の足はこんなに早く良くならなかっただろうよ。",
  ui_story_5029_50290028_60_dialog_content = "教えてやる！今まで足が悪いフリをしてたのは、\n宝を盗んだ後に疑いをかけられないようにするためさ！",
  ui_story_5029_50290028_61_dialog_content = "私には分からない。なぜそんなことを…",
  ui_story_5029_50290028_62_dialog_content = "金が必要なら、そう話してくれればよかったのだ。",
  ui_story_5029_50290028_63_dialog_content = "善人のフリはよせ！\n金の問題じゃない！",
  ui_story_5029_50290028_64_dialog_content = "俺はただ、お前が一番大切にしてるものを盗んで、\n失うことの痛みを味わせてやりたかっただけだ。",
  ui_story_5029_50290028_65_dialog_content = "クック、領主様がお前に何をしたというのだ。",
  ui_story_5029_50290028_66_dialog_content = "ケガをした後も、ゆっくり休養を取らせてやっていただろう。\nなぜこんなことをした？",
  ui_story_5029_50290028_67_dialog_content = "ハハハ…ハハハハハ！！",
  ui_story_5029_50290028_68_dialog_content = "我が家は代々領主一家に仕え、懸命に尽くしてきた。",
  ui_story_5029_50290028_69_dialog_content = "俺だって、お前たちに何も悪いことはしちゃいない。\nそれなのに、なんだ？",
  ui_story_5029_50290028_70_dialog_content = "俺がケガをしたのは\nお前を救うためにガケから落ちたせいだって言うのに…",
  ui_story_5029_50290028_71_dialog_content = "すぐにゼインなんてヤツを俺の後釜に据えやがって！！",
  ui_story_5029_50290028_72_dialog_content = "そして俺はメイドたちの雑用の手伝いだ…\nそれだけなら、まだガマンもできた。",
  ui_story_5029_50290028_73_dialog_content = "だが、それだけじゃ飽き足らず、\n俺を野良犬同然に追い出そうとしていただろう？",
  ui_story_5029_50290028_74_dialog_content = "そのようなことはしない。",
  ui_story_5029_50290028_75_dialog_content = "俺はこの耳で聞いたんだ！メイド長に話してただろ。\n俺がいなくなったら、俺の部屋をゼインに使わせると…",
  ui_story_5029_50290028_76_dialog_content = "俺の家は代々忠誠を誓ってきたっていうのに、\nこんな仕打ちがあるか！？",
  ui_story_5029_50290028_77_dialog_content = "お前は誤解している…",
  ui_story_5029_50290028_78_dialog_content = "ゼイン、そうあせるな！\nお前も遅かれ早かれ俺と同じ扱いを受けるさ、アハハハ！",
  ui_story_5029_50290028_79_dialog_content = "そうか…",
  ui_story_5029_50290028_80_dialog_content = "エルビスさん、本当なんですか…？",
  ui_story_5029_50290028_81_dialog_content = "事実であると同時に、\n事実ではありません。",
  ui_story_5029_50290028_82_dialog_content = "クック、お前は走るのが得意だったな。\nだが、ケガをして、おそらく一生歩くことも\n不自由になってしまった。",
  ui_story_5029_50290028_83_dialog_content = "だから、ずっと申し訳なく思っていたのだ。",
  ui_story_5029_50290028_84_dialog_content = "お前は忠誠心があり、勇敢だ。\nだが、それよりもずっと賢く、実行力もある。",
  ui_story_5029_50290028_85_dialog_content = "私の一族に縛られていなければ、\n商売の世界で大きな成功を収めることもできるだろう。",
  ui_story_5029_50290028_86_dialog_content = "だから私は、お前に投資して\n商売の世界に飛び込んでもらおうと考えていたのだ。",
  ui_story_5029_50290028_87_dialog_content = "もっと早くに話しておくべきだったな…",
  ui_story_5029_50290028_88_dialog_content = "な、何を訳の分からないことを言ってやがる！？",
  ui_story_5029_50290028_89_dialog_content = "そ…そんな…そんなはずはない！",
  ui_story_5029_50290028_90_dialog_content = "全部、俺の誤解だったというのか？",
  ui_story_5029_50290028_91_dialog_content = "そんなはずは…！",
  ui_story_5029_50290028_92_dialog_content = "俺のことなど見てもいなかったくせに、\n俺のためにいろいろ考えていたと言うのか？",
  ui_story_5029_50290028_93_dialog_content = "そんなウソが俺に通用すると思うな！",
  ui_story_5029_50290028_94_dialog_content = "お前は自分の都合いいように\n話を作っているだけだ！",
  ui_story_5029_50290028_95_dialog_content = "そうか、白夜城の姫の前で、\nそんなことは認められないという訳だな？",
  ui_story_5029_50290028_96_dialog_content = "だから、筋の通らない言い訳をしてるんだろう？",
  ui_story_5029_50290028_97_dialog_content = "領主様の言われたことは本当だ。\n私が証明できる。",
  ui_story_5029_50290028_98_dialog_content = "黙れ！",
  ui_story_5029_50290028_99_dialog_content = "この私が人を見誤るとはな…",
  ui_story_5029_50290028_100_dialog_content = "クッ…",
  ui_story_5029_50290028_101_dialog_content = "その心の狭さでは、ビジネスには不向きだ。",
  ui_story_5029_50290028_102_dialog_content = "俺がどんな道を選ぼうと、\nつべこべ言われる筋合いはない！",
  ui_story_5029_50290028_103_dialog_content = "長い間精一杯仕えて来たのに、\nこの期に及んで、俺をだまそうとするなんて…",
  ui_story_5029_50290028_104_dialog_content = "フ…アハハハハ！",
  ui_story_5029_50290028_105_dialog_content = "そんなデタラメ、信じられるものか！",
  ui_story_5029_50290028_106_dialog_content = "ぺっ！",
  ui_story_5029_50290028_107_dialog_content = "貴様…いつか必ず後悔するぞ。",
  ui_story_5029_50290028_108_dialog_content = "人だかりが集まってきた。",
  ui_story_5029_50290028_109_dialog_content = "ゼイン、クックを連れて先に戻れ。",
  ui_story_5029_50290028_110_dialog_content = "はっ！",
  ui_story_5029_50290028_111_dialog_content = "エルビスさん、わざわざすみません…",
  ui_story_5029_50290028_112_dialog_content = "真実はどうあれ、銀の箱を見つけて\nクックを捕まえて下さったことに感謝いたします。",
  ui_story_5029_50290028_113_dialog_content = "そうだ、この箱、お返ししないと。",
  ui_story_5029_50290028_114_dialog_content = "転んだ勢いで鍵が壊れてしまったみたいなんです。\n中身がなくなっていないか、確認してください。",
  ui_story_5029_50290028_115_dialog_content = "ありがとうございます。",
  ui_story_5029_50290028_116_dialog_content = "<color=#828282>カチャ</color>",
  ui_story_5029_50290028_117_dialog_content = "間違いありません、中身はきちんと入っています。",
  ui_story_5029_50290028_118_dialog_content = "<color=#828282>ヒュゥ――</color>",
  ui_story_5029_50290028_119_dialog_content = "あ、何か風で…",
  ui_story_5029_50290028_120_dialog_content = "拾ってきます！",
  ui_story_5029_50290028_121_dialog_content = "これは…",
  ui_story_5029_50290028_122_dialog_content = "単なる古い絵ですよ。",
  ui_story_5029_50290028_123_dialog_content = "一番大切にしてる箱に入れていたからには、\nこの絵も大切なものなんですよね？",
  ui_story_5029_50290028_124_dialog_content = "ええ。",
  ui_story_5029_50290028_125_dialog_content = "もう戻ることはできない昔のものです。",
  ui_story_5029_50290028_126_dialog_content = "…いえ、この話は止めておきましょう。",
  ui_story_5029_50290028_127_dialog_content = "カレン殿下、PlayerNameさん、バイスさん、それからフィアさん。\nありがとうございました。",
  ui_story_5029_50290028_128_dialog_content = "我が家でハーバーシティならではの晩さん会が開かれます。\n差し支えなければ、皆さんもぜひ、おいでください。",
  ui_story_5029_50290028_129_dialog_content = "ふうん…なにか値打ちものが入ってると思ってたのに。",
  ui_story_5029_50290028_130_dialog_content = "ただの絵？よく分かんないな。",
  ui_story_5029_50290028_131_dialog_content = "フィアちゃんだったら、師匠の本を入れるのかしら？",
  ui_story_5029_50290028_132_dialog_content = "そんなわけないでしょ。\n本を入れるなら、自分のを入れる！",
  ui_story_5029_50290028_133_dialog_content = "この絵に描かれた人…どこか見覚えがある。",
  ui_story_5029_50290028_134_dialog_content = "PlayerName、事件はもう終わったのよ。\n今は考えるのを止めましょう。",
  ui_story_5029_50290028_135_dialog_content = "事件のことはエルビスがきちんと処理するはずよ。",
  ui_story_5029_50290028_136_dialog_content = "それから…",
  ui_story_5029_50290028_137_dialog_content = "この近くの山の上に展望台があると聞いたの。\nもう長い間放置されているけど、見晴らしがいいそうよ。",
  ui_story_5029_50290028_138_dialog_content = "皆で見に行かない？",
  ui_story_5029_50290028_139_dialog_content = "ええ？気を休めるなら身体を動かすのが一番よ！",
  ui_story_5029_50290028_140_dialog_content = "この山の裏に芝生があって、\nジョギングに最適らしいわ！",
  ui_story_5029_50290028_141_dialog_content = "PlayerName、行くわよ！\n一日でも訓練をなまけちゃいけないわ。",
  ui_story_5029_50290028_142_dialog_content = "待って待って！あっちのグルメフェアに\nたくさん人が行ってるの！",
  ui_story_5029_50290028_143_dialog_content = "夜はもっとにぎやかになるんだって！",
  ui_story_5029_50290028_144_dialog_content = "PlayerName、あたしとキャロに\nおいしいもの食べさせてくれるって、約束したでしょ？",
  ui_story_5029_50290028_145_dialog_content = "グルメフェア、行こうよ～！",
  ui_story_5029_50290028_146_dialog_content = "ジョギングしましょ！",
  ui_story_5029_50290028_147_dialog_content = "展望台で景色を眺めましょう！",
  ui_story_5029_50290028_148_dialog_content = "ええっ…",
  ui_story_5029_50290028_149_dialog_content = "ええと……",
  ui_story_5029_50290028_150_dialog_content = "どうしよう…",
  ui_story_5029_50290028_151_dialog_content = "<color=#828282>チリン――</color>",
  ui_story_5029_50290028_152_dialog_content = "おかえりなさいませ。",
  ui_story_5029_50290028_153_dialog_content = "こよいのひととき、無駄にはなさいませんでしたね。",
  ui_story_5029_50290028_154_dialog_content = "おめでとうございます。\nあなたは夢の中の謎を見事解き明かしました。",
  ui_story_5029_50290028_155_dialog_content = "…なぜ、そのように驚いたお顔で\n僕を見ているのですか？",
  ui_story_5029_50290028_156_dialog_content = "僕があなたの夢を利用したと、\n思っていらっしゃるのですか？",
  ui_story_5029_50290028_157_dialog_content = "もし、そのようにお考えなら…",
  ui_story_5029_50290028_158_dialog_content = "なぜ<color=#793f76>はじめに戻って</color>、\n僕の誘いをお断りにならなかったのです？",
  ui_story_5029_50290028_159_dialog_content = "そうは言っても、僕のマジックで作り出した夢から\n逃れられる者は、この世にそう多くおりませんがね。",
  ui_story_5029_50290028_160_dialog_content = "事ここに至っては、あなたはもはや、\n「ジェノが干渉した未来」を受け入れるしかないのです。",
  ui_story_5029_50290028_161_dialog_content = "それに…夜明けが近づいています。",
  ui_story_5029_50290028_162_dialog_content = "占いも、ここまでといたしましょう。",
  ui_story_5029_50290028_163_dialog_content = "どうあろうと、忘れてはいけませんよ…",
  ui_story_5029_50290028_164_dialog_content = "奇跡は、すぐ側にあるのです。"
}
return config
